INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M1-1-u4-C1','math',1,1,'u4',2,'길이 비교하기 — 한쪽 끝을 맞추어 다른 쪽 끝을 보고 「더 길다·더 짧다」로 말하기, 구부러진 것은 펴서·굵기와 상관없이 견주기',ARRAY['2수03-06']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M1-1-u4-C2','math',1,1,'u4',3,'무게 비교하기 — 손으로 들거나 양팔저울에 올려 내려간 쪽이 「더 무겁다」, 크기만 보고 무게를 단정하지 않기',ARRAY['2수03-06']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M1-1-u4-C3','math',1,1,'u4',4,'넓이 비교하기 — 겹쳐 보거나 같은 칸 수를 세어 「더 넓다·더 좁다」로 말하기, 한 변의 길이만 보고 정하지 않기',ARRAY['2수03-06']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M1-1-u4-C4','math',1,1,'u4',5,'담을 수 있는 양 비교하기 — 한 그릇에 가득 담은 물을 다른 그릇에 옮겨 담아 넘침·남음으로 견주고, 높이만 보고 정하지 않기',ARRAY['2수03-06']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M1-1-u4-C5','math',1,1,'u4',5,'담긴 양 비교하기 — 같은 그릇이면 물 높이로 견주고, 그릇의 크기(담을 수 있는 양)와 실제 담긴 양을 가르기',ARRAY['2수03-06']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M1-1-u4-C6','math',1,1,'u4',2,'알맞은 비교 말 — 길이·무게·넓이·들이마다 맞는 말(길다/무겁다/넓다/많다)을 쓰고, 「크다」로 뭉뚱그리지 않으며, 견주는 방향이 바뀌면 반대말로 바꾸어 말하기',ARRAY['2수03-06']::text[],27) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M1-1-u4-C7','math',1,1,'u4',2,'셋 이상 견주기 — 두 번 이상 견준 결과를 이어 「가장 ~하다」를 찾고, 한 번 견주어 본 것만으로 「가장」을 단정하지 않기',ARRAY['2수03-06']::text[],28) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-1-u4-X01','math',1,'u4',ARRAY['M1-1-u4-C1']::text[],'한쪽 끝을 맞추지 않고, 오른쪽으로 더 튀어나온 것을 더 길다고 한다','두 연필을 책상 모서리에 탁 대어 끝을 맞춘 뒤 다른 쪽 끝만 보게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-1-u4-X02','math',1,'u4',ARRAY['M1-1-u4-C1']::text[],'구부러진 끈·실은 양 끝 사이가 가까워 보여 더 짧다고 한다','구부러진 털실을 곧게 펴서 곧은 실 옆에 대어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-1-u4-X03','math',1,'u4',ARRAY['M1-1-u4-C1']::text[],'굵은(두꺼운) 것을 더 길다고 한다 — 굵기와 길이를 섞음','굵은 크레파스와 가는 긴 연필의 끝을 맞추어 다른 쪽 끝만 보게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-1-u4-X04','math',1,'u4',ARRAY['M1-1-u4-C2']::text[],'크기가 크면 더 무겁다고 단정한다','큰 빈 상자와 작은 돌을 양손에 들어 보게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-1-u4-X05','math',1,'u4',ARRAY['M1-1-u4-C2']::text[],'양팔저울에서 위로 올라간 쪽을 더 무겁다고 거꾸로 읽는다','무거운 가방을 든 손이 아래로 처지는 것을 몸으로 느끼고 저울 접시와 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-1-u4-X06','math',1,'u4',ARRAY['M1-1-u4-C3']::text[],'한 변(가로나 세로)의 길이만 보고 넓이를 정한다','길쭉한 종이와 네모난 종이를 겹쳐 남는 곳을 서로 견주어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-1-u4-X07','math',1,'u4',ARRAY['M1-1-u4-C3']::text[],'겹쳐 놓았을 때 위에 놓인 것을 더 넓다고 한다','위에 놓인 종이를 들어 보아 아래 종이가 둘레에 남는지 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-1-u4-X08','math',1,'u4',ARRAY['M1-1-u4-C4']::text[],'그릇의 높이만 보고 키가 큰 그릇에 더 많이 담을 수 있다고 한다','좁고 긴 컵의 물을 넓고 낮은 그릇에 부어 남는 곳을 보게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-1-u4-X09','math',1,'u4',ARRAY['M1-1-u4-C4','M1-1-u4-C5']::text[],'담긴 양과 담을 수 있는 양을 헷갈린다 — 큰 그릇이면 담긴 물도 많다고 여김','빈 양동이와 물이 가득 찬 컵을 나란히 두고 「그릇 크기」와 「들어 있는 물」을 따로 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-1-u4-X10','math',1,'u4',ARRAY['M1-1-u4-C4']::text[],'옮겨 담아 넘쳤을 때 받는 그릇이 더 크다고 거꾸로 해석한다','「넘쳤다 = 받는 그릇이 다 못 받았다」를 직접 부어 보며 말로 붙이기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-1-u4-X11','math',1,'u4',ARRAY['M1-1-u4-C4']::text[],'가득 채우지 않고(조금씩 담아) 담을 수 있는 양을 견준다','「담을 수 있는 양은 가득 채워 보아야 안다」를 놓친 경우 — 반만 채운 두 컵으로 틀린 결론을 직접 내 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-1-u4-X12','math',1,'u4',ARRAY['M1-1-u4-C6']::text[],'견주는 것에 맞지 않는 비교 말을 쓰거나 「크다」로 뭉뚱그린다(넓이를 「길다」, 들이를 「무겁다」 등)','길이·무게·넓이·들이 카드 네 장과 비교 말 카드를 짝 짓는 놀이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-1-u4-X13','math',1,'u4',ARRAY['M1-1-u4-C6']::text[],'견주는 방향이 바뀌어도 같은 말을 쓴다 — 「㉮가 더 길다」를 「㉯도 더 길다」로','두 친구가 서로를 보고 말하기 놀이: 「너는 나보다 더 커」 ↔ 「너는 나보다 더 작아」') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-1-u4-X14','math',1,'u4',ARRAY['M1-1-u4-C7']::text[],'두 개만 견주어 보고 셋 가운데 「가장」이라고 단정한다','셋째 물건과 한 번 더 견주어야 「가장」을 말할 수 있다는 것을 표로 그려 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-1-u4-X15','math',1,'u4',ARRAY['M1-1-u4-C7','M1-1-u4-C1','M1-1-u4-C2','M1-1-u4-C3','M1-1-u4-C4']::text[],'「가장 긴/짧은」, 「더 무거운/가벼운」처럼 묻는 방향을 거꾸로 읽는다','물음의 비교 말에 동그라미를 치고 답을 고른 뒤 그 말을 넣어 다시 읽어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-1-u4-X16','math',1,'u4',ARRAY['M1-1-u4-C1','M1-1-u4-C2','M1-1-u4-C3','M1-1-u4-C4']::text[],'크기가 다른 단위(뼘·구슬·타일·컵)로 잰 개수만 보고 견준다','같은 책상을 아이 뼘과 어른 뼘으로 재어 수가 달라지는 것을 직접 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L02_basic#1','math',1,1,'u4','L02','g1_1_math_u4_L02_basic','lesson_basic','M1-1-u4-C1',1,'mc','auto','왼쪽 끝을 빨간 선에 맞추어 놓았어요. 더 긴 것은 어느 것인가요?',ARRAY['M1-1-u4-X15','M1-1-u4-X01']::text[],true,'{"seq":1,"concept":"M1-1-u4-C1","difficulty":1,"kind":"mc","stem":"왼쪽 끝을 빨간 선에 맞추어 놓았어요. 더 긴 것은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M1-1-u4-X15"},{"t":"길이가 같아요","mis":"M1-1-u4-X01"}],"explanation":["왼쪽 끝이 맞추어져 있어요.","오른쪽 끝이 더 많이 나간 ㉮가 더 길어요.","끝을 맞추면 다른 쪽 끝만 보면 돼요."],"asset":{"type":"len_bars","rows":[{"label":"㉮","len":8},{"label":"㉯","len":5}]},"variant_rule":{"cmp4":{"ask":"most"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L02_basic#2','math',1,1,'u4','L02','g1_1_math_u4_L02_basic','lesson_basic','M1-1-u4-C1',1,'mc','auto','끝을 맞추어 놓았어요. 가장 짧은 것은 어느 것인가요?',ARRAY['M1-1-u4-X15','M1-1-u4-X14']::text[],true,'{"seq":2,"concept":"M1-1-u4-C1","difficulty":1,"kind":"mc","stem":"끝을 맞추어 놓았어요. 가장 짧은 것은 어느 것인가요?","options":[{"t":"㉰","correct":true},{"t":"㉯","mis":"M1-1-u4-X15"},{"t":"㉮","mis":"M1-1-u4-X14"}],"explanation":["왼쪽 끝이 모두 맞추어져 있어요.","오른쪽 끝이 가장 덜 나간 ㉰가 가장 짧아요.","셋을 견줄 때는 「가장 짧다」라고 말해요."],"asset":{"type":"len_bars","rows":[{"label":"㉮","len":6},{"label":"㉯","len":9},{"label":"㉰","len":3}]},"variant_rule":{"cmp4":{"ask":"least"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L02_basic#3','math',1,1,'u4','L02','g1_1_math_u4_L02_basic','lesson_basic','M1-1-u4-C6',1,'ox','auto','㉯는 ㉮보다 더 짧아요.',ARRAY['M1-1-u4-X12']::text[],true,'{"seq":3,"concept":"M1-1-u4-C6","difficulty":1,"kind":"ox","stem":"㉯는 ㉮보다 더 짧아요.","answer":"O","reason_options":[{"t":"끝을 맞추었을 때 ㉯의 오른쪽 끝이 덜 나갔으니까","correct":true},{"t":"짧은 것은 「더 작다」라고 말해야 하니까","mis":"M1-1-u4-X12"}],"mis":"M1-1-u4-X12","explanation":["두 막대의 왼쪽 끝이 맞추어져 있어요.","㉯의 오른쪽 끝이 덜 나갔으니 ㉯가 더 짧아요.","길이는 「더 길다·더 짧다」로 말해요."],"asset":{"type":"len_bars","rows":[{"label":"㉮","len":7},{"label":"㉯","len":4}]},"variant_rule":{"cmp4":{}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L02_basic#4','math',1,1,'u4','L02','g1_1_math_u4_L02_basic','lesson_basic','M1-1-u4-C6',1,'blank','auto','줄넘기 줄이 허리띠보다 더 길어요. 그러면 허리띠는 줄넘기 줄보다 더 (        ).',ARRAY['M1-1-u4-X13','M1-1-u4-X12']::text[],true,'{"seq":4,"concept":"M1-1-u4-C6","difficulty":1,"kind":"blank","stem":"줄넘기 줄이 허리띠보다 더 길어요. 그러면 허리띠는 줄넘기 줄보다 더 (        ).","options":[{"t":"짧아요","correct":true},{"t":"길어요","mis":"M1-1-u4-X13"},{"t":"작아요","mis":"M1-1-u4-X12"}],"explanation":["줄넘기 줄이 더 길다면","거꾸로 허리띠는 줄넘기 줄보다 더 짧아요.","견주는 방향이 바뀌면 반대말을 써요."],"variant_rule":{"alt":[{"stem":"기차가 버스보다 더 길어요. 그러면 버스는 기차보다 더 (        ).","options":[{"t":"짧아요","correct":true},{"t":"길어요","mis":"M1-1-u4-X13"},{"t":"가벼워요","mis":"M1-1-u4-X12"}],"explanation":["기차가 더 길다면","거꾸로 버스는 기차보다 더 짧아요.","견주는 방향이 바뀌면 반대말을 써요."],"asset":null},{"stem":"색연필이 크레파스보다 더 길어요. 그러면 크레파스는 색연필보다 더 (        ).","options":[{"t":"짧아요","correct":true},{"t":"길어요","mis":"M1-1-u4-X13"},{"t":"좁아요","mis":"M1-1-u4-X12"}],"explanation":["색연필이 더 길다면","거꾸로 크레파스는 색연필보다 더 짧아요.","견주는 방향이 바뀌면 반대말을 써요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L02_basic#5','math',1,1,'u4','L02','g1_1_math_u4_L02_basic','lesson_basic','M1-1-u4-C1',2,'mc','auto','두 막대의 끝이 맞추어져 있지 않아요. 칸을 세어 보고 더 긴 것을 고르세요.',ARRAY['M1-1-u4-X01']::text[],true,'{"seq":5,"concept":"M1-1-u4-C1","difficulty":2,"kind":"mc","stem":"두 막대의 끝이 맞추어져 있지 않아요. 칸을 세어 보고 더 긴 것을 고르세요.","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M1-1-u4-X01"},{"t":"길이가 같아요","mis":"M1-1-u4-X01"}],"explanation":["㉮는 6칸, ㉯는 4칸이에요.","㉯가 오른쪽으로 더 나가 있지만 더 긴 것은 ㉮예요.","끝이 안 맞으면 칸을 세거나 끝을 맞추어 다시 봐요."],"asset":{"type":"len_bars","rows":[{"label":"㉮","len":6},{"label":"㉯","len":4,"off":3}],"grid":true},"variant_rule":{"cmp4":{"ask":"most"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L02_basic#6','math',1,1,'u4','L02','g1_1_math_u4_L02_basic','lesson_basic','M1-1-u4-C1',2,'mc','auto','구부러진 실의 마디 하나는 칸 하나와 길이가 같아요. 두 실을 곧게 펴면 더 긴 것은 어느 것인가요?',ARRAY['M1-1-u4-X02']::text[],true,'{"seq":6,"concept":"M1-1-u4-C1","difficulty":2,"kind":"mc","stem":"구부러진 실의 마디 하나는 칸 하나와 길이가 같아요. 두 실을 곧게 펴면 더 긴 것은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M1-1-u4-X02"},{"t":"길이가 같아요","mis":"M1-1-u4-X02"}],"explanation":["㉮는 마디가 7개 — 펴면 7칸이에요.","㉯는 5칸이에요. 그래서 ㉮가 더 길어요.","구부러져 있으면 짧아 보여요. 펴서 견주어요."],"asset":{"type":"len_bars","rows":[{"label":"㉮","len":7,"bend":true},{"label":"㉯","len":5}],"grid":true},"variant_rule":{"cmp4":{"ask":"most"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L02_basic#7','math',1,1,'u4','L02','g1_1_math_u4_L02_basic','lesson_basic','M1-1-u4-C1',2,'sa','auto','㉯는 ㉮보다 몇 칸 더 긴가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M1-1-u4-C1","difficulty":2,"kind":"sa","stem":"㉯는 ㉮보다 몇 칸 더 긴가요? 숫자로 쓰세요.","answer":["3"],"explanation":["㉮는 4칸, ㉯는 7칸이에요.","7칸은 4칸보다 3칸 더 길어요.","끝을 맞춘 뒤 남는 칸만 세어도 돼요."],"asset":{"type":"len_bars","rows":[{"label":"㉮","len":4},{"label":"㉯","len":7}],"grid":true},"variant_rule":{"cmp4":{}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L02_basic#8','math',1,1,'u4','L02','g1_1_math_u4_L02_basic','lesson_basic','M1-1-u4-C6',2,'match','auto','견주는 것과 알맞은 비교 말을 이어 보세요.','{}'::text[],true,'{"seq":8,"concept":"M1-1-u4-C6","difficulty":2,"kind":"match","stem":"견주는 것과 알맞은 비교 말을 이어 보세요.","pairs":[{"l":"길이","r":"더 길다"},{"l":"무게","r":"더 무겁다"},{"l":"넓이","r":"더 넓다"}],"mis":"M1-1-u4-X12","explanation":["길이는 「길다·짧다」로 말해요.","무게는 「무겁다·가볍다」, 넓이는 「넓다·좁다」로 말해요.","무엇을 견주는지 먼저 봐요."],"variant_rule":{"alt":[{"stem":"비교 말과 반대말을 이어 보세요.","pairs":[{"l":"더 길다","r":"더 짧다"},{"l":"더 무겁다","r":"더 가볍다"},{"l":"더 넓다","r":"더 좁다"}],"explanation":["길다의 반대는 짧다예요.","무겁다↔가볍다, 넓다↔좁다예요.","방향이 바뀌면 반대말을 써요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L02_basic#9','math',1,1,'u4','L02','g1_1_math_u4_L02_basic','lesson_basic','M1-1-u4-C7',2,'ox','auto','㉮는 ㉯보다 길고, ㉯는 ㉰보다 길어요. 그러면 ㉮가 가장 길어요.',ARRAY['M1-1-u4-X14']::text[],true,'{"seq":9,"concept":"M1-1-u4-C7","difficulty":2,"kind":"ox","stem":"㉮는 ㉯보다 길고, ㉯는 ㉰보다 길어요. 그러면 ㉮가 가장 길어요.","answer":"O","reason_options":[{"t":"㉮는 ㉯보다 길고 ㉯는 ㉰보다 기니까 ㉮는 ㉰보다도 길어요","correct":true},{"t":"㉮와 ㉰는 서로 대어 보지 않았으니 알 수 없으니까","mis":"M1-1-u4-X14"}],"mis":"M1-1-u4-X14","explanation":["㉮ > ㉯, ㉯ > ㉰ 예요.","㉮는 ㉯보다 길고 ㉯는 ㉰보다 기니 ㉮는 ㉰보다도 길어요.","그래서 ㉮가 가장 길어요."],"variant_rule":{"alt":[{"stem":"㉮는 ㉯보다 짧고, ㉯는 ㉰보다 짧아요. 그러면 ㉰가 가장 짧아요.","answer":"X","reason_options":[{"t":"㉮가 ㉯보다 짧고 ㉯가 ㉰보다 짧으니 가장 짧은 것은 ㉮예요","correct":true},{"t":"마지막에 나온 ㉰가 가장 짧으니까","mis":"M1-1-u4-X15"}],"explanation":["㉮ < ㉯, ㉯ < ㉰ 예요.","가장 짧은 것은 ㉮, 가장 긴 것은 ㉰예요.","「짧다」를 거꾸로 읽지 않도록 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L02_basic#10','math',1,1,'u4','L02','g1_1_math_u4_L02_basic','lesson_basic','M1-1-u4-C1',3,'error','auto','친구들이 길이를 견주는 방법을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M1-1-u4-X01','M1-1-u4-X02']::text[],true,'{"seq":10,"concept":"M1-1-u4-C1","difficulty":3,"kind":"error","stem":"친구들이 길이를 견주는 방법을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지우: 끝을 맞추지 않아도 오른쪽으로 더 나간 것이 더 길어.","correct":true,"mis_target":"M1-1-u4-X01"},{"t":"하루: 한쪽 끝을 맞추고 다른 쪽 끝을 봐야 해.","mis":"M1-1-u4-X01"},{"t":"서아: 구부러진 줄은 곧게 펴서 대어 봐야 해.","mis":"M1-1-u4-X02"}],"explanation":["끝이 안 맞으면 튀어나온 쪽이 길어 보일 뿐이에요.","한쪽 끝을 맞추어야 정확해요.","지우가 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 친구들이 길이를 견주는 방법을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도이: 굵은 크레파스가 가는 연필보다 언제나 더 길어.","correct":true,"mis_target":"M1-1-u4-X03"},{"t":"하루: 굵기 말고 끝만 보면 돼.","mis":"M1-1-u4-X03"},{"t":"유나: 끝을 맞추어 대어 보면 알 수 있어.","mis":"M1-1-u4-X01"}],"explanation":["굵기는 길이가 아니에요.","끝을 맞추어 다른 쪽 끝을 봐야 해요.","도이가 잘못 말했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L02_challenge#1','math',1,1,'u4','L02','g1_1_math_u4_L02_challenge','lesson_challenge','M1-1-u4-C1',2,'mc','auto','굵은 막대와 가는 막대가 있어요. 더 긴 것은 어느 것인가요?',ARRAY['M1-1-u4-X03']::text[],true,'{"seq":1,"concept":"M1-1-u4-C1","difficulty":2,"kind":"mc","stem":"굵은 막대와 가는 막대가 있어요. 더 긴 것은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M1-1-u4-X03"},{"t":"길이가 같아요","mis":"M1-1-u4-X03"}],"explanation":["왼쪽 끝이 맞추어져 있어요.","㉮는 굵지만 오른쪽 끝은 ㉯가 더 나갔어요.","굵기가 아니라 끝을 봐요 — ㉯가 더 길어요."],"asset":{"type":"len_bars","rows":[{"label":"㉮","len":5,"thick":true},{"label":"㉯","len":7}]},"variant_rule":{"cmp4":{"ask":"most"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L02_challenge#2','math',1,1,'u4','L02','g1_1_math_u4_L02_challenge','lesson_challenge','M1-1-u4-C7',2,'sa','auto','가장 긴 것과 가장 짧은 것은 몇 칸 차이가 나나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M1-1-u4-C7","difficulty":2,"kind":"sa","stem":"가장 긴 것과 가장 짧은 것은 몇 칸 차이가 나나요? 숫자로 쓰세요.","answer":["5"],"explanation":["㉮ 6칸, ㉯ 9칸, ㉰ 4칸이에요.","가장 긴 ㉯와 가장 짧은 ㉰는 9칸과 4칸이에요.","9칸은 4칸보다 5칸 더 길어요."],"asset":{"type":"len_bars","rows":[{"label":"㉮","len":6},{"label":"㉯","len":9},{"label":"㉰","len":4}],"grid":true},"variant_rule":{"cmp4":{}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L02_challenge#3','math',1,1,'u4','L02','g1_1_math_u4_L02_challenge','lesson_challenge','M1-1-u4-C1',3,'mc','auto','끝이 맞추어져 있지 않아요. 칸을 세어 가장 긴 것을 고르세요.',ARRAY['M1-1-u4-X01']::text[],true,'{"seq":3,"concept":"M1-1-u4-C1","difficulty":3,"kind":"mc","stem":"끝이 맞추어져 있지 않아요. 칸을 세어 가장 긴 것을 고르세요.","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M1-1-u4-X01"},{"t":"㉰","mis":"M1-1-u4-X01"}],"explanation":["㉮ 6칸, ㉯ 7칸, ㉰ 5칸이에요.","㉮와 ㉰는 오른쪽으로 더 나가 있지만 칸 수는 적어요.","가장 긴 것은 ㉯예요."],"asset":{"type":"len_bars","rows":[{"label":"㉮","len":6,"off":2},{"label":"㉯","len":7},{"label":"㉰","len":5,"off":3}],"grid":true},"variant_rule":{"cmp4":{"ask":"most"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L02_challenge#4','math',1,1,'u4','L02','g1_1_math_u4_L02_challenge','lesson_challenge','M1-1-u4-C1',3,'mc','auto','구부러진 실의 마디 하나는 칸 하나와 길이가 같아요. 곧게 펴면 가장 긴 것은 어느 것인가요?',ARRAY['M1-1-u4-X02','M1-1-u4-X15']::text[],true,'{"seq":4,"concept":"M1-1-u4-C1","difficulty":3,"kind":"mc","stem":"구부러진 실의 마디 하나는 칸 하나와 길이가 같아요. 곧게 펴면 가장 긴 것은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉰","mis":"M1-1-u4-X02"},{"t":"㉯","mis":"M1-1-u4-X15"}],"explanation":["㉮는 마디 8개 — 펴면 8칸이에요.","㉯는 6칸, ㉰는 7칸이에요.","구부러진 ㉮가 펴면 가장 길어요."],"asset":{"type":"len_bars","rows":[{"label":"㉮","len":8,"bend":true},{"label":"㉯","len":6},{"label":"㉰","len":7}],"grid":true},"variant_rule":{"cmp4":{"ask":"most"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L02_challenge#5','math',1,1,'u4','L02','g1_1_math_u4_L02_challenge','lesson_challenge','M1-1-u4-C7',3,'mc','auto','㉮는 ㉯보다 길어요. ㉰는 ㉮보다 길어요. 가장 짧은 것은 어느 것인가요?',ARRAY['M1-1-u4-X14','M1-1-u4-X15']::text[],true,'{"seq":5,"concept":"M1-1-u4-C7","difficulty":3,"kind":"mc","stem":"㉮는 ㉯보다 길어요. ㉰는 ㉮보다 길어요. 가장 짧은 것은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M1-1-u4-X14"},{"t":"㉰","mis":"M1-1-u4-X15"}],"explanation":["㉰ > ㉮ 이고 ㉮ > ㉯ 예요.","길이 차례는 ㉰, ㉮, ㉯예요.","가장 짧은 것은 ㉯예요."],"variant_rule":{"alt":[{"stem":"㉯는 ㉰보다 짧아요. ㉮는 ㉯보다 짧아요. 가장 긴 것은 어느 것인가요?","options":[{"t":"㉰","correct":true},{"t":"㉯","mis":"M1-1-u4-X14"},{"t":"㉮","mis":"M1-1-u4-X15"}],"explanation":["㉮ < ㉯ 이고 ㉯ < ㉰ 예요.","길이 차례는 ㉮, ㉯, ㉰예요.","가장 긴 것은 ㉰예요."],"asset":null},{"stem":"㉰는 ㉯보다 길어요. ㉮는 ㉰보다 길어요. 가장 짧은 것은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉰","mis":"M1-1-u4-X14"},{"t":"㉮","mis":"M1-1-u4-X15"}],"explanation":["㉮ > ㉰ 이고 ㉰ > ㉯ 예요.","길이 차례는 ㉮, ㉰, ㉯예요.","가장 짧은 것은 ㉯예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L02_challenge#6','math',1,1,'u4','L02','g1_1_math_u4_L02_challenge','lesson_challenge','M1-1-u4-C6',3,'ox','auto','끈 ㉮가 끈 ㉯보다 더 짧으면, 끈 ㉯는 끈 ㉮보다 더 길어요.',ARRAY['M1-1-u4-X13']::text[],true,'{"seq":6,"concept":"M1-1-u4-C6","difficulty":3,"kind":"ox","stem":"끈 ㉮가 끈 ㉯보다 더 짧으면, 끈 ㉯는 끈 ㉮보다 더 길어요.","answer":"O","reason_options":[{"t":"㉮가 더 짧다는 것은 ㉯가 더 길다는 말이니까","correct":true},{"t":"둘 다 「더 짧다」라고 말해야 하니까","mis":"M1-1-u4-X13"}],"mis":"M1-1-u4-X13","explanation":["㉮ < ㉯ 예요.","거꾸로 말하면 ㉯는 ㉮보다 더 길어요.","방향이 바뀌면 짧다는 길다로 바뀌어요."],"variant_rule":{"alt":[{"stem":"연필이 볼펜보다 더 길면, 볼펜도 연필보다 더 길어요.","answer":"X","reason_options":[{"t":"연필이 더 길면 볼펜은 연필보다 더 짧으니까","correct":true},{"t":"둘 다 「더 길다」로 말할 수 있으니까","mis":"M1-1-u4-X13"}],"explanation":["연필 > 볼펜 이에요.","거꾸로 말하면 볼펜은 연필보다 더 짧아요.","방향이 바뀌면 반대말을 써요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L02_challenge#7','math',1,1,'u4','L02','g1_1_math_u4_L02_challenge','lesson_challenge','M1-1-u4-C7',3,'mc','auto','끝을 맞추어 놓았어요. 길이가 두 번째로 긴 것(가운데)은 어느 것인가요?',ARRAY['M1-1-u4-X15']::text[],true,'{"seq":7,"concept":"M1-1-u4-C7","difficulty":3,"kind":"mc","stem":"끝을 맞추어 놓았어요. 길이가 두 번째로 긴 것(가운데)은 어느 것인가요?","options":[{"t":"㉰","correct":true},{"t":"㉮","mis":"M1-1-u4-X15"},{"t":"㉯","mis":"M1-1-u4-X15"}],"explanation":["㉮ 9칸, ㉯ 4칸, ㉰ 6칸이에요.","긴 차례는 ㉮, ㉰, ㉯예요.","가운데는 ㉰예요."],"asset":{"type":"len_bars","rows":[{"label":"㉮","len":9},{"label":"㉯","len":4},{"label":"㉰","len":6}],"grid":true},"variant_rule":{"cmp4":{"ask":"mid"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L02_challenge#8','math',1,1,'u4','L02','g1_1_math_u4_L02_challenge','lesson_challenge','M1-1-u4-C7',4,'mc','auto','서아는 하루보다 키가 커요. 도이는 서아보다 키가 커요. 하루는 지우보다 키가 커요. 키가 가장 작은 사람은 누구인가요?',ARRAY['M1-1-u4-X14','M1-1-u4-X15']::text[],true,'{"seq":8,"concept":"M1-1-u4-C7","difficulty":4,"kind":"mc","stem":"서아는 하루보다 키가 커요. 도이는 서아보다 키가 커요. 하루는 지우보다 키가 커요. 키가 가장 작은 사람은 누구인가요?","options":[{"t":"지우","correct":true},{"t":"하루","mis":"M1-1-u4-X14"},{"t":"도이","mis":"M1-1-u4-X15"}],"explanation":["도이 > 서아 > 하루 예요.","하루 > 지우 이니 지우가 하루보다도 작아요.","키가 가장 작은 사람은 지우예요."],"variant_rule":{"alt":[{"stem":"나무 ㉮는 나무 ㉯보다 키가 커요. 나무 ㉰는 나무 ㉮보다 키가 커요. 나무 ㉱는 나무 ㉰보다 키가 커요. 키가 가장 작은 나무는?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M1-1-u4-X14"},{"t":"㉱","mis":"M1-1-u4-X15"}],"explanation":["㉱ > ㉰ > ㉮ > ㉯ 예요.","차례대로 늘어놓으면 맨 끝은 ㉯예요.","키가 가장 작은 나무는 ㉯예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L02_challenge#9','math',1,1,'u4','L02','g1_1_math_u4_L02_challenge','lesson_challenge','M1-1-u4-C1',4,'essay','teacher','두 줄넘기 줄 가운데 어느 것이 더 긴지 알아보려고 해요. 어떻게 견주면 정확한지 방법을 쓰고, 조심할 점을 하나 말해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M1-1-u4-C1","difficulty":4,"kind":"essay","stem":"두 줄넘기 줄 가운데 어느 것이 더 긴지 알아보려고 해요. 어떻게 견주면 정확한지 방법을 쓰고, 조심할 점을 하나 말해 보세요.","answer_guide":{"answer":"두 줄을 곧게 편 뒤 한쪽 끝을 맞추어 나란히 놓고 다른 쪽 끝이 더 나간 줄이 더 길다. 줄이 구부러져 있거나 끝이 안 맞으면 길이를 잘못 볼 수 있다.","scoring_points":["곧게 펴는 것을 말했는가","한쪽 끝을 맞춘다고 했는가","다른 쪽 끝을 보고 판단한다고 했는가"]},"explanation":["구부러진 줄은 먼저 곧게 펴요.","한쪽 끝을 맞추어 나란히 놓아요.","다른 쪽 끝이 더 나간 줄이 더 길어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L02_challenge#10','math',1,1,'u4','L02','g1_1_math_u4_L02_challenge','lesson_challenge','M1-1-u4-C1',4,'mc','auto','지우와 아빠가 같은 책상의 길이를 뼘으로 재었어요. 지우는 8뼘, 아빠는 5뼘이었어요. 알맞은 말은 어느 것인가요?',ARRAY['M1-1-u4-X16']::text[],true,'{"seq":10,"concept":"M1-1-u4-C1","difficulty":4,"kind":"mc","stem":"지우와 아빠가 같은 책상의 길이를 뼘으로 재었어요. 지우는 8뼘, 아빠는 5뼘이었어요. 알맞은 말은 어느 것인가요?","options":[{"t":"같은 책상이에요 — 아빠 뼘이 더 길어서 수가 적어요","correct":true},{"t":"지우가 잰 책상이 더 길어요","mis":"M1-1-u4-X16"},{"t":"아빠가 잘못 재었어요","mis":"M1-1-u4-X16"}],"explanation":["지우와 아빠는 같은 책상을 재었어요.","아빠 뼘이 더 길어서 적은 수로 끝까지 닿아요.","재는 것의 크기가 다르면 수만 보고 견줄 수 없어요."],"variant_rule":{"alt":[{"stem":"하루는 클립으로, 도이는 연필로 같은 끈을 재었어요. 하루는 클립 9개, 도이는 연필 3자루였어요. 알맞은 말은 어느 것인가요?","options":[{"t":"같은 끈이에요 — 연필이 클립보다 길어서 수가 적어요","correct":true},{"t":"하루가 잰 끈이 더 길어요","mis":"M1-1-u4-X16"},{"t":"도이가 잘못 재었어요","mis":"M1-1-u4-X16"}],"explanation":["하루와 도이는 같은 끈을 재었어요.","연필이 클립보다 길어서 적은 수로 끝까지 닿아요.","재는 것의 크기가 다르면 수만 보고 견줄 수 없어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L03_basic#1','math',1,1,'u4','L03','g1_1_math_u4_L03_basic','lesson_basic','M1-1-u4-C2',1,'mc','auto','양팔저울에 두 과일을 올렸어요. 더 무거운 것은 어느 것인가요?',ARRAY['M1-1-u4-X05']::text[],true,'{"seq":1,"concept":"M1-1-u4-C2","difficulty":1,"kind":"mc","stem":"양팔저울에 두 과일을 올렸어요. 더 무거운 것은 어느 것인가요?","options":[{"t":"수박","correct":true},{"t":"딸기","mis":"M1-1-u4-X05"},{"t":"무게가 같아요","mis":"M1-1-u4-X05"}],"explanation":["수박 쪽 접시가 아래로 내려갔어요.","아래로 내려간 쪽이 더 무거워요.","그래서 수박이 더 무거워요."],"asset":{"type":"balance","scales":[{"l":{"icon":"🍉","name":"수박"},"r":{"icon":"🍓","name":"딸기"},"down":"l"}]},"variant_rule":{"cmp4":{"ask":"most"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L03_basic#2','math',1,1,'u4','L03','g1_1_math_u4_L03_basic','lesson_basic','M1-1-u4-C2',1,'mc','auto','양팔저울에 두 물건을 올렸어요. 더 가벼운 것은 어느 것인가요?',ARRAY['M1-1-u4-X05']::text[],true,'{"seq":2,"concept":"M1-1-u4-C2","difficulty":1,"kind":"mc","stem":"양팔저울에 두 물건을 올렸어요. 더 가벼운 것은 어느 것인가요?","options":[{"t":"깃털","correct":true},{"t":"책","mis":"M1-1-u4-X05"},{"t":"무게가 같아요","mis":"M1-1-u4-X05"}],"explanation":["책 쪽 접시가 아래로 내려갔어요.","위로 올라간 깃털 쪽이 더 가벼워요.","더 가벼운 것은 깃털이에요."],"asset":{"type":"balance","scales":[{"l":{"icon":"📕","name":"책"},"r":{"icon":"🪶","name":"깃털"},"down":"l"}]},"variant_rule":{"cmp4":{"ask":"least"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L03_basic#3','math',1,1,'u4','L03','g1_1_math_u4_L03_basic','lesson_basic','M1-1-u4-C2',1,'ox','auto','저울에서 위로 올라간 쪽의 풍선이 축구공보다 더 무거워요.',ARRAY['M1-1-u4-X05']::text[],true,'{"seq":3,"concept":"M1-1-u4-C2","difficulty":1,"kind":"ox","stem":"저울에서 위로 올라간 쪽의 풍선이 축구공보다 더 무거워요.","answer":"X","reason_options":[{"t":"아래로 내려간 쪽이 더 무거우니까","correct":true},{"t":"높이 올라간 쪽이 힘이 세서 더 무거우니까","mis":"M1-1-u4-X05"}],"mis":"M1-1-u4-X05","explanation":["축구공 쪽이 아래로 내려갔어요.","내려간 쪽이 더 무거워요 — 축구공이 더 무거워요.","풍선은 위로 올라갔으니 더 가벼워요."],"asset":{"type":"balance","scales":[{"l":{"icon":"⚽","name":"축구공"},"r":{"icon":"🎈","name":"풍선"},"down":"l"}]},"variant_rule":{"cmp4":{}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L03_basic#4','math',1,1,'u4','L03','g1_1_math_u4_L03_basic','lesson_basic','M1-1-u4-C6',1,'blank','auto','가방이 공책보다 더 무거워요. 그러면 공책은 가방보다 더 (        ).',ARRAY['M1-1-u4-X13','M1-1-u4-X12']::text[],true,'{"seq":4,"concept":"M1-1-u4-C6","difficulty":1,"kind":"blank","stem":"가방이 공책보다 더 무거워요. 그러면 공책은 가방보다 더 (        ).","options":[{"t":"가벼워요","correct":true},{"t":"무거워요","mis":"M1-1-u4-X13"},{"t":"짧아요","mis":"M1-1-u4-X12"}],"explanation":["가방이 더 무겁다면","거꾸로 공책은 가방보다 더 가벼워요.","견주는 방향이 바뀌면 반대말을 써요."],"variant_rule":{"alt":[{"stem":"의자가 필통보다 더 무거워요. 그러면 필통은 의자보다 더 (        ).","options":[{"t":"가벼워요","correct":true},{"t":"무거워요","mis":"M1-1-u4-X13"},{"t":"좁아요","mis":"M1-1-u4-X12"}],"explanation":["의자가 더 무겁다면","거꾸로 필통은 의자보다 더 가벼워요.","견주는 방향이 바뀌면 반대말을 써요."],"asset":null},{"stem":"사과가 귤보다 더 무거워요. 그러면 귤은 사과보다 더 (        ).","options":[{"t":"가벼워요","correct":true},{"t":"무거워요","mis":"M1-1-u4-X13"},{"t":"작아요","mis":"M1-1-u4-X12"}],"explanation":["사과가 더 무겁다면","거꾸로 귤은 사과보다 더 가벼워요.","무게는 「무겁다·가볍다」로 말해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L03_basic#5','math',1,1,'u4','L03','g1_1_math_u4_L03_basic','lesson_basic','M1-1-u4-C2',2,'mc','auto','큰 풍선과 작은 돌을 양팔저울에 올렸어요. 더 무거운 것은 어느 것인가요?',ARRAY['M1-1-u4-X04']::text[],true,'{"seq":5,"concept":"M1-1-u4-C2","difficulty":2,"kind":"mc","stem":"큰 풍선과 작은 돌을 양팔저울에 올렸어요. 더 무거운 것은 어느 것인가요?","options":[{"t":"작은 돌","correct":true},{"t":"큰 풍선","mis":"M1-1-u4-X04"},{"t":"무게가 같아요","mis":"M1-1-u4-X04"}],"explanation":["작은 돌 쪽 접시가 아래로 내려갔어요.","크기는 풍선이 더 크지만 더 무거운 것은 작은 돌이에요.","크기만 보고 무게를 정할 수 없어요."],"asset":{"type":"balance","scales":[{"l":{"icon":"🎈","name":"큰 풍선"},"r":{"icon":"🪨","name":"작은 돌"},"down":"r"}]},"variant_rule":{"cmp4":{"ask":"most"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L03_basic#6','math',1,1,'u4','L03','g1_1_math_u4_L03_basic','lesson_basic','M1-1-u4-C7',2,'mc','auto','저울 두 개로 상자 세 개를 견주었어요. 가장 무거운 상자는 어느 것인가요?',ARRAY['M1-1-u4-X14','M1-1-u4-X15']::text[],true,'{"seq":6,"concept":"M1-1-u4-C7","difficulty":2,"kind":"mc","stem":"저울 두 개로 상자 세 개를 견주었어요. 가장 무거운 상자는 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M1-1-u4-X14"},{"t":"㉰","mis":"M1-1-u4-X15"}],"explanation":["첫째 저울에서 ㉮가 ㉯보다 무거워요.","둘째 저울에서 ㉯가 ㉰보다 무거워요.","그래서 가장 무거운 것은 ㉮예요."],"asset":{"type":"balance","scales":[{"l":{"icon":"📦","name":"㉮"},"r":{"icon":"📦","name":"㉯"},"down":"l"},{"l":{"icon":"📦","name":"㉯"},"r":{"icon":"📦","name":"㉰"},"down":"l"}]},"variant_rule":{"cmp4":{"ask":"most","names":[["㉮","㉯","㉰"]]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L03_basic#7','math',1,1,'u4','L03','g1_1_math_u4_L03_basic','lesson_basic','M1-1-u4-C7',2,'sa','auto','저울 두 개를 보고 가장 가벼운 상자를 쓰세요. (㉮, ㉯, ㉰ 가운데 하나)','{}'::text[],true,'{"seq":7,"concept":"M1-1-u4-C7","difficulty":2,"kind":"sa","stem":"저울 두 개를 보고 가장 가벼운 상자를 쓰세요. (㉮, ㉯, ㉰ 가운데 하나)","answer":["㉰"],"explanation":["㉮는 ㉯보다 무거워요.","㉯는 ㉰보다 무거워요.","가장 가벼운 상자는 ㉰예요."],"asset":{"type":"balance","scales":[{"l":{"icon":"📦","name":"㉮"},"r":{"icon":"📦","name":"㉯"},"down":"l"},{"l":{"icon":"📦","name":"㉯"},"r":{"icon":"📦","name":"㉰"},"down":"l"}]},"variant_rule":{"cmp4":{"ask":"least","names":[["㉮","㉯","㉰"]]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L03_basic#8','math',1,1,'u4','L03','g1_1_math_u4_L03_basic','lesson_basic','M1-1-u4-C6',2,'match','auto','비교 말과 반대말을 이어 보세요.','{}'::text[],true,'{"seq":8,"concept":"M1-1-u4-C6","difficulty":2,"kind":"match","stem":"비교 말과 반대말을 이어 보세요.","pairs":[{"l":"더 무겁다","r":"더 가볍다"},{"l":"더 길다","r":"더 짧다"},{"l":"더 넓다","r":"더 좁다"}],"mis":"M1-1-u4-X13","explanation":["무겁다의 반대는 가볍다예요.","길다↔짧다, 넓다↔좁다예요.","견주는 방향이 바뀌면 반대말을 써요."],"variant_rule":{"alt":[{"stem":"견주는 것과 견주는 방법을 이어 보세요.","pairs":[{"l":"무게","r":"양팔저울에 올리기"},{"l":"길이","r":"끝을 맞추어 대어 보기"},{"l":"넓이","r":"겹쳐 보기"}],"explanation":["무게는 저울이나 손으로 들어 봐요.","길이는 끝을 맞추고, 넓이는 겹쳐 봐요.","무엇을 견주는지에 따라 방법이 달라요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L03_basic#9','math',1,1,'u4','L03','g1_1_math_u4_L03_basic','lesson_basic','M1-1-u4-C2',2,'mc','auto','두 물건을 양손에 하나씩 들었더니 오른손이 아래로 내려갔어요. 오른손에 든 물건은 어떤 것인가요?',ARRAY['M1-1-u4-X05','M1-1-u4-X04']::text[],true,'{"seq":9,"concept":"M1-1-u4-C2","difficulty":2,"kind":"mc","stem":"두 물건을 양손에 하나씩 들었더니 오른손이 아래로 내려갔어요. 오른손에 든 물건은 어떤 것인가요?","options":[{"t":"더 무거운 것","correct":true},{"t":"더 가벼운 것","mis":"M1-1-u4-X05"},{"t":"더 큰 것","mis":"M1-1-u4-X04"}],"explanation":["무거운 것을 들면 손이 아래로 내려가요.","오른손이 내려갔으니 오른손에 든 것이 더 무거워요.","크기는 들어 봐야 알 수 있는 게 아니에요 — 무게를 말해요."],"variant_rule":{"alt":[{"stem":"양팔저울의 왼쪽 접시가 위로 올라갔어요. 왼쪽에 놓인 물건은 어떤 것인가요?","options":[{"t":"더 가벼운 것","correct":true},{"t":"더 무거운 것","mis":"M1-1-u4-X05"},{"t":"더 작은 것","mis":"M1-1-u4-X04"}],"explanation":["무거운 쪽 접시가 아래로 내려가요.","왼쪽이 올라갔으니 왼쪽 물건이 더 가벼워요.","크기가 아니라 무게를 말해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L03_basic#10','math',1,1,'u4','L03','g1_1_math_u4_L03_basic','lesson_basic','M1-1-u4-C2',3,'error','auto','친구들이 무게에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M1-1-u4-X04','M1-1-u4-X05']::text[],true,'{"seq":10,"concept":"M1-1-u4-C2","difficulty":3,"kind":"error","stem":"친구들이 무게에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도이: 크기가 크니까 틀림없이 더 무거워.","correct":true,"mis_target":"M1-1-u4-X04"},{"t":"하루: 저울에서 내려간 쪽이 더 무거워.","mis":"M1-1-u4-X05"},{"t":"서아: 양손에 들어 보면 무게를 견줄 수 있어.","mis":"M1-1-u4-X04"}],"explanation":["큰 빈 상자가 작은 돌보다 가벼울 수 있어요.","크기만 보고 무게를 정할 수 없어요.","도이가 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 친구들이 무게에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"유나: 저울에서 위로 올라간 쪽이 더 무거워.","correct":true,"mis_target":"M1-1-u4-X05"},{"t":"지우: 크기가 커도 가벼울 수 있어.","mis":"M1-1-u4-X04"},{"t":"하루: 내려간 접시 쪽이 더 무거워.","mis":"M1-1-u4-X05"}],"explanation":["저울은 무거운 쪽이 아래로 내려가요.","올라간 쪽은 더 가벼워요.","유나가 잘못 말했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L03_challenge#1','math',1,1,'u4','L03','g1_1_math_u4_L03_challenge','lesson_challenge','M1-1-u4-C2',2,'mc','auto','큰 스펀지와 작은 쇠공을 양팔저울에 올렸어요. 더 가벼운 것은 어느 것인가요?',ARRAY['M1-1-u4-X04']::text[],true,'{"seq":1,"concept":"M1-1-u4-C2","difficulty":2,"kind":"mc","stem":"큰 스펀지와 작은 쇠공을 양팔저울에 올렸어요. 더 가벼운 것은 어느 것인가요?","options":[{"t":"큰 스펀지","correct":true},{"t":"작은 쇠공","mis":"M1-1-u4-X04"},{"t":"무게가 같아요","mis":"M1-1-u4-X04"}],"explanation":["작은 쇠공 쪽이 아래로 내려갔어요.","위로 올라간 큰 스펀지가 더 가벼워요.","크기가 크다고 무거운 것은 아니에요."],"asset":{"type":"balance","scales":[{"l":{"icon":"🧽","name":"큰 스펀지"},"r":{"icon":"⚙️","name":"작은 쇠공"},"down":"r"}]},"variant_rule":{"cmp4":{"ask":"least"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L03_challenge#2','math',1,1,'u4','L03','g1_1_math_u4_L03_challenge','lesson_challenge','M1-1-u4-C2',2,'ox','auto','저울이 기울지 않고 반듯해요. 상자 ㉮와 상자 ㉯의 무게는 같아요.',ARRAY['M1-1-u4-X04']::text[],true,'{"seq":2,"concept":"M1-1-u4-C2","difficulty":2,"kind":"ox","stem":"저울이 기울지 않고 반듯해요. 상자 ㉮와 상자 ㉯의 무게는 같아요.","answer":"O","reason_options":[{"t":"어느 쪽도 내려가지 않았으니 무게가 같아요","correct":true},{"t":"두 상자의 크기가 같아 보이니까","mis":"M1-1-u4-X04"}],"mis":"M1-1-u4-X04","explanation":["저울이 반듯하면 양쪽 무게가 같아요.","한쪽이 더 무거우면 그쪽이 내려가요.","그래서 ㉮와 ㉯는 무게가 같아요."],"asset":{"type":"balance","scales":[{"l":{"icon":"📦","name":"㉮"},"r":{"icon":"📦","name":"㉯"},"down":"eq"}]},"variant_rule":{"cmp4":{"names":[["㉮","㉯","㉰"]]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L03_challenge#3','math',1,1,'u4','L03','g1_1_math_u4_L03_challenge','lesson_challenge','M1-1-u4-C7',3,'mc','auto','저울 두 개로 상자 세 개를 견주었어요. 가장 가벼운 상자는 어느 것인가요?',ARRAY['M1-1-u4-X14','M1-1-u4-X15']::text[],true,'{"seq":3,"concept":"M1-1-u4-C7","difficulty":3,"kind":"mc","stem":"저울 두 개로 상자 세 개를 견주었어요. 가장 가벼운 상자는 어느 것인가요?","options":[{"t":"㉰","correct":true},{"t":"㉮","mis":"M1-1-u4-X14"},{"t":"㉯","mis":"M1-1-u4-X15"}],"explanation":["첫째 저울에서 ㉯가 ㉮보다 무거워요.","둘째 저울에서 ㉮가 ㉰보다 무거워요.","무거운 차례는 ㉯, ㉮, ㉰ — 가장 가벼운 것은 ㉰예요."],"asset":{"type":"balance","scales":[{"l":{"icon":"📦","name":"㉮"},"r":{"icon":"📦","name":"㉯"},"down":"r"},{"l":{"icon":"📦","name":"㉮"},"r":{"icon":"📦","name":"㉰"},"down":"l"}]},"variant_rule":{"cmp4":{"ask":"least","names":[["㉮","㉯","㉰"]]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L03_challenge#4','math',1,1,'u4','L03','g1_1_math_u4_L03_challenge','lesson_challenge','M1-1-u4-C7',3,'mc','auto','저울 세 개로 상자 세 개를 견주었어요. 무게가 가운데인 상자는 어느 것인가요?',ARRAY['M1-1-u4-X15']::text[],true,'{"seq":4,"concept":"M1-1-u4-C7","difficulty":3,"kind":"mc","stem":"저울 세 개로 상자 세 개를 견주었어요. 무게가 가운데인 상자는 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M1-1-u4-X15"},{"t":"㉰","mis":"M1-1-u4-X15"}],"explanation":["㉮는 ㉯보다, ㉯는 ㉰보다, ㉮는 ㉰보다 무거워요.","무거운 차례는 ㉮, ㉯, ㉰예요.","가운데는 ㉯예요."],"asset":{"type":"balance","scales":[{"l":{"icon":"📦","name":"㉮"},"r":{"icon":"📦","name":"㉯"},"down":"l"},{"l":{"icon":"📦","name":"㉯"},"r":{"icon":"📦","name":"㉰"},"down":"l"},{"l":{"icon":"📦","name":"㉮"},"r":{"icon":"📦","name":"㉰"},"down":"l"}]},"variant_rule":{"cmp4":{"ask":"mid","names":[["㉮","㉯","㉰"]]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L03_challenge#5','math',1,1,'u4','L03','g1_1_math_u4_L03_challenge','lesson_challenge','M1-1-u4-C2',3,'mc','auto','같은 크기의 공 두 개를 저울에 올렸더니 ㉯ 쪽으로 기울었어요. 더 가벼운 공은 어느 것인가요?',ARRAY['M1-1-u4-X05','M1-1-u4-X04']::text[],true,'{"seq":5,"concept":"M1-1-u4-C2","difficulty":3,"kind":"mc","stem":"같은 크기의 공 두 개를 저울에 올렸더니 ㉯ 쪽으로 기울었어요. 더 가벼운 공은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M1-1-u4-X05"},{"t":"같은 크기라서 무게도 같아요","mis":"M1-1-u4-X04"}],"explanation":["㉯ 쪽 접시가 아래로 내려갔어요.","위로 올라간 ㉮가 더 가벼워요.","크기가 같아도 무게는 다를 수 있어요."],"asset":{"type":"balance","scales":[{"l":{"icon":"⚪","name":"㉮"},"r":{"icon":"⚪","name":"㉯"},"down":"r"}]},"variant_rule":{"cmp4":{"ask":"least","names":[["㉮","㉯"]]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L03_challenge#6','math',1,1,'u4','L03','g1_1_math_u4_L03_challenge','lesson_challenge','M1-1-u4-C6',3,'blank','auto','㉮는 ㉯보다 더 무겁고, ㉰는 ㉮보다 더 무거워요. ㉯는 셋 가운데 가장 (        ).',ARRAY['M1-1-u4-X15','M1-1-u4-X12']::text[],true,'{"seq":6,"concept":"M1-1-u4-C6","difficulty":3,"kind":"blank","stem":"㉮는 ㉯보다 더 무겁고, ㉰는 ㉮보다 더 무거워요. ㉯는 셋 가운데 가장 (        ).","options":[{"t":"가벼워요","correct":true},{"t":"무거워요","mis":"M1-1-u4-X15"},{"t":"짧아요","mis":"M1-1-u4-X12"}],"explanation":["㉰ > ㉮ 이고 ㉮ > ㉯ 예요.","무거운 차례는 ㉰, ㉮, ㉯예요.","그래서 ㉯는 가장 가벼워요."],"variant_rule":{"alt":[{"stem":"㉯는 ㉮보다 더 가볍고, ㉮는 ㉰보다 더 가벼워요. ㉰는 셋 가운데 가장 (        ).","options":[{"t":"무거워요","correct":true},{"t":"가벼워요","mis":"M1-1-u4-X15"},{"t":"길어요","mis":"M1-1-u4-X12"}],"explanation":["㉯ < ㉮ 이고 ㉮ < ㉰ 예요.","가벼운 차례는 ㉯, ㉮, ㉰예요.","그래서 ㉰는 가장 무거워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L03_challenge#7','math',1,1,'u4','L03','g1_1_math_u4_L03_challenge','lesson_challenge','M1-1-u4-C7',3,'error','auto','세 가지 공의 무게를 알아보려고 해요. 잘못 생각한 친구는 누구인가요?',ARRAY['M1-1-u4-X14']::text[],true,'{"seq":7,"concept":"M1-1-u4-C7","difficulty":3,"kind":"error","stem":"세 가지 공의 무게를 알아보려고 해요. 잘못 생각한 친구는 누구인가요?","options":[{"t":"서아: 축구공이 야구공보다 무거우니까 셋 가운데 축구공이 가장 무거워.","correct":true,"mis_target":"M1-1-u4-X14"},{"t":"하루: 농구공과도 한 번 더 견주어 봐야 해.","mis":"M1-1-u4-X14"},{"t":"도이: 축구공과 농구공을 저울에 올려 보자.","mis":"M1-1-u4-X14"}],"explanation":["서아는 축구공과 야구공만 견주었어요.","농구공과는 견주어 보지 않았어요.","셋째 것과도 견주어야 「가장」을 말할 수 있어요."],"variant_rule":{"alt":[{"stem":"세 가지 상자의 무게를 알아보려고 해요. 잘못 생각한 친구는 누구인가요?","options":[{"t":"유나: ㉮가 ㉯보다 가벼우니까 ㉮가 셋 가운데 가장 가벼워.","correct":true,"mis_target":"M1-1-u4-X14"},{"t":"지우: ㉮와 ㉰도 견주어 봐야 해.","mis":"M1-1-u4-X14"},{"t":"하루: 저울에 ㉮와 ㉰를 올려 보자.","mis":"M1-1-u4-X14"}],"explanation":["유나는 ㉮와 ㉯만 견주었어요.","㉰와는 견주어 보지 않았어요.","셋째 것과도 견주어야 「가장」을 말할 수 있어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L03_challenge#8','math',1,1,'u4','L03','g1_1_math_u4_L03_challenge','lesson_challenge','M1-1-u4-C2',4,'mc','auto','크기가 다른 구슬로 무게를 견주었어요. ㉮는 큰 구슬 4개, ㉯는 작은 구슬 6개와 무게가 같았어요. 큰 구슬 1개는 작은 구슬 2개와 무게가 같아요. 더 무거운 것은 어느 것인가요?',ARRAY['M1-1-u4-X16']::text[],true,'{"seq":8,"concept":"M1-1-u4-C2","difficulty":4,"kind":"mc","stem":"크기가 다른 구슬로 무게를 견주었어요. ㉮는 큰 구슬 4개, ㉯는 작은 구슬 6개와 무게가 같았어요. 큰 구슬 1개는 작은 구슬 2개와 무게가 같아요. 더 무거운 것은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M1-1-u4-X16"},{"t":"무게가 같아요","mis":"M1-1-u4-X16"}],"explanation":["큰 구슬 1개 = 작은 구슬 2개예요.","㉮는 큰 구슬 4개 — 작은 구슬로 8개만큼이에요.","작은 구슬 8개는 6개보다 많으니 ㉮가 더 무거워요."],"variant_rule":{"alt":[{"stem":"㉮는 큰 구슬 3개, ㉯는 작은 구슬 5개와 무게가 같았어요. 큰 구슬 1개는 작은 구슬 2개와 무게가 같아요. 더 무거운 것은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M1-1-u4-X16"},{"t":"무게가 같아요","mis":"M1-1-u4-X16"}],"explanation":["큰 구슬 1개 = 작은 구슬 2개예요.","㉮는 작은 구슬로 6개만큼이에요.","6개는 5개보다 많으니 ㉮가 더 무거워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L03_challenge#9','math',1,1,'u4','L03','g1_1_math_u4_L03_challenge','lesson_challenge','M1-1-u4-C7',4,'mc','auto','사과 1개는 귤 3개와, 배 1개는 귤 5개와 무게가 같아요. 사과와 배 가운데 더 무거운 것은 어느 것인가요?',ARRAY['M1-1-u4-X15','M1-1-u4-X14']::text[],true,'{"seq":9,"concept":"M1-1-u4-C7","difficulty":4,"kind":"mc","stem":"사과 1개는 귤 3개와, 배 1개는 귤 5개와 무게가 같아요. 사과와 배 가운데 더 무거운 것은 어느 것인가요?","options":[{"t":"배","correct":true},{"t":"사과","mis":"M1-1-u4-X15"},{"t":"무게가 같아요","mis":"M1-1-u4-X14"}],"explanation":["사과는 귤 3개만큼, 배는 귤 5개만큼 무거워요.","귤 5개가 귤 3개보다 무거워요.","그래서 배가 더 무거워요."],"variant_rule":{"alt":[{"stem":"필통 1개는 지우개 4개와, 공책 1권은 지우개 2개와 무게가 같아요. 필통과 공책 가운데 더 가벼운 것은 어느 것인가요?","options":[{"t":"공책","correct":true},{"t":"필통","mis":"M1-1-u4-X15"},{"t":"무게가 같아요","mis":"M1-1-u4-X14"}],"explanation":["필통은 지우개 4개만큼, 공책은 지우개 2개만큼 무거워요.","지우개 2개가 더 가벼워요.","그래서 공책이 더 가벼워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L03_challenge#10','math',1,1,'u4','L03','g1_1_math_u4_L03_challenge','lesson_challenge','M1-1-u4-C2',4,'essay','teacher','크기가 큰 것이 언제나 더 무거운 것은 아니에요. 그 까닭을 예를 들어 쓰고, 무게를 바르게 견주는 방법을 말해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M1-1-u4-C2","difficulty":4,"kind":"essay","stem":"크기가 큰 것이 언제나 더 무거운 것은 아니에요. 그 까닭을 예를 들어 쓰고, 무게를 바르게 견주는 방법을 말해 보세요.","answer_guide":{"answer":"큰 빈 상자는 작은 돌보다 가벼울 수 있다. 무게는 크기로 정할 수 없으니 양손에 들어 보거나 양팔저울에 올려 내려가는 쪽을 본다.","scoring_points":["큰데 가벼운(또는 작은데 무거운) 예를 들었는가","크기로 무게를 정할 수 없다고 말했는가","들어 보기나 양팔저울을 방법으로 말했는가"]},"explanation":["큰 풍선, 큰 빈 상자는 가벼워요.","작은 돌, 작은 쇠공은 무거울 수 있어요.","들어 보거나 저울에 올려 견주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L04_basic#1','math',1,1,'u4','L04','g1_1_math_u4_L04_basic','lesson_basic','M1-1-u4-C3',1,'mc','auto','종이 두 장을 겹쳐 보았어요. 더 넓은 것은 어느 것인가요?',ARRAY['M1-1-u4-X07']::text[],true,'{"seq":1,"concept":"M1-1-u4-C3","difficulty":1,"kind":"mc","stem":"종이 두 장을 겹쳐 보았어요. 더 넓은 것은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M1-1-u4-X07"},{"t":"넓이가 같아요","mis":"M1-1-u4-X07"}],"explanation":["㉯를 ㉮ 위에 겹쳤어요.","㉯는 ㉮ 안에 다 들어가고 ㉮가 둘레에 남아요.","남는 쪽 ㉮가 더 넓어요."],"asset":{"type":"area_shapes","mode":"overlap","shapes":[{"label":"㉮","w":6,"h":4},{"label":"㉯","w":3,"h":2}]},"variant_rule":{"cmp4":{"ask":"most"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L04_basic#2','math',1,1,'u4','L04','g1_1_math_u4_L04_basic','lesson_basic','M1-1-u4-C3',1,'mc','auto','두 모양을 나란히 놓았어요. 더 좁은 것은 어느 것인가요?',ARRAY['M1-1-u4-X15','M1-1-u4-X06']::text[],true,'{"seq":2,"concept":"M1-1-u4-C3","difficulty":1,"kind":"mc","stem":"두 모양을 나란히 놓았어요. 더 좁은 것은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M1-1-u4-X15"},{"t":"넓이가 같아요","mis":"M1-1-u4-X06"}],"explanation":["㉮는 크고 ㉯는 작아요.","차이가 크면 눈으로 보아도 알 수 있어요.","더 좁은 것은 ㉯예요."],"asset":{"type":"area_shapes","mode":"side","shapes":[{"label":"㉮","w":5,"h":4},{"label":"㉯","w":2,"h":2}]},"variant_rule":{"cmp4":{"ask":"least"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L04_basic#3','math',1,1,'u4','L04','g1_1_math_u4_L04_basic','lesson_basic','M1-1-u4-C6',1,'ox','auto','운동장은 교실보다 더 넓어요.',ARRAY['M1-1-u4-X12']::text[],true,'{"seq":3,"concept":"M1-1-u4-C6","difficulty":1,"kind":"ox","stem":"운동장은 교실보다 더 넓어요.","answer":"O","reason_options":[{"t":"운동장 바닥이 교실 바닥보다 더 크게 펼쳐져 있으니까","correct":true},{"t":"넓이는 「더 길다」라고 말해야 하니까","mis":"M1-1-u4-X12"}],"mis":"M1-1-u4-X12","explanation":["운동장 바닥과 교실 바닥을 견주어요.","운동장이 더 넓어요.","넓이는 「더 넓다·더 좁다」로 말해요."],"variant_rule":{"alt":[{"stem":"손수건은 돗자리보다 더 넓어요.","answer":"X","reason_options":[{"t":"돗자리 위에 손수건을 겹치면 돗자리가 남으니까","correct":true},{"t":"손수건이 더 무거우니까","mis":"M1-1-u4-X12"}],"explanation":["손수건을 돗자리 위에 겹쳐 봐요.","돗자리가 둘레에 남아요 — 돗자리가 더 넓어요.","손수건은 돗자리보다 더 좁아요."],"asset":null},{"stem":"칠판은 공책보다 더 넓어요.","answer":"O","reason_options":[{"t":"공책을 칠판에 대면 칠판이 둘레에 많이 남으니까","correct":true},{"t":"칠판이 더 길기 때문에 「더 길다」만 맞으니까","mis":"M1-1-u4-X12"}],"explanation":["공책을 칠판에 대어 봐요.","칠판이 둘레에 남아요 — 칠판이 더 넓어요.","넓이는 「더 넓다·더 좁다」로 말해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L04_basic#4','math',1,1,'u4','L04','g1_1_math_u4_L04_basic','lesson_basic','M1-1-u4-C6',1,'blank','auto','수첩이 책보다 더 좁아요. 그러면 책은 수첩보다 더 (        ).',ARRAY['M1-1-u4-X13','M1-1-u4-X12']::text[],true,'{"seq":4,"concept":"M1-1-u4-C6","difficulty":1,"kind":"blank","stem":"수첩이 책보다 더 좁아요. 그러면 책은 수첩보다 더 (        ).","options":[{"t":"넓어요","correct":true},{"t":"좁아요","mis":"M1-1-u4-X13"},{"t":"많아요","mis":"M1-1-u4-X12"}],"explanation":["수첩이 더 좁다면","거꾸로 책은 수첩보다 더 넓어요.","견주는 방향이 바뀌면 반대말을 써요."],"variant_rule":{"alt":[{"stem":"교실이 운동장보다 더 좁아요. 그러면 운동장은 교실보다 더 (        ).","options":[{"t":"넓어요","correct":true},{"t":"좁아요","mis":"M1-1-u4-X13"},{"t":"길어요","mis":"M1-1-u4-X12"}],"explanation":["교실이 더 좁다면","거꾸로 운동장은 교실보다 더 넓어요.","넓이는 「넓다·좁다」로 말해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L04_basic#5','math',1,1,'u4','L04','g1_1_math_u4_L04_basic','lesson_basic','M1-1-u4-C3',2,'mc','auto','칸을 세어 보고 더 넓은 것을 고르세요.',ARRAY['M1-1-u4-X06']::text[],true,'{"seq":5,"concept":"M1-1-u4-C3","difficulty":2,"kind":"mc","stem":"칸을 세어 보고 더 넓은 것을 고르세요.","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M1-1-u4-X06"},{"t":"넓이가 같아요","mis":"M1-1-u4-X06"}],"explanation":["㉮는 12칸, ㉯는 10칸이에요.","㉯가 가로로 더 길지만 칸 수는 ㉮가 더 많아요.","더 넓은 것은 ㉮예요."],"asset":{"type":"area_shapes","mode":"grid","shapes":[{"label":"㉮","w":3,"h":4},{"label":"㉯","w":5,"h":2}]},"variant_rule":{"cmp4":{"ask":"most"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L04_basic#6','math',1,1,'u4','L04','g1_1_math_u4_L04_basic','lesson_basic','M1-1-u4-C3',2,'sa','auto','㉮는 ㉯보다 몇 칸 더 넓은가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M1-1-u4-C3","difficulty":2,"kind":"sa","stem":"㉮는 ㉯보다 몇 칸 더 넓은가요? 숫자로 쓰세요.","answer":["1"],"explanation":["㉮는 9칸, ㉯는 8칸이에요.","9칸은 8칸보다 1칸 더 많아요.","그래서 ㉮가 1칸 더 넓어요."],"asset":{"type":"area_shapes","mode":"grid","shapes":[{"label":"㉮","w":3,"h":3},{"label":"㉯","w":4,"h":2}]},"variant_rule":{"cmp4":{}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L04_basic#7','math',1,1,'u4','L04','g1_1_math_u4_L04_basic','lesson_basic','M1-1-u4-C7',2,'mc','auto','칸을 세어 보고 가장 넓은 것을 고르세요.',ARRAY['M1-1-u4-X06','M1-1-u4-X15']::text[],true,'{"seq":7,"concept":"M1-1-u4-C7","difficulty":2,"kind":"mc","stem":"칸을 세어 보고 가장 넓은 것을 고르세요.","options":[{"t":"㉰","correct":true},{"t":"㉮","mis":"M1-1-u4-X06"},{"t":"㉯","mis":"M1-1-u4-X15"}],"explanation":["㉮ 10칸, ㉯ 9칸, ㉰ 12칸이에요.","㉮는 한 변이 가장 길지만 칸 수는 ㉰가 가장 많아요.","가장 넓은 것은 ㉰예요."],"asset":{"type":"area_shapes","mode":"grid","shapes":[{"label":"㉮","w":5,"h":2},{"label":"㉯","w":3,"h":3},{"label":"㉰","w":4,"h":3}]},"variant_rule":{"cmp4":{"ask":"most"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L04_basic#8','math',1,1,'u4','L04','g1_1_math_u4_L04_basic','lesson_basic','M1-1-u4-C6',2,'match','auto','견주는 것과 알맞은 방법을 이어 보세요.','{}'::text[],true,'{"seq":8,"concept":"M1-1-u4-C6","difficulty":2,"kind":"match","stem":"견주는 것과 알맞은 방법을 이어 보세요.","pairs":[{"l":"길이","r":"끝을 맞추어 대어 보기"},{"l":"무게","r":"양팔저울에 올리기"},{"l":"넓이","r":"겹쳐 보기"}],"mis":"M1-1-u4-X12","explanation":["길이는 끝을 맞추어 대어 봐요.","무게는 저울에, 넓이는 겹쳐 봐요.","무엇을 견주는지에 따라 방법이 달라요."],"variant_rule":{"alt":[{"stem":"견주는 것과 알맞은 비교 말을 이어 보세요.","pairs":[{"l":"넓이","r":"더 넓다"},{"l":"길이","r":"더 짧다"},{"l":"무게","r":"더 가볍다"}],"explanation":["넓이는 「넓다·좁다」로 말해요.","길이는 「길다·짧다」, 무게는 「무겁다·가볍다」예요.","무엇을 견주는지 먼저 봐요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L04_basic#9','math',1,1,'u4','L04','g1_1_math_u4_L04_basic','lesson_basic','M1-1-u4-C3',2,'ox','auto','작은 종이를 큰 종이 위에 겹쳤어요. 위에 놓인 ㉯가 더 넓어요.',ARRAY['M1-1-u4-X07']::text[],true,'{"seq":9,"concept":"M1-1-u4-C3","difficulty":2,"kind":"ox","stem":"작은 종이를 큰 종이 위에 겹쳤어요. 위에 놓인 ㉯가 더 넓어요.","answer":"X","reason_options":[{"t":"㉯가 ㉮ 안에 다 들어가고 ㉮가 둘레에 남으니까","correct":true},{"t":"위에 놓인 것이 더 넓으니까","mis":"M1-1-u4-X07"}],"mis":"M1-1-u4-X07","explanation":["㉯는 위에 놓였지만 ㉮ 안에 다 들어가요.","둘레에 남는 ㉮가 더 넓어요.","위아래가 아니라 남는 곳을 봐요."],"asset":{"type":"area_shapes","mode":"overlap","shapes":[{"label":"㉮","w":5,"h":4},{"label":"㉯","w":3,"h":3}]},"variant_rule":{"cmp4":{}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L04_basic#10','math',1,1,'u4','L04','g1_1_math_u4_L04_basic','lesson_basic','M1-1-u4-C3',3,'error','auto','두 모양을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M1-1-u4-X06']::text[],true,'{"seq":10,"concept":"M1-1-u4-C3","difficulty":3,"kind":"error","stem":"두 모양을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하루: ㉮가 더 길쭉하니까 더 넓어.","correct":true,"mis_target":"M1-1-u4-X06"},{"t":"지우: 칸을 세어 보니 ㉯가 9칸이야.","mis":"M1-1-u4-X06"},{"t":"서아: 칸이 더 많은 ㉯가 더 넓어.","mis":"M1-1-u4-X06"}],"explanation":["㉮는 6칸, ㉯는 9칸이에요.","길쭉하다고 넓은 것이 아니에요.","하루가 잘못 말했어요."],"asset":{"type":"area_shapes","mode":"grid","shapes":[{"label":"㉮","w":6,"h":1},{"label":"㉯","w":3,"h":3}]},"variant_rule":{"cmp4":{}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L04_challenge#1','math',1,1,'u4','L04','g1_1_math_u4_L04_challenge','lesson_challenge','M1-1-u4-C3',2,'mc','auto','칸을 세어 보고 더 넓은 것을 고르세요.',ARRAY['M1-1-u4-X06']::text[],true,'{"seq":1,"concept":"M1-1-u4-C3","difficulty":2,"kind":"mc","stem":"칸을 세어 보고 더 넓은 것을 고르세요.","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M1-1-u4-X06"},{"t":"넓이가 같아요","mis":"M1-1-u4-X06"}],"explanation":["㉮는 7칸, ㉯는 6칸이에요.","모양이 달라도 칸 수로 견줄 수 있어요.","더 넓은 것은 ㉮예요."],"asset":{"type":"area_shapes","mode":"grid","shapes":[{"label":"㉮","cells":[[0,0],[0,1],[1,0],[1,1],[2,0],[2,1],[2,2]]},{"label":"㉯","w":2,"h":3}]},"variant_rule":{"cmp4":{"ask":"most"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L04_challenge#2','math',1,1,'u4','L04','g1_1_math_u4_L04_challenge','lesson_challenge','M1-1-u4-C3',2,'sa','auto','㉮는 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M1-1-u4-C3","difficulty":2,"kind":"sa","stem":"㉮는 몇 칸인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["㉮의 칸을 하나씩 점을 찍으며 세어요.","위 두 줄 6칸과 아래 2칸 — 모두 8칸이에요.","모양이 울퉁불퉁해도 칸을 세면 넓이를 알 수 있어요."],"asset":{"type":"area_shapes","mode":"grid","shapes":[{"label":"㉮","cells":[[0,0],[0,1],[0,2],[1,0],[1,1],[1,2],[2,0],[3,0]]},{"label":"㉯","w":3,"h":3}]},"variant_rule":{"cmp4":{}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L04_challenge#3','math',1,1,'u4','L04','g1_1_math_u4_L04_challenge','lesson_challenge','M1-1-u4-C7',3,'mc','auto','칸을 세어 보고 가장 좁은 것을 고르세요.',ARRAY['M1-1-u4-X06','M1-1-u4-X15']::text[],true,'{"seq":3,"concept":"M1-1-u4-C7","difficulty":3,"kind":"mc","stem":"칸을 세어 보고 가장 좁은 것을 고르세요.","options":[{"t":"㉰","correct":true},{"t":"㉮","mis":"M1-1-u4-X06"},{"t":"㉯","mis":"M1-1-u4-X15"}],"explanation":["㉮ 8칸, ㉯ 9칸, ㉰ 7칸이에요.","㉰는 키가 가장 크지만 칸 수는 가장 적어요.","가장 좁은 것은 ㉰예요."],"asset":{"type":"area_shapes","mode":"grid","shapes":[{"label":"㉮","w":2,"h":4},{"label":"㉯","w":3,"h":3},{"label":"㉰","cells":[[0,0],[0,1],[0,2],[1,1],[2,1],[3,1],[4,1]]}]},"variant_rule":{"cmp4":{"ask":"least"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L04_challenge#4','math',1,1,'u4','L04','g1_1_math_u4_L04_challenge','lesson_challenge','M1-1-u4-C3',3,'mc','auto','칸을 세어 보고 더 넓은 것을 고르세요.',ARRAY['M1-1-u4-X06']::text[],true,'{"seq":4,"concept":"M1-1-u4-C3","difficulty":3,"kind":"mc","stem":"칸을 세어 보고 더 넓은 것을 고르세요.","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M1-1-u4-X06"},{"t":"넓이가 같아요","mis":"M1-1-u4-X06"}],"explanation":["㉮는 8칸, ㉯는 9칸이에요.","㉮가 가로로 훨씬 길지만 칸 수는 ㉯가 많아요.","더 넓은 것은 ㉯예요."],"asset":{"type":"area_shapes","mode":"grid","shapes":[{"label":"㉮","w":8,"h":1},{"label":"㉯","w":3,"h":3}]},"variant_rule":{"cmp4":{"ask":"most"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L04_challenge#5','math',1,1,'u4','L04','g1_1_math_u4_L04_challenge','lesson_challenge','M1-1-u4-C3',3,'ox','auto','가로가 더 긴 모양이 언제나 더 넓어요.',ARRAY['M1-1-u4-X06']::text[],true,'{"seq":5,"concept":"M1-1-u4-C3","difficulty":3,"kind":"ox","stem":"가로가 더 긴 모양이 언제나 더 넓어요.","answer":"X","reason_options":[{"t":"세로가 짧으면 가로가 길어도 더 좁을 수 있으니까","correct":true},{"t":"가로가 길면 넓으니까","mis":"M1-1-u4-X06"}],"mis":"M1-1-u4-X06","explanation":["가로 8칸·세로 1칸은 8칸이에요.","가로 3칸·세로 3칸은 9칸이에요.","한 변만 보고 넓이를 정할 수 없어요."],"variant_rule":{"alt":[{"stem":"세로가 더 긴 모양이 언제나 더 넓어요.","answer":"X","reason_options":[{"t":"가로가 좁으면 세로가 길어도 더 좁을 수 있으니까","correct":true},{"t":"키가 크면 넓으니까","mis":"M1-1-u4-X06"}],"explanation":["세로 6칸·가로 1칸은 6칸이에요.","가로 3칸·세로 3칸은 9칸이에요.","한 변만 보고 넓이를 정할 수 없어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L04_challenge#6','math',1,1,'u4','L04','g1_1_math_u4_L04_challenge','lesson_challenge','M1-1-u4-C3',3,'mc','auto','크기가 같은 종이 두 장 가운데 ㉮만 반으로 한 번 접었어요. 지금 더 넓은 것은 어느 것인가요?',ARRAY['M1-1-u4-X15','M1-1-u4-X06']::text[],true,'{"seq":6,"concept":"M1-1-u4-C3","difficulty":3,"kind":"mc","stem":"크기가 같은 종이 두 장 가운데 ㉮만 반으로 한 번 접었어요. 지금 더 넓은 것은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M1-1-u4-X15"},{"t":"넓이가 같아요","mis":"M1-1-u4-X06"}],"explanation":["접기 전에는 두 종이의 넓이가 같았어요.","㉮를 반으로 접으니 반만 남았어요.","지금은 ㉯가 더 넓어요."],"variant_rule":{"alt":[{"stem":"크기가 같은 종이 두 장 가운데 ㉯만 반으로 두 번 접었어요. 지금 더 좁은 것은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M1-1-u4-X15"},{"t":"넓이가 같아요","mis":"M1-1-u4-X06"}],"explanation":["접기 전에는 두 종이의 넓이가 같았어요.","㉯는 두 번 접어 더 작아졌어요.","지금은 ㉯가 더 좁아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L04_challenge#7','math',1,1,'u4','L04','g1_1_math_u4_L04_challenge','lesson_challenge','M1-1-u4-C7',3,'blank','auto','㉮는 ㉯보다 넓고, ㉯는 ㉰보다 넓어요. 가장 좁은 것은 (        )예요.',ARRAY['M1-1-u4-X15','M1-1-u4-X14']::text[],true,'{"seq":7,"concept":"M1-1-u4-C7","difficulty":3,"kind":"blank","stem":"㉮는 ㉯보다 넓고, ㉯는 ㉰보다 넓어요. 가장 좁은 것은 (        )예요.","options":[{"t":"㉰","correct":true},{"t":"㉮","mis":"M1-1-u4-X15"},{"t":"㉯","mis":"M1-1-u4-X14"}],"explanation":["㉮ > ㉯, ㉯ > ㉰ 예요.","넓은 차례는 ㉮, ㉯, ㉰예요.","가장 좁은 것은 ㉰예요."],"variant_rule":{"alt":[{"stem":"㉰는 ㉮보다 넓고, ㉮는 ㉯보다 넓어요. 가장 넓은 것은 (        )예요.","options":[{"t":"㉰","correct":true},{"t":"㉯","mis":"M1-1-u4-X15"},{"t":"㉮","mis":"M1-1-u4-X14"}],"explanation":["㉰ > ㉮, ㉮ > ㉯ 예요.","넓은 차례는 ㉰, ㉮, ㉯예요.","가장 넓은 것은 ㉰예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L04_challenge#8','math',1,1,'u4','L04','g1_1_math_u4_L04_challenge','lesson_challenge','M1-1-u4-C3',4,'mc','auto','칸을 세어 보고 알맞은 말을 고르세요.',ARRAY['M1-1-u4-X06']::text[],true,'{"seq":8,"concept":"M1-1-u4-C3","difficulty":4,"kind":"mc","stem":"칸을 세어 보고 알맞은 말을 고르세요.","options":[{"t":"넓이가 같아요","correct":true},{"t":"㉯","mis":"M1-1-u4-X06"},{"t":"㉮","mis":"M1-1-u4-X06"}],"explanation":["㉮는 가로 4칸·세로 3칸 — 12칸이에요.","㉯는 가로 2칸·세로 6칸 — 12칸이에요.","모양은 달라도 넓이는 같아요."],"asset":{"type":"area_shapes","mode":"grid","shapes":[{"label":"㉮","w":4,"h":3},{"label":"㉯","w":2,"h":6}]},"variant_rule":{"cmp4":{}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L04_challenge#9','math',1,1,'u4','L04','g1_1_math_u4_L04_challenge','lesson_challenge','M1-1-u4-C7',4,'mc','auto','큰 타일 1장은 작은 타일 2장과 넓이가 같아요. ㉮는 큰 타일 4장, ㉯는 작은 타일 6장으로 빈틈없이 덮였어요. 더 넓은 것은 어느 것인가요?',ARRAY['M1-1-u4-X16']::text[],true,'{"seq":9,"concept":"M1-1-u4-C7","difficulty":4,"kind":"mc","stem":"큰 타일 1장은 작은 타일 2장과 넓이가 같아요. ㉮는 큰 타일 4장, ㉯는 작은 타일 6장으로 빈틈없이 덮였어요. 더 넓은 것은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M1-1-u4-X16"},{"t":"넓이가 같아요","mis":"M1-1-u4-X16"}],"explanation":["큰 타일 4장은 작은 타일 8장만큼이에요.","㉮는 작은 타일 8장, ㉯는 6장만큼이에요.","그래서 ㉮가 더 넓어요."],"variant_rule":{"alt":[{"stem":"큰 타일 1장은 작은 타일 2장과 넓이가 같아요. ㉮는 큰 타일 3장, ㉯는 작은 타일 7장으로 빈틈없이 덮였어요. 더 넓은 것은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M1-1-u4-X16"},{"t":"넓이가 같아요","mis":"M1-1-u4-X16"}],"explanation":["큰 타일 3장은 작은 타일 6장만큼이에요.","㉮는 작은 타일 6장, ㉯는 7장만큼이에요.","그래서 ㉯가 더 넓어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L04_challenge#10','math',1,1,'u4','L04','g1_1_math_u4_L04_challenge','lesson_challenge','M1-1-u4-C3',4,'essay','teacher','모양이 다른 두 종이 가운데 어느 것이 더 넓은지 알아보려고 해요. 어떻게 견주면 좋을지 두 가지 방법을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M1-1-u4-C3","difficulty":4,"kind":"essay","stem":"모양이 다른 두 종이 가운데 어느 것이 더 넓은지 알아보려고 해요. 어떻게 견주면 좋을지 두 가지 방법을 쓰세요.","answer_guide":{"answer":"① 두 종이를 겹쳐 보아 둘레에 남는 쪽이 더 넓다(남는 곳이 양쪽에 있으면 잘라 붙여 본다). ② 같은 크기의 칸(모눈)을 그려 칸 수를 세어 더 많은 쪽이 더 넓다.","scoring_points":["겹쳐 보기를 말했는가","같은 크기 칸 세기를 말했는가","한 변만 보면 안 된다는 것을 드러냈는가"]},"explanation":["겹쳐 보아 남는 쪽을 찾아요.","같은 크기 칸을 그려 칸 수를 세어요.","한 변의 길이만 보고 정하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L05_basic#1','math',1,1,'u4','L05','g1_1_math_u4_L05_basic','lesson_basic','M1-1-u4-C4',1,'mc','auto','빈 그릇 두 개예요. 더 많이 담을 수 있는 그릇은 어느 것인가요?',ARRAY['M1-1-u4-X15','M1-1-u4-X08']::text[],true,'{"seq":1,"concept":"M1-1-u4-C4","difficulty":1,"kind":"mc","stem":"빈 그릇 두 개예요. 더 많이 담을 수 있는 그릇은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M1-1-u4-X15"},{"t":"담을 수 있는 양이 같아요","mis":"M1-1-u4-X08"}],"explanation":["㉮가 ㉯보다 훨씬 커요.","차이가 크면 눈으로 보아도 알 수 있어요.","㉮에 더 많이 담을 수 있어요."],"asset":{"type":"cups","items":[{"label":"㉮","w":4,"h":5,"fill":0},{"label":"㉯","w":2,"h":2,"fill":0}]},"variant_rule":{"cmp4":{"ask":"most","by":"cap"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L05_basic#2','math',1,1,'u4','L05','g1_1_math_u4_L05_basic','lesson_basic','M1-1-u4-C5',1,'mc','auto','크기가 같은 컵 세 개에 물이 들어 있어요. 물이 가장 많이 담긴 컵은 어느 것인가요?',ARRAY['M1-1-u4-X15','M1-1-u4-X09']::text[],true,'{"seq":2,"concept":"M1-1-u4-C5","difficulty":1,"kind":"mc","stem":"크기가 같은 컵 세 개에 물이 들어 있어요. 물이 가장 많이 담긴 컵은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M1-1-u4-X15"},{"t":"㉰","mis":"M1-1-u4-X09"}],"explanation":["세 컵은 크기가 같아요.","같은 컵이면 물 높이가 가장 높은 컵에 물이 가장 많아요.","물이 가장 많이 담긴 컵은 ㉮예요."],"asset":{"type":"cups","items":[{"label":"㉮","w":3,"h":5,"fill":0.8},{"label":"㉯","w":3,"h":5,"fill":0.4},{"label":"㉰","w":3,"h":5,"fill":0.6}],"same":true},"variant_rule":{"cmp4":{"ask":"most","by":"fill"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L05_basic#3','math',1,1,'u4','L05','g1_1_math_u4_L05_basic','lesson_basic','M1-1-u4-C4',1,'ox','auto','㉮에 가득 담은 물을 ㉯에 부었더니 넘쳤어요. ㉮에 더 많이 담을 수 있어요.',ARRAY['M1-1-u4-X10']::text[],true,'{"seq":3,"concept":"M1-1-u4-C4","difficulty":1,"kind":"ox","stem":"㉮에 가득 담은 물을 ㉯에 부었더니 넘쳤어요. ㉮에 더 많이 담을 수 있어요.","answer":"O","reason_options":[{"t":"㉯가 ㉮의 물을 다 받지 못했으니까","correct":true},{"t":"넘친 ㉯가 더 크니까","mis":"M1-1-u4-X10"}],"mis":"M1-1-u4-X10","explanation":["㉮의 물을 ㉯에 다 붓지 못하고 넘쳤어요.","㉯가 ㉮보다 적게 담을 수 있다는 뜻이에요.","그래서 ㉮에 더 많이 담을 수 있어요."],"asset":{"type":"cups","items":[{"label":"㉮","w":3,"h":4,"fill":1},{"label":"㉯","w":2,"h":4,"fill":0}],"pour":{"from":0,"to":1}},"variant_rule":{"cmp4":{}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L05_basic#4','math',1,1,'u4','L05','g1_1_math_u4_L05_basic','lesson_basic','M1-1-u4-C6',1,'blank','auto','주전자에 컵보다 더 많이 담을 수 있어요. 그러면 컵에는 주전자보다 더 (        ) 담을 수 있어요.',ARRAY['M1-1-u4-X13','M1-1-u4-X12']::text[],true,'{"seq":4,"concept":"M1-1-u4-C6","difficulty":1,"kind":"blank","stem":"주전자에 컵보다 더 많이 담을 수 있어요. 그러면 컵에는 주전자보다 더 (        ) 담을 수 있어요.","options":[{"t":"적게","correct":true},{"t":"많이","mis":"M1-1-u4-X13"},{"t":"짧게","mis":"M1-1-u4-X12"}],"explanation":["주전자에 더 많이 담을 수 있다면","거꾸로 컵에는 주전자보다 더 적게 담을 수 있어요.","견주는 방향이 바뀌면 반대말을 써요."],"variant_rule":{"alt":[{"stem":"양동이에 물병보다 더 많이 담을 수 있어요. 그러면 물병에는 양동이보다 더 (        ) 담을 수 있어요.","options":[{"t":"적게","correct":true},{"t":"많이","mis":"M1-1-u4-X13"},{"t":"가볍게","mis":"M1-1-u4-X12"}],"explanation":["양동이에 더 많이 담을 수 있다면","거꾸로 물병에는 더 적게 담을 수 있어요.","들이는 「많다·적다」로 말해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L05_basic#5','math',1,1,'u4','L05','g1_1_math_u4_L05_basic','lesson_basic','M1-1-u4-C4',2,'mc','auto','좁고 높은 ㉮에 가득 담은 물을 넓고 낮은 ㉯에 부었더니 빈 곳이 남았어요. 더 많이 담을 수 있는 그릇은 어느 것인가요?',ARRAY['M1-1-u4-X08','M1-1-u4-X11']::text[],true,'{"seq":5,"concept":"M1-1-u4-C4","difficulty":2,"kind":"mc","stem":"좁고 높은 ㉮에 가득 담은 물을 넓고 낮은 ㉯에 부었더니 빈 곳이 남았어요. 더 많이 담을 수 있는 그릇은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M1-1-u4-X08"},{"t":"담을 수 있는 양이 같아요","mis":"M1-1-u4-X11"}],"explanation":["㉮의 물을 ㉯에 다 부었는데 빈 곳이 남았어요.","㉯가 ㉮보다 더 많이 담을 수 있다는 뜻이에요.","높이만 보고 정하면 안 돼요 — ㉯예요."],"asset":{"type":"cups","items":[{"label":"㉮","w":2,"h":6,"fill":1},{"label":"㉯","w":5,"h":3,"fill":0}],"pour":{"from":0,"to":1}},"variant_rule":{"cmp4":{"ask":"most","by":"cap"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L05_basic#6','math',1,1,'u4','L05','g1_1_math_u4_L05_basic','lesson_basic','M1-1-u4-C5',2,'mc','auto','큰 그릇 ㉮에는 물이 조금, 작은 그릇 ㉯에는 물이 가득 들어 있어요. 담을 수 있는 양이 더 많은 그릇은 어느 것인가요?',ARRAY['M1-1-u4-X09','M1-1-u4-X11']::text[],true,'{"seq":6,"concept":"M1-1-u4-C5","difficulty":2,"kind":"mc","stem":"큰 그릇 ㉮에는 물이 조금, 작은 그릇 ㉯에는 물이 가득 들어 있어요. 담을 수 있는 양이 더 많은 그릇은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M1-1-u4-X09"},{"t":"알 수 없어요","mis":"M1-1-u4-X11"}],"explanation":["담을 수 있는 양은 그릇의 크기예요.","물이 얼마나 들어 있는지와는 달라요.","그릇이 더 큰 ㉮에 더 많이 담을 수 있어요."],"asset":{"type":"cups","items":[{"label":"㉮","w":5,"h":5,"fill":0.2},{"label":"㉯","w":2,"h":3,"fill":1}]},"variant_rule":{"cmp4":{"ask":"most","by":"cap"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L05_basic#7','math',1,1,'u4','L05','g1_1_math_u4_L05_basic','lesson_basic','M1-1-u4-C5',2,'sa','auto','크기가 같은 컵 세 개예요. 물이 가장 적게 담긴 컵을 쓰세요. (㉮, ㉯, ㉰ 가운데 하나)','{}'::text[],true,'{"seq":7,"concept":"M1-1-u4-C5","difficulty":2,"kind":"sa","stem":"크기가 같은 컵 세 개예요. 물이 가장 적게 담긴 컵을 쓰세요. (㉮, ㉯, ㉰ 가운데 하나)","answer":["㉯"],"explanation":["세 컵은 크기가 같아요.","물 높이가 가장 낮은 컵에 물이 가장 적어요.","가장 적게 담긴 컵은 ㉯예요."],"asset":{"type":"cups","items":[{"label":"㉮","w":3,"h":5,"fill":0.6},{"label":"㉯","w":3,"h":5,"fill":0.2},{"label":"㉰","w":3,"h":5,"fill":0.9}],"same":true},"variant_rule":{"cmp4":{"ask":"least","by":"fill"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L05_basic#8','math',1,1,'u4','L05','g1_1_math_u4_L05_basic','lesson_basic','M1-1-u4-C4',2,'match','auto','옮겨 담은 결과와 알맞은 말을 이어 보세요.','{}'::text[],false,'{"seq":8,"concept":"M1-1-u4-C4","difficulty":2,"kind":"match","stem":"옮겨 담은 결과와 알맞은 말을 이어 보세요.","pairs":[{"l":"넘쳤어요","r":"붓는 그릇에 더 많이 담을 수 있어요"},{"l":"빈 곳이 남았어요","r":"받는 그릇에 더 많이 담을 수 있어요"},{"l":"꼭 맞게 찼어요","r":"담을 수 있는 양이 같아요"}],"mis":"M1-1-u4-X10","explanation":["넘쳤다면 받는 그릇이 다 못 받은 거예요.","빈 곳이 남았다면 받는 그릇이 더 커요.","꼭 맞게 차면 담을 수 있는 양이 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L05_basic#9','math',1,1,'u4','L05','g1_1_math_u4_L05_basic','lesson_basic','M1-1-u4-C4',2,'mc','auto','하루는 두 그릇에 물을 반쯤씩 담아 물 높이를 보고 더 많이 담을 수 있는 그릇을 찾으려고 해요. 무엇을 고쳐야 하나요?',ARRAY['M1-1-u4-X11','M1-1-u4-X08']::text[],true,'{"seq":9,"concept":"M1-1-u4-C4","difficulty":2,"kind":"mc","stem":"하루는 두 그릇에 물을 반쯤씩 담아 물 높이를 보고 더 많이 담을 수 있는 그릇을 찾으려고 해요. 무엇을 고쳐야 하나요?","options":[{"t":"한 그릇에 물을 가득 담아 다른 그릇에 옮겨 부어 봐야 해요","correct":true},{"t":"반쯤 담아도 충분해요","mis":"M1-1-u4-X11"},{"t":"그릇의 높이만 재어 보면 돼요","mis":"M1-1-u4-X08"}],"explanation":["담을 수 있는 양은 가득 채워 보아야 알아요.","한 그릇에 가득 담아 다른 그릇에 부어 봐요.","넘치는지 남는지를 보면 알 수 있어요."],"variant_rule":{"alt":[{"stem":"도이는 두 컵에 물을 조금씩 넣고 「물이 더 높은 컵에 더 많이 담을 수 있어」라고 했어요. 무엇이 잘못되었나요?","options":[{"t":"가득 채우지 않고 견주었어요","correct":true},{"t":"잘못된 것이 없어요","mis":"M1-1-u4-X11"},{"t":"높은 컵을 고르면 돼요","mis":"M1-1-u4-X08"}],"explanation":["담을 수 있는 양은 가득 채워야 알아요.","조금씩 넣은 물 높이로는 알 수 없어요.","가득 담아 옮겨 부어 봐요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L05_basic#10','math',1,1,'u4','L05','g1_1_math_u4_L05_basic','lesson_basic','M1-1-u4-C4',3,'error','auto','그림을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M1-1-u4-X10']::text[],true,'{"seq":10,"concept":"M1-1-u4-C4","difficulty":3,"kind":"error","stem":"그림을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지우: ㉯가 넘쳤으니까 ㉯에 더 많이 담을 수 있어.","correct":true,"mis_target":"M1-1-u4-X10"},{"t":"하루: ㉮의 물을 ㉯가 다 받지 못했어.","mis":"M1-1-u4-X10"},{"t":"서아: ㉮에 더 많이 담을 수 있어.","mis":"M1-1-u4-X10"}],"explanation":["㉮에 가득 담은 물을 ㉯에 부었더니 넘쳤어요.","㉯가 다 받지 못했으니 ㉯가 더 적게 담아요.","지우가 거꾸로 말했어요."],"asset":{"type":"cups","items":[{"label":"㉮","w":4,"h":4,"fill":1},{"label":"㉯","w":3,"h":4,"fill":0}],"pour":{"from":0,"to":1}},"variant_rule":{"cmp4":{}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L05_challenge#1','math',1,1,'u4','L05','g1_1_math_u4_L05_challenge','lesson_challenge','M1-1-u4-C4',2,'mc','auto','㉮에 가득 담은 물을 ㉯에 부었어요. 더 많이 담을 수 있는 그릇은 어느 것인가요?',ARRAY['M1-1-u4-X10','M1-1-u4-X11']::text[],true,'{"seq":1,"concept":"M1-1-u4-C4","difficulty":2,"kind":"mc","stem":"㉮에 가득 담은 물을 ㉯에 부었어요. 더 많이 담을 수 있는 그릇은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M1-1-u4-X10"},{"t":"담을 수 있는 양이 같아요","mis":"M1-1-u4-X11"}],"explanation":["㉮의 물을 ㉯에 다 붓고도 빈 곳이 남았어요.","㉯가 ㉮보다 더 많이 담을 수 있어요.","더 많이 담을 수 있는 그릇은 ㉯예요."],"asset":{"type":"cups","items":[{"label":"㉮","w":3,"h":3,"fill":1},{"label":"㉯","w":3,"h":5,"fill":0}],"pour":{"from":0,"to":1}},"variant_rule":{"cmp4":{"ask":"most","by":"cap"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L05_challenge#2','math',1,1,'u4','L05','g1_1_math_u4_L05_challenge','lesson_challenge','M1-1-u4-C5',2,'mc','auto','크기가 같은 컵 네 개예요. 물이 가장 적게 담긴 컵은 어느 것인가요?',ARRAY['M1-1-u4-X15','M1-1-u4-X09']::text[],true,'{"seq":2,"concept":"M1-1-u4-C5","difficulty":2,"kind":"mc","stem":"크기가 같은 컵 네 개예요. 물이 가장 적게 담긴 컵은 어느 것인가요?","options":[{"t":"㉱","correct":true},{"t":"㉯","mis":"M1-1-u4-X15"},{"t":"㉰","mis":"M1-1-u4-X09"}],"explanation":["네 컵은 크기가 같아요.","물 높이가 가장 낮은 컵에 물이 가장 적어요.","가장 적게 담긴 컵은 ㉱예요."],"asset":{"type":"cups","items":[{"label":"㉮","w":2,"h":6,"fill":0.5},{"label":"㉯","w":2,"h":6,"fill":0.9},{"label":"㉰","w":2,"h":6,"fill":0.3},{"label":"㉱","w":2,"h":6,"fill":0.1}],"same":true},"variant_rule":{"cmp4":{"ask":"least","by":"fill"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L05_challenge#3','math',1,1,'u4','L05','g1_1_math_u4_L05_challenge','lesson_challenge','M1-1-u4-C4',3,'mc','auto','같은 컵으로 물을 퍼서 그릇을 가득 채웠어요. ㉮는 3컵, ㉯는 6컵, ㉰는 5컵이 들어갔어요. 가장 많이 담을 수 있는 그릇은 어느 것인가요?',ARRAY['M1-1-u4-X08','M1-1-u4-X15']::text[],true,'{"seq":3,"concept":"M1-1-u4-C4","difficulty":3,"kind":"mc","stem":"같은 컵으로 물을 퍼서 그릇을 가득 채웠어요. ㉮는 3컵, ㉯는 6컵, ㉰는 5컵이 들어갔어요. 가장 많이 담을 수 있는 그릇은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M1-1-u4-X08"},{"t":"㉰","mis":"M1-1-u4-X15"}],"explanation":["같은 컵으로 퍼 담았으니 컵 수로 견줄 수 있어요.","6컵이 가장 많아요.","㉮가 가장 높지만 가장 많이 담는 것은 ㉯예요."],"asset":{"type":"cups","items":[{"label":"㉮","w":1,"h":6,"fill":0},{"label":"㉯","w":4,"h":3,"fill":0},{"label":"㉰","w":2,"h":5,"fill":0}]},"variant_rule":{"cmp4":{"ask":"most","by":"cap"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L05_challenge#4','math',1,1,'u4','L05','g1_1_math_u4_L05_challenge','lesson_challenge','M1-1-u4-C4',3,'mc','auto','㉮의 물을 ㉯에 부으면 넘치고, ㉯의 물을 ㉰에 부으면 넘쳐요. 가장 많이 담을 수 있는 것은 어느 것인가요?',ARRAY['M1-1-u4-X10','M1-1-u4-X14']::text[],true,'{"seq":4,"concept":"M1-1-u4-C4","difficulty":3,"kind":"mc","stem":"㉮의 물을 ㉯에 부으면 넘치고, ㉯의 물을 ㉰에 부으면 넘쳐요. 가장 많이 담을 수 있는 것은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉰","mis":"M1-1-u4-X10"},{"t":"㉯","mis":"M1-1-u4-X14"}],"explanation":["㉮가 ㉯보다 많이 담아요.","㉯가 ㉰보다 많이 담아요.","그래서 ㉮에 가장 많이 담을 수 있어요."],"variant_rule":{"alt":[{"stem":"㉮의 물을 ㉯에 부으면 빈 곳이 남고, ㉯의 물을 ㉰에 부으면 빈 곳이 남아요. 가장 많이 담을 수 있는 것은 어느 것인가요?","options":[{"t":"㉰","correct":true},{"t":"㉮","mis":"M1-1-u4-X10"},{"t":"㉯","mis":"M1-1-u4-X14"}],"explanation":["㉯가 ㉮보다 많이 담아요.","㉰가 ㉯보다 많이 담아요.","그래서 ㉰에 가장 많이 담을 수 있어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L05_challenge#5','math',1,1,'u4','L05','g1_1_math_u4_L05_challenge','lesson_challenge','M1-1-u4-C5',3,'ox','auto','큰 양동이에는 물이 조금, 작은 컵에는 물이 가득 들어 있어요. 양동이에 담긴 물이 언제나 더 많아요.',ARRAY['M1-1-u4-X09']::text[],true,'{"seq":5,"concept":"M1-1-u4-C5","difficulty":3,"kind":"ox","stem":"큰 양동이에는 물이 조금, 작은 컵에는 물이 가득 들어 있어요. 양동이에 담긴 물이 언제나 더 많아요.","answer":"X","reason_options":[{"t":"양동이가 커도 물이 조금이면 컵에 담긴 물보다 적을 수 있으니까","correct":true},{"t":"양동이가 더 크니까","mis":"M1-1-u4-X09"}],"mis":"M1-1-u4-X09","explanation":["양동이가 크다는 것은 담을 수 있는 양이 많다는 뜻이에요.","지금 들어 있는 물(담긴 양)은 다를 수 있어요.","담긴 양은 물을 옮겨 보아야 알아요."],"variant_rule":{"alt":[{"stem":"크기가 같은 두 컵에서 물 높이가 더 높은 컵에 물이 더 많이 담겨 있어요.","answer":"O","reason_options":[{"t":"같은 컵이면 물 높이로 담긴 양을 견줄 수 있으니까","correct":true},{"t":"컵이 같으면 물의 양도 언제나 같으니까","mis":"M1-1-u4-X09"}],"explanation":["두 컵의 크기가 같아요.","같은 컵이면 물이 더 높은 쪽에 더 많이 담겨 있어요.","컵이 다르면 높이만으로는 알 수 없어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L05_challenge#6','math',1,1,'u4','L05','g1_1_math_u4_L05_challenge','lesson_challenge','M1-1-u4-C4',3,'mc','auto','물병의 물을 작은 컵으로, 주전자의 물을 큰 컵으로 퍼냈어요. 물병은 4컵, 주전자는 3컵이었어요. 알맞은 말은 어느 것인가요?',ARRAY['M1-1-u4-X16']::text[],true,'{"seq":6,"concept":"M1-1-u4-C4","difficulty":3,"kind":"mc","stem":"물병의 물을 작은 컵으로, 주전자의 물을 큰 컵으로 퍼냈어요. 물병은 4컵, 주전자는 3컵이었어요. 알맞은 말은 어느 것인가요?","options":[{"t":"컵 크기가 달라서 컵 수만 보고 견줄 수 없어요","correct":true},{"t":"물병에 더 많이 들어 있어요","mis":"M1-1-u4-X16"},{"t":"주전자에 더 많이 들어 있어요","mis":"M1-1-u4-X16"}],"explanation":["퍼낸 컵의 크기가 달라요.","작은 컵 4번과 큰 컵 3번은 바로 견줄 수 없어요.","같은 컵으로 퍼야 수로 견줄 수 있어요."],"variant_rule":{"alt":[{"stem":"물병의 물을 큰 컵으로, 주전자의 물을 작은 컵으로 퍼냈어요. 물병은 2컵, 주전자는 5컵이었어요. 알맞은 말은 어느 것인가요?","options":[{"t":"컵 크기가 달라서 컵 수만 보고 견줄 수 없어요","correct":true},{"t":"주전자에 더 많이 들어 있어요","mis":"M1-1-u4-X16"},{"t":"물병에 더 많이 들어 있어요","mis":"M1-1-u4-X16"}],"explanation":["퍼낸 컵의 크기가 달라요.","큰 컵 2번과 작은 컵 5번은 바로 견줄 수 없어요.","같은 컵으로 퍼야 수로 견줄 수 있어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L05_challenge#7','math',1,1,'u4','L05','g1_1_math_u4_L05_challenge','lesson_challenge','M1-1-u4-C4',3,'error','auto','모양이 다른 두 컵을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M1-1-u4-X08','M1-1-u4-X11']::text[],true,'{"seq":7,"concept":"M1-1-u4-C4","difficulty":3,"kind":"error","stem":"모양이 다른 두 컵을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하루: 물 높이가 같으니까 두 컵에 담긴 물도 언제나 같아.","correct":true,"mis_target":"M1-1-u4-X08"},{"t":"도이: 넓은 컵에 물이 더 많을 수 있어.","mis":"M1-1-u4-X08"},{"t":"유나: 한쪽 물을 다른 컵에 부어 보면 알 수 있어.","mis":"M1-1-u4-X11"}],"explanation":["컵의 넓이가 다르면 물 높이가 같아도 양이 달라요.","넓은 컵에 물이 더 많이 들어 있어요.","하루가 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"모양이 다른 두 그릇을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서아: 더 높은 그릇에 언제나 더 많이 담을 수 있어.","correct":true,"mis_target":"M1-1-u4-X08"},{"t":"지우: 낮아도 넓으면 더 많이 담을 수 있어.","mis":"M1-1-u4-X08"},{"t":"하루: 가득 담아 옮겨 부어 보자.","mis":"M1-1-u4-X11"}],"explanation":["높이만 보고는 알 수 없어요.","낮고 넓은 그릇이 더 많이 담을 수도 있어요.","서아가 잘못 말했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L05_challenge#8','math',1,1,'u4','L05','g1_1_math_u4_L05_challenge','lesson_challenge','M1-1-u4-C4',4,'mc','auto','같은 컵으로 ㉮에는 7번, ㉯에는 5번 부으니 가득 찼어요. ㉯에 가득 담은 물을 ㉮에 부으면 어떻게 되나요?',ARRAY['M1-1-u4-X10','M1-1-u4-X16']::text[],true,'{"seq":8,"concept":"M1-1-u4-C4","difficulty":4,"kind":"mc","stem":"같은 컵으로 ㉮에는 7번, ㉯에는 5번 부으니 가득 찼어요. ㉯에 가득 담은 물을 ㉮에 부으면 어떻게 되나요?","options":[{"t":"빈 곳이 남아요","correct":true},{"t":"넘쳐요","mis":"M1-1-u4-X10"},{"t":"꼭 맞게 차요","mis":"M1-1-u4-X16"}],"explanation":["㉮는 7컵, ㉯는 5컵을 담을 수 있어요.","5컵을 7컵짜리 그릇에 부어요.","2컵만큼 빈 곳이 남아요."],"variant_rule":{"alt":[{"stem":"같은 컵으로 ㉮에는 4번, ㉯에는 6번 부으니 가득 찼어요. ㉯에 가득 담은 물을 ㉮에 부으면 어떻게 되나요?","options":[{"t":"넘쳐요","correct":true},{"t":"빈 곳이 남아요","mis":"M1-1-u4-X10"},{"t":"꼭 맞게 차요","mis":"M1-1-u4-X16"}],"explanation":["㉮는 4컵, ㉯는 6컵을 담을 수 있어요.","6컵을 4컵짜리 그릇에 부어요.","다 담지 못해 넘쳐요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L05_challenge#9','math',1,1,'u4','L05','g1_1_math_u4_L05_challenge','lesson_challenge','M1-1-u4-C7',4,'mc','auto','㉮는 ㉯보다, ㉯는 ㉰보다, ㉱는 ㉮보다 더 많이 담을 수 있어요. 가장 적게 담을 수 있는 것은 어느 것인가요?',ARRAY['M1-1-u4-X15','M1-1-u4-X14']::text[],true,'{"seq":9,"concept":"M1-1-u4-C7","difficulty":4,"kind":"mc","stem":"㉮는 ㉯보다, ㉯는 ㉰보다, ㉱는 ㉮보다 더 많이 담을 수 있어요. 가장 적게 담을 수 있는 것은 어느 것인가요?","options":[{"t":"㉰","correct":true},{"t":"㉱","mis":"M1-1-u4-X15"},{"t":"㉯","mis":"M1-1-u4-X14"}],"explanation":["㉱ > ㉮, ㉮ > ㉯, ㉯ > ㉰ 예요.","많이 담는 차례는 ㉱, ㉮, ㉯, ㉰예요.","가장 적게 담을 수 있는 것은 ㉰예요."],"variant_rule":{"alt":[{"stem":"㉯는 ㉮보다, ㉰는 ㉯보다, ㉮는 ㉱보다 더 많이 담을 수 있어요. 가장 많이 담을 수 있는 것은 어느 것인가요?","options":[{"t":"㉰","correct":true},{"t":"㉱","mis":"M1-1-u4-X15"},{"t":"㉯","mis":"M1-1-u4-X14"}],"explanation":["㉰ > ㉯, ㉯ > ㉮, ㉮ > ㉱ 예요.","많이 담는 차례는 ㉰, ㉯, ㉮, ㉱예요.","가장 많이 담을 수 있는 것은 ㉰예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_L05_challenge#10','math',1,1,'u4','L05','g1_1_math_u4_L05_challenge','lesson_challenge','M1-1-u4-C5',4,'essay','teacher','「담을 수 있는 양」과 「담긴 양」은 어떻게 다른가요? 집에 있는 그릇으로 예를 들어 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M1-1-u4-C5","difficulty":4,"kind":"essay","stem":"「담을 수 있는 양」과 「담긴 양」은 어떻게 다른가요? 집에 있는 그릇으로 예를 들어 설명해 보세요.","answer_guide":{"answer":"담을 수 있는 양은 그릇에 가득 채웠을 때의 양(그릇의 크기)이고, 담긴 양은 지금 그릇 안에 들어 있는 물의 양이다. 예: 큰 냄비는 담을 수 있는 양이 많지만 물을 조금 넣으면 담긴 양은 적다.","scoring_points":["담을 수 있는 양 = 가득 채운 양(그릇 크기)이라고 했는가","담긴 양 = 지금 들어 있는 양이라고 했는가","두 양이 다른 그릇 예를 들었는가"]},"explanation":["담을 수 있는 양은 가득 채웠을 때의 양이에요.","담긴 양은 지금 들어 있는 물의 양이에요.","큰 그릇에도 물이 조금만 담겨 있을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_a#1','math',1,1,'u4','','g1_1_math_u4_review_a','unit_review','M1-1-u4-C1',1,'mc','auto','끝을 맞추어 놓았어요. 더 긴 것은 어느 것인가요?',ARRAY['M1-1-u4-X15','M1-1-u4-X01']::text[],true,'{"seq":1,"concept":"M1-1-u4-C1","difficulty":1,"kind":"mc","stem":"끝을 맞추어 놓았어요. 더 긴 것은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M1-1-u4-X15"},{"t":"길이가 같아요","mis":"M1-1-u4-X01"}],"explanation":["왼쪽 끝이 맞추어져 있어요.","오른쪽 끝이 더 나간 ㉮가 더 길어요.","끝을 맞추면 다른 쪽 끝만 보면 돼요."],"asset":{"type":"len_bars","rows":[{"label":"㉮","len":8},{"label":"㉯","len":5}]},"variant_rule":{"cmp4":{"ask":"most"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_a#2','math',1,1,'u4','','g1_1_math_u4_review_a','unit_review','M1-1-u4-C2',1,'mc','auto','양팔저울에 두 물건을 올렸어요. 더 무거운 것은 어느 것인가요?',ARRAY['M1-1-u4-X05']::text[],true,'{"seq":2,"concept":"M1-1-u4-C2","difficulty":1,"kind":"mc","stem":"양팔저울에 두 물건을 올렸어요. 더 무거운 것은 어느 것인가요?","options":[{"t":"수박","correct":true},{"t":"딸기","mis":"M1-1-u4-X05"},{"t":"무게가 같아요","mis":"M1-1-u4-X05"}],"explanation":["수박 쪽 접시가 아래로 내려갔어요.","아래로 내려간 쪽이 더 무거워요.","더 무거운 것은 수박이에요."],"asset":{"type":"balance","scales":[{"l":{"icon":"🍉","name":"수박"},"r":{"icon":"🍓","name":"딸기"},"down":"l"}]},"variant_rule":{"cmp4":{"ask":"most"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_a#3','math',1,1,'u4','','g1_1_math_u4_review_a','unit_review','M1-1-u4-C3',1,'mc','auto','종이 두 장을 겹쳐 보았어요. 더 넓은 것은 어느 것인가요?',ARRAY['M1-1-u4-X07']::text[],true,'{"seq":3,"concept":"M1-1-u4-C3","difficulty":1,"kind":"mc","stem":"종이 두 장을 겹쳐 보았어요. 더 넓은 것은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M1-1-u4-X07"},{"t":"넓이가 같아요","mis":"M1-1-u4-X07"}],"explanation":["㉯를 ㉮ 위에 겹쳤어요.","㉯는 ㉮ 안에 다 들어가고 ㉮가 둘레에 남아요.","남는 쪽 ㉮가 더 넓어요."],"asset":{"type":"area_shapes","mode":"overlap","shapes":[{"label":"㉮","w":6,"h":4},{"label":"㉯","w":3,"h":2}]},"variant_rule":{"cmp4":{"ask":"most"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_a#4','math',1,1,'u4','','g1_1_math_u4_review_a','unit_review','M1-1-u4-C4',1,'mc','auto','빈 그릇 두 개예요. 더 많이 담을 수 있는 그릇은 어느 것인가요?',ARRAY['M1-1-u4-X15','M1-1-u4-X08']::text[],true,'{"seq":4,"concept":"M1-1-u4-C4","difficulty":1,"kind":"mc","stem":"빈 그릇 두 개예요. 더 많이 담을 수 있는 그릇은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M1-1-u4-X15"},{"t":"담을 수 있는 양이 같아요","mis":"M1-1-u4-X08"}],"explanation":["두 그릇의 크기 차이가 커요.","차이가 크면 눈으로 보아도 알 수 있어요.","㉮에 더 많이 담을 수 있어요."],"asset":{"type":"cups","items":[{"label":"㉮","w":4,"h":5,"fill":0},{"label":"㉯","w":2,"h":2,"fill":0}]},"variant_rule":{"cmp4":{"ask":"most","by":"cap"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_a#5','math',1,1,'u4','','g1_1_math_u4_review_a','unit_review','M1-1-u4-C5',1,'mc','auto','크기가 같은 컵 세 개에 물이 들어 있어요. 물이 가장 많이 담긴 컵은 어느 것인가요?',ARRAY['M1-1-u4-X15','M1-1-u4-X09']::text[],true,'{"seq":5,"concept":"M1-1-u4-C5","difficulty":1,"kind":"mc","stem":"크기가 같은 컵 세 개에 물이 들어 있어요. 물이 가장 많이 담긴 컵은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M1-1-u4-X15"},{"t":"㉰","mis":"M1-1-u4-X09"}],"explanation":["세 컵은 크기가 같아요.","같은 컵이면 물 높이가 가장 높은 컵에 물이 가장 많아요.","물이 가장 많이 담긴 컵은 ㉮예요."],"asset":{"type":"cups","items":[{"label":"㉮","w":3,"h":5,"fill":0.8},{"label":"㉯","w":3,"h":5,"fill":0.4},{"label":"㉰","w":3,"h":5,"fill":0.6}],"same":true},"variant_rule":{"cmp4":{"ask":"most","by":"fill"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_a#6','math',1,1,'u4','','g1_1_math_u4_review_a','unit_review','M1-1-u4-C6',1,'blank','auto','줄넘기 줄이 허리띠보다 더 길어요. 그러면 허리띠는 줄넘기 줄보다 더 (        ).',ARRAY['M1-1-u4-X13','M1-1-u4-X12']::text[],false,'{"seq":6,"concept":"M1-1-u4-C6","difficulty":1,"kind":"blank","stem":"줄넘기 줄이 허리띠보다 더 길어요. 그러면 허리띠는 줄넘기 줄보다 더 (        ).","options":[{"t":"짧아요","correct":true},{"t":"길어요","mis":"M1-1-u4-X13"},{"t":"작아요","mis":"M1-1-u4-X12"}],"explanation":["줄넘기 줄이 허리띠보다 더 길어요.","거꾸로 말하면 허리띠는 줄넘기 줄보다 더 짧아요.","견주는 방향이 바뀌면 반대말을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_a#7','math',1,1,'u4','','g1_1_math_u4_review_a','unit_review','M1-1-u4-C6',1,'blank','auto','물통은 우유갑보다 담을 수 있는 양이 더 (        ).',ARRAY['M1-1-u4-X12']::text[],false,'{"seq":7,"concept":"M1-1-u4-C6","difficulty":1,"kind":"blank","stem":"물통은 우유갑보다 담을 수 있는 양이 더 (        ).","options":[{"t":"많아요","correct":true},{"t":"넓어요","mis":"M1-1-u4-X12"},{"t":"길어요","mis":"M1-1-u4-X12"}],"explanation":["무엇을 견주는지 먼저 봐요.","담을 수 있는 양(들이)은 「많다·적다」로 말해요.","길이는 길다, 무게는 무겁다, 넓이는 넓다, 들이는 많다로 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_a#8','math',1,1,'u4','','g1_1_math_u4_review_a','unit_review','M1-1-u4-C1',1,'ox','auto','㉯는 ㉮보다 더 짧아요.',ARRAY['M1-1-u4-X15']::text[],true,'{"seq":8,"concept":"M1-1-u4-C1","difficulty":1,"kind":"ox","stem":"㉯는 ㉮보다 더 짧아요.","answer":"O","reason_options":[{"t":"끝을 맞추었을 때 ㉯의 오른쪽 끝이 덜 나갔으니까","correct":true},{"t":"아래에 놓인 것이 더 짧으니까","mis":"M1-1-u4-X15"}],"mis":"M1-1-u4-X15","explanation":["두 막대의 왼쪽 끝이 맞추어져 있어요.","㉯의 오른쪽 끝이 덜 나갔으니 ㉯가 더 짧아요.","끝을 맞추면 다른 쪽 끝만 보면 돼요."],"asset":{"type":"len_bars","rows":[{"label":"㉮","len":7},{"label":"㉯","len":4}]},"variant_rule":{"cmp4":{}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_a#9','math',1,1,'u4','','g1_1_math_u4_review_a','unit_review','M1-1-u4-C1',2,'mc','auto','끝이 맞추어져 있지 않아요. 칸을 세어 더 긴 것을 고르세요.',ARRAY['M1-1-u4-X01']::text[],true,'{"seq":9,"concept":"M1-1-u4-C1","difficulty":2,"kind":"mc","stem":"끝이 맞추어져 있지 않아요. 칸을 세어 더 긴 것을 고르세요.","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M1-1-u4-X01"},{"t":"길이가 같아요","mis":"M1-1-u4-X01"}],"explanation":["㉮는 6칸, ㉯는 4칸이에요.","오른쪽으로 더 나간 것이 더 긴 것은 아니에요.","더 긴 것은 ㉮예요."],"asset":{"type":"len_bars","rows":[{"label":"㉮","len":6},{"label":"㉯","len":4,"off":3}],"grid":true},"variant_rule":{"cmp4":{"ask":"most"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_a#10','math',1,1,'u4','','g1_1_math_u4_review_a','unit_review','M1-1-u4-C2',2,'mc','auto','큰 풍선과 작은 돌을 양팔저울에 올렸어요. 더 무거운 것은 어느 것인가요?',ARRAY['M1-1-u4-X04']::text[],true,'{"seq":10,"concept":"M1-1-u4-C2","difficulty":2,"kind":"mc","stem":"큰 풍선과 작은 돌을 양팔저울에 올렸어요. 더 무거운 것은 어느 것인가요?","options":[{"t":"작은 돌","correct":true},{"t":"큰 풍선","mis":"M1-1-u4-X04"},{"t":"무게가 같아요","mis":"M1-1-u4-X04"}],"explanation":["작은 돌 쪽 접시가 아래로 내려갔어요.","크기는 큰 풍선이 더 크지만 더 무거운 것은 작은 돌이에요.","크기만 보고 무게를 정할 수 없어요."],"asset":{"type":"balance","scales":[{"l":{"icon":"🎈","name":"큰 풍선"},"r":{"icon":"🪨","name":"작은 돌"},"down":"r"}]},"variant_rule":{"cmp4":{"ask":"most"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_a#11','math',1,1,'u4','','g1_1_math_u4_review_a','unit_review','M1-1-u4-C3',2,'mc','auto','칸을 세어 보고 더 넓은 것을 고르세요.',ARRAY['M1-1-u4-X06']::text[],true,'{"seq":11,"concept":"M1-1-u4-C3","difficulty":2,"kind":"mc","stem":"칸을 세어 보고 더 넓은 것을 고르세요.","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M1-1-u4-X06"},{"t":"넓이가 같아요","mis":"M1-1-u4-X06"}],"explanation":["㉮는 12칸, ㉯는 10칸이에요.","한 변이 더 길다고 더 넓은 것은 아니에요.","더 넓은 것은 ㉮예요."],"asset":{"type":"area_shapes","mode":"grid","shapes":[{"label":"㉮","w":3,"h":4},{"label":"㉯","w":5,"h":2}]},"variant_rule":{"cmp4":{"ask":"most"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_a#12','math',1,1,'u4','','g1_1_math_u4_review_a','unit_review','M1-1-u4-C4',2,'mc','auto','㉮에 가득 담은 물을 ㉯에 부었어요. 더 많이 담을 수 있는 그릇은 어느 것인가요?',ARRAY['M1-1-u4-X10','M1-1-u4-X11']::text[],true,'{"seq":12,"concept":"M1-1-u4-C4","difficulty":2,"kind":"mc","stem":"㉮에 가득 담은 물을 ㉯에 부었어요. 더 많이 담을 수 있는 그릇은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M1-1-u4-X10"},{"t":"담을 수 있는 양이 같아요","mis":"M1-1-u4-X11"}],"explanation":["㉮의 물을 다 붓고도 ㉯에 빈 곳이 남았어요.","㉯가 ㉮보다 더 많이 담을 수 있다는 뜻이에요.","더 많이 담을 수 있는 그릇은 ㉯예요."],"asset":{"type":"cups","items":[{"label":"㉮","w":2,"h":4,"fill":1},{"label":"㉯","w":3,"h":4,"fill":0}],"pour":{"from":0,"to":1}},"variant_rule":{"cmp4":{"ask":"most","by":"cap"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_a#13','math',1,1,'u4','','g1_1_math_u4_review_a','unit_review','M1-1-u4-C5',2,'mc','auto','큰 그릇 ㉮에는 물이 조금, 작은 그릇 ㉯에는 물이 가득 들어 있어요. 담을 수 있는 양이 더 많은 그릇은 어느 것인가요?',ARRAY['M1-1-u4-X09','M1-1-u4-X11']::text[],true,'{"seq":13,"concept":"M1-1-u4-C5","difficulty":2,"kind":"mc","stem":"큰 그릇 ㉮에는 물이 조금, 작은 그릇 ㉯에는 물이 가득 들어 있어요. 담을 수 있는 양이 더 많은 그릇은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M1-1-u4-X09"},{"t":"알 수 없어요","mis":"M1-1-u4-X11"}],"explanation":["담을 수 있는 양은 그릇의 크기예요.","지금 물이 얼마나 들어 있는지와는 달라요.","그릇이 더 큰 ㉮에 더 많이 담을 수 있어요."],"asset":{"type":"cups","items":[{"label":"㉮","w":5,"h":5,"fill":0.2},{"label":"㉯","w":2,"h":3,"fill":1}]},"variant_rule":{"cmp4":{"ask":"most","by":"cap"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_a#14','math',1,1,'u4','','g1_1_math_u4_review_a','unit_review','M1-1-u4-C7',2,'mc','auto','끝을 맞추어 놓았어요. 가장 짧은 것은 어느 것인가요?',ARRAY['M1-1-u4-X15','M1-1-u4-X14']::text[],true,'{"seq":14,"concept":"M1-1-u4-C7","difficulty":2,"kind":"mc","stem":"끝을 맞추어 놓았어요. 가장 짧은 것은 어느 것인가요?","options":[{"t":"㉰","correct":true},{"t":"㉯","mis":"M1-1-u4-X15"},{"t":"㉮","mis":"M1-1-u4-X14"}],"explanation":["㉮ 6칸, ㉯ 9칸, ㉰ 3칸이에요.","오른쪽 끝이 가장 덜 나간 것은 ㉰예요.","셋을 견줄 때는 「가장 짧다」라고 말해요."],"asset":{"type":"len_bars","rows":[{"label":"㉮","len":6},{"label":"㉯","len":9},{"label":"㉰","len":3}],"grid":true},"variant_rule":{"cmp4":{"ask":"least"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_a#15','math',1,1,'u4','','g1_1_math_u4_review_a','unit_review','M1-1-u4-C6',2,'match','auto','견주는 것과 알맞은 비교 말을 이어 보세요.','{}'::text[],false,'{"seq":15,"concept":"M1-1-u4-C6","difficulty":2,"kind":"match","stem":"견주는 것과 알맞은 비교 말을 이어 보세요.","pairs":[{"l":"길이","r":"더 길다"},{"l":"무게","r":"더 무겁다"},{"l":"넓이","r":"더 넓다"}],"mis":"M1-1-u4-X12","explanation":["길이는 「길다·짧다」로 말해요.","무게는 「무겁다·가볍다」, 넓이는 「넓다·좁다」, 들이는 「많다·적다」예요.","무엇을 견주는지 먼저 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_a#16','math',1,1,'u4','','g1_1_math_u4_review_a','unit_review','M1-1-u4-C2',2,'ox','auto','저울에서 위로 올라간 풍선이 더 무거워요.',ARRAY['M1-1-u4-X05']::text[],true,'{"seq":16,"concept":"M1-1-u4-C2","difficulty":2,"kind":"ox","stem":"저울에서 위로 올라간 풍선이 더 무거워요.","answer":"X","reason_options":[{"t":"아래로 내려간 쪽이 더 무거우니까","correct":true},{"t":"높이 올라간 쪽이 힘이 세서 더 무거우니까","mis":"M1-1-u4-X05"}],"mis":"M1-1-u4-X05","explanation":["축구공 쪽이 아래로 내려갔어요.","내려간 쪽이 더 무거워요 — 축구공이 더 무거워요.","풍선은 위로 올라갔으니 더 가벼워요."],"asset":{"type":"balance","scales":[{"l":{"icon":"⚽","name":"축구공"},"r":{"icon":"🎈","name":"풍선"},"down":"l"}]},"variant_rule":{"cmp4":{}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_a#17','math',1,1,'u4','','g1_1_math_u4_review_a','unit_review','M1-1-u4-C1',3,'mc','auto','구부러진 실의 마디 하나는 칸 하나와 길이가 같아요. 곧게 펴면 가장 긴 것은 어느 것인가요?',ARRAY['M1-1-u4-X02','M1-1-u4-X15']::text[],true,'{"seq":17,"concept":"M1-1-u4-C1","difficulty":3,"kind":"mc","stem":"구부러진 실의 마디 하나는 칸 하나와 길이가 같아요. 곧게 펴면 가장 긴 것은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉰","mis":"M1-1-u4-X02"},{"t":"㉯","mis":"M1-1-u4-X15"}],"explanation":["㉮는 마디 8개 — 펴면 8칸이에요.","㉯는 6칸, ㉰는 7칸이에요.","구부러진 ㉮가 펴면 가장 길어요."],"asset":{"type":"len_bars","rows":[{"label":"㉮","len":8,"bend":true},{"label":"㉯","len":6},{"label":"㉰","len":7}],"grid":true},"variant_rule":{"cmp4":{"ask":"most"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_a#18','math',1,1,'u4','','g1_1_math_u4_review_a','unit_review','M1-1-u4-C3',3,'sa','auto','더 넓은 것은 더 좁은 것보다 몇 칸 더 넓은가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M1-1-u4-C3","difficulty":3,"kind":"sa","stem":"더 넓은 것은 더 좁은 것보다 몇 칸 더 넓은가요? 숫자로 쓰세요.","answer":["1"],"explanation":["㉮는 9칸, ㉯는 8칸이에요.","9칸은 8칸보다 1칸 더 많아요.","칸 수의 차이가 넓이의 차이예요."],"asset":{"type":"area_shapes","mode":"grid","shapes":[{"label":"㉮","w":3,"h":3},{"label":"㉯","w":4,"h":2}]},"variant_rule":{"cmp4":{}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_a#19','math',1,1,'u4','','g1_1_math_u4_review_a','unit_review','M1-1-u4-C7',3,'mc','auto','저울 두 개로 상자 세 개를 견주었어요. 가장 무거운 상자는 어느 것인가요?',ARRAY['M1-1-u4-X14','M1-1-u4-X15']::text[],true,'{"seq":19,"concept":"M1-1-u4-C7","difficulty":3,"kind":"mc","stem":"저울 두 개로 상자 세 개를 견주었어요. 가장 무거운 상자는 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M1-1-u4-X14"},{"t":"㉰","mis":"M1-1-u4-X15"}],"explanation":["첫째 저울에서 ㉮가 ㉯보다 무거워요.","둘째 저울에서 ㉯가 ㉰보다 무거워요.","가장 무거운 것은 ㉮예요."],"asset":{"type":"balance","scales":[{"l":{"icon":"📦","name":"㉮"},"r":{"icon":"📦","name":"㉯"},"down":"l"},{"l":{"icon":"📦","name":"㉯"},"r":{"icon":"📦","name":"㉰"},"down":"l"}]},"variant_rule":{"cmp4":{"ask":"most","names":[["㉮","㉯","㉰"]]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_a#20','math',1,1,'u4','','g1_1_math_u4_review_a','unit_review','M1-1-u4-C4',3,'mc','auto','같은 컵으로 물을 퍼서 그릇을 가득 채웠어요. ㉮는 3컵, ㉯는 6컵, ㉰는 5컵이 들어갔어요. 가장 많이 담을 수 있는 그릇은 어느 것인가요?',ARRAY['M1-1-u4-X08','M1-1-u4-X15']::text[],true,'{"seq":20,"concept":"M1-1-u4-C4","difficulty":3,"kind":"mc","stem":"같은 컵으로 물을 퍼서 그릇을 가득 채웠어요. ㉮는 3컵, ㉯는 6컵, ㉰는 5컵이 들어갔어요. 가장 많이 담을 수 있는 그릇은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M1-1-u4-X08"},{"t":"㉰","mis":"M1-1-u4-X15"}],"explanation":["같은 컵으로 퍼 담았으니 컵 수로 견줄 수 있어요.","6컵이 가장 많아요.","가장 높은 그릇이 아니라 ㉯에 가장 많이 담을 수 있어요."],"asset":{"type":"cups","items":[{"label":"㉮","w":1,"h":6,"fill":0},{"label":"㉯","w":4,"h":3,"fill":0},{"label":"㉰","w":2,"h":5,"fill":0}]},"variant_rule":{"cmp4":{"ask":"most","by":"cap"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_a#21','math',1,1,'u4','','g1_1_math_u4_review_a','unit_review','M1-1-u4-C6',3,'error','auto','친구들이 비교하는 말을 했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M1-1-u4-X12','M1-1-u4-X13']::text[],false,'{"seq":21,"concept":"M1-1-u4-C6","difficulty":3,"kind":"error","stem":"친구들이 비교하는 말을 했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하루: 운동장은 교실보다 더 길어요(넓이를 말하려고).","correct":true,"mis_target":"M1-1-u4-X12"},{"t":"서아: 운동장은 교실보다 더 넓어요.","mis":"M1-1-u4-X12"},{"t":"지우: 교실은 운동장보다 더 좁아요.","mis":"M1-1-u4-X13"}],"explanation":["바닥의 크기는 넓이예요.","넓이는 「넓다·좁다」로 말해요.","하루가 알맞지 않은 말을 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_a#22','math',1,1,'u4','','g1_1_math_u4_review_a','unit_review','M1-1-u4-C2',3,'error','auto','친구들이 무게에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M1-1-u4-X04','M1-1-u4-X05']::text[],false,'{"seq":22,"concept":"M1-1-u4-C2","difficulty":3,"kind":"error","stem":"친구들이 무게에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도이: 크기가 크니까 틀림없이 더 무거워.","correct":true,"mis_target":"M1-1-u4-X04"},{"t":"하루: 저울에서 내려간 쪽이 더 무거워.","mis":"M1-1-u4-X05"},{"t":"서아: 양손에 들어 보면 무게를 견줄 수 있어.","mis":"M1-1-u4-X04"}],"explanation":["무게는 크기나 높이로 정해지지 않아요.","양손에 들거나 저울에서 내려간 쪽을 봐요.","그래서 그 친구의 말이 잘못되었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_a#23','math',1,1,'u4','','g1_1_math_u4_review_a','unit_review','M1-1-u4-C7',4,'mc','auto','㉮는 ㉯보다 길고, ㉰는 ㉮보다 길고, ㉱는 ㉰보다 길어요. 가장 짧은 것은 어느 것인가요?',ARRAY['M1-1-u4-X14','M1-1-u4-X15']::text[],false,'{"seq":23,"concept":"M1-1-u4-C7","difficulty":4,"kind":"mc","stem":"㉮는 ㉯보다 길고, ㉰는 ㉮보다 길고, ㉱는 ㉰보다 길어요. 가장 짧은 것은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M1-1-u4-X14"},{"t":"㉱","mis":"M1-1-u4-X15"}],"explanation":["㉱ > ㉰ > ㉮ > ㉯ 예요.","긴 차례로 늘어놓으면 맨 끝은 ㉯예요.","가장 짧은 것은 ㉯예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_a#24','math',1,1,'u4','','g1_1_math_u4_review_a','unit_review','M1-1-u4-C3',4,'mc','auto','㉮는 가로 4칸·세로 3칸, ㉯는 가로 2칸·세로 6칸인 모양이에요. 알맞은 말은 어느 것인가요?',ARRAY['M1-1-u4-X06']::text[],false,'{"seq":24,"concept":"M1-1-u4-C3","difficulty":4,"kind":"mc","stem":"㉮는 가로 4칸·세로 3칸, ㉯는 가로 2칸·세로 6칸인 모양이에요. 알맞은 말은 어느 것인가요?","options":[{"t":"넓이가 같아요","correct":true},{"t":"㉯가 더 넓어요","mis":"M1-1-u4-X06"},{"t":"㉮가 더 넓어요","mis":"M1-1-u4-X06"}],"explanation":["㉮는 4칸씩 3줄 — 12칸이에요.","㉯는 2칸씩 6줄 — 12칸이에요.","모양은 달라도 넓이는 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_a#25','math',1,1,'u4','','g1_1_math_u4_review_a','unit_review','M1-1-u4-C5',4,'essay','teacher','그림의 두 그릇 가운데 어느 그릇에 더 많이 담을 수 있는지, 또 지금 어느 그릇에 물이 더 많이 담겨 있는지 각각 쓰고 까닭을 말해 보세요. (㉮는 큰 그릇에 물이 조금, ㉯는 작은 그릇에 물이 가득)','{}'::text[],false,'{"seq":25,"concept":"M1-1-u4-C5","difficulty":4,"kind":"essay","stem":"그림의 두 그릇 가운데 어느 그릇에 더 많이 담을 수 있는지, 또 지금 어느 그릇에 물이 더 많이 담겨 있는지 각각 쓰고 까닭을 말해 보세요. (㉮는 큰 그릇에 물이 조금, ㉯는 작은 그릇에 물이 가득)","answer_guide":{"answer":"더 많이 담을 수 있는 그릇은 ㉮(그릇이 더 크다). 지금 담긴 물은 ㉮의 물을 ㉯ 같은 컵에 옮겨 보아야 정확히 알 수 있으며 ㉯가 더 많을 수도 있다.","scoring_points":["담을 수 있는 양(그릇 크기)과 담긴 양(들어 있는 물)을 나누어 말했는가","그림이나 예와 맞게 판단했는가","어떻게 확인할지(옮겨 부어 보기 등) 말했는가"]},"explanation":["담을 수 있는 양은 그릇에 가득 채운 양이에요.","담긴 양은 지금 들어 있는 물의 양이에요.","두 양을 섞지 말고 따로 따져요."],"asset":{"type":"cups","items":[{"label":"㉮","w":5,"h":5,"fill":0.2},{"label":"㉯","w":2,"h":3,"fill":1}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_b#1','math',1,1,'u4','','g1_1_math_u4_review_b','unit_review','M1-1-u4-C1',1,'mc','auto','끝을 맞추어 놓았어요. 더 긴 것은 어느 것인가요?',ARRAY['M1-1-u4-X15','M1-1-u4-X01']::text[],true,'{"seq":1,"concept":"M1-1-u4-C1","difficulty":1,"kind":"mc","stem":"끝을 맞추어 놓았어요. 더 긴 것은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M1-1-u4-X15"},{"t":"길이가 같아요","mis":"M1-1-u4-X01"}],"explanation":["왼쪽 끝이 맞추어져 있어요.","오른쪽 끝이 더 나간 ㉯가 더 길어요.","끝을 맞추면 다른 쪽 끝만 보면 돼요."],"asset":{"type":"len_bars","rows":[{"label":"㉮","len":4},{"label":"㉯","len":7}]},"variant_rule":{"cmp4":{"ask":"most"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_b#2','math',1,1,'u4','','g1_1_math_u4_review_b','unit_review','M1-1-u4-C2',1,'mc','auto','양팔저울에 두 물건을 올렸어요. 더 무거운 것은 어느 것인가요?',ARRAY['M1-1-u4-X05']::text[],true,'{"seq":2,"concept":"M1-1-u4-C2","difficulty":1,"kind":"mc","stem":"양팔저울에 두 물건을 올렸어요. 더 무거운 것은 어느 것인가요?","options":[{"t":"책가방","correct":true},{"t":"연필","mis":"M1-1-u4-X05"},{"t":"무게가 같아요","mis":"M1-1-u4-X05"}],"explanation":["책가방 쪽 접시가 아래로 내려갔어요.","아래로 내려간 쪽이 더 무거워요.","더 무거운 것은 책가방이에요."],"asset":{"type":"balance","scales":[{"l":{"icon":"✏️","name":"연필"},"r":{"icon":"🎒","name":"책가방"},"down":"r"}]},"variant_rule":{"cmp4":{"ask":"most"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_b#3','math',1,1,'u4','','g1_1_math_u4_review_b','unit_review','M1-1-u4-C3',1,'mc','auto','종이 두 장을 겹쳐 보았어요. 더 넓은 것은 어느 것인가요?',ARRAY['M1-1-u4-X07']::text[],true,'{"seq":3,"concept":"M1-1-u4-C3","difficulty":1,"kind":"mc","stem":"종이 두 장을 겹쳐 보았어요. 더 넓은 것은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M1-1-u4-X07"},{"t":"넓이가 같아요","mis":"M1-1-u4-X07"}],"explanation":["㉯를 ㉮ 위에 겹쳤어요.","㉯는 ㉮ 안에 다 들어가고 ㉮가 둘레에 남아요.","남는 쪽 ㉮가 더 넓어요."],"asset":{"type":"area_shapes","mode":"overlap","shapes":[{"label":"㉮","w":5,"h":5},{"label":"㉯","w":2,"h":3}]},"variant_rule":{"cmp4":{"ask":"most"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_b#4','math',1,1,'u4','','g1_1_math_u4_review_b','unit_review','M1-1-u4-C4',1,'mc','auto','빈 그릇 두 개예요. 더 많이 담을 수 있는 그릇은 어느 것인가요?',ARRAY['M1-1-u4-X15','M1-1-u4-X08']::text[],true,'{"seq":4,"concept":"M1-1-u4-C4","difficulty":1,"kind":"mc","stem":"빈 그릇 두 개예요. 더 많이 담을 수 있는 그릇은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M1-1-u4-X15"},{"t":"담을 수 있는 양이 같아요","mis":"M1-1-u4-X08"}],"explanation":["두 그릇의 크기 차이가 커요.","차이가 크면 눈으로 보아도 알 수 있어요.","㉯에 더 많이 담을 수 있어요."],"asset":{"type":"cups","items":[{"label":"㉮","w":2,"h":3,"fill":0},{"label":"㉯","w":5,"h":4,"fill":0}]},"variant_rule":{"cmp4":{"ask":"most","by":"cap"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_b#5','math',1,1,'u4','','g1_1_math_u4_review_b','unit_review','M1-1-u4-C5',1,'mc','auto','크기가 같은 컵 세 개에 물이 들어 있어요. 물이 가장 많이 담긴 컵은 어느 것인가요?',ARRAY['M1-1-u4-X15','M1-1-u4-X09']::text[],true,'{"seq":5,"concept":"M1-1-u4-C5","difficulty":1,"kind":"mc","stem":"크기가 같은 컵 세 개에 물이 들어 있어요. 물이 가장 많이 담긴 컵은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M1-1-u4-X15"},{"t":"㉰","mis":"M1-1-u4-X09"}],"explanation":["세 컵은 크기가 같아요.","같은 컵이면 물 높이가 가장 높은 컵에 물이 가장 많아요.","물이 가장 많이 담긴 컵은 ㉯예요."],"asset":{"type":"cups","items":[{"label":"㉮","w":3,"h":5,"fill":0.3},{"label":"㉯","w":3,"h":5,"fill":0.9},{"label":"㉰","w":3,"h":5,"fill":0.5}],"same":true},"variant_rule":{"cmp4":{"ask":"most","by":"fill"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_b#6','math',1,1,'u4','','g1_1_math_u4_review_b','unit_review','M1-1-u4-C6',1,'blank','auto','가방이 공책보다 더 무거워요. 그러면 공책은 가방보다 더 (        ).',ARRAY['M1-1-u4-X13','M1-1-u4-X12']::text[],false,'{"seq":6,"concept":"M1-1-u4-C6","difficulty":1,"kind":"blank","stem":"가방이 공책보다 더 무거워요. 그러면 공책은 가방보다 더 (        ).","options":[{"t":"가벼워요","correct":true},{"t":"무거워요","mis":"M1-1-u4-X13"},{"t":"짧아요","mis":"M1-1-u4-X12"}],"explanation":["가방이 공책보다 더 무거워요.","거꾸로 말하면 공책은 가방보다 더 가벼워요.","견주는 방향이 바뀌면 반대말을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_b#7','math',1,1,'u4','','g1_1_math_u4_review_b','unit_review','M1-1-u4-C6',1,'blank','auto','기차는 자동차보다 더 (        ).',ARRAY['M1-1-u4-X12']::text[],false,'{"seq":7,"concept":"M1-1-u4-C6","difficulty":1,"kind":"blank","stem":"기차는 자동차보다 더 (        ).","options":[{"t":"길어요","correct":true},{"t":"많아요","mis":"M1-1-u4-X12"},{"t":"넓어요","mis":"M1-1-u4-X12"}],"explanation":["무엇을 견주는지 먼저 봐요.","기차와 자동차의 길이를 견주어요.","길이는 길다, 무게는 무겁다, 넓이는 넓다, 들이는 많다로 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_b#8','math',1,1,'u4','','g1_1_math_u4_review_b','unit_review','M1-1-u4-C1',1,'ox','auto','㉯는 ㉮보다 더 짧아요.',ARRAY['M1-1-u4-X15']::text[],true,'{"seq":8,"concept":"M1-1-u4-C1","difficulty":1,"kind":"ox","stem":"㉯는 ㉮보다 더 짧아요.","answer":"X","reason_options":[{"t":"끝을 맞추었을 때 ㉯의 오른쪽 끝이 더 나갔으니까","correct":true},{"t":"아래에 놓인 것이 더 짧으니까","mis":"M1-1-u4-X15"}],"mis":"M1-1-u4-X15","explanation":["두 막대의 왼쪽 끝이 맞추어져 있어요.","㉯의 오른쪽 끝이 더 나갔으니 ㉯가 더 길어요.","끝을 맞추면 다른 쪽 끝만 보면 돼요."],"asset":{"type":"len_bars","rows":[{"label":"㉮","len":3},{"label":"㉯","len":6}]},"variant_rule":{"cmp4":{}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_b#9','math',1,1,'u4','','g1_1_math_u4_review_b','unit_review','M1-1-u4-C1',2,'mc','auto','끝이 맞추어져 있지 않아요. 칸을 세어 더 긴 것을 고르세요.',ARRAY['M1-1-u4-X01']::text[],true,'{"seq":9,"concept":"M1-1-u4-C1","difficulty":2,"kind":"mc","stem":"끝이 맞추어져 있지 않아요. 칸을 세어 더 긴 것을 고르세요.","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M1-1-u4-X01"},{"t":"길이가 같아요","mis":"M1-1-u4-X01"}],"explanation":["㉮는 4칸, ㉯는 7칸이에요.","오른쪽으로 더 나간 것이 더 긴 것은 아니에요.","더 긴 것은 ㉯예요."],"asset":{"type":"len_bars","rows":[{"label":"㉮","len":4,"off":4},{"label":"㉯","len":7}],"grid":true},"variant_rule":{"cmp4":{"ask":"most"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_b#10','math',1,1,'u4','','g1_1_math_u4_review_b','unit_review','M1-1-u4-C2',2,'mc','auto','빈 상자와 쇠 나사를 양팔저울에 올렸어요. 더 무거운 것은 어느 것인가요?',ARRAY['M1-1-u4-X04']::text[],true,'{"seq":10,"concept":"M1-1-u4-C2","difficulty":2,"kind":"mc","stem":"빈 상자와 쇠 나사를 양팔저울에 올렸어요. 더 무거운 것은 어느 것인가요?","options":[{"t":"쇠 나사","correct":true},{"t":"빈 상자","mis":"M1-1-u4-X04"},{"t":"무게가 같아요","mis":"M1-1-u4-X04"}],"explanation":["쇠 나사 쪽 접시가 아래로 내려갔어요.","크기는 빈 상자가 더 크지만 더 무거운 것은 쇠 나사예요.","크기만 보고 무게를 정할 수 없어요."],"asset":{"type":"balance","scales":[{"l":{"icon":"📦","name":"빈 상자"},"r":{"icon":"🔩","name":"쇠 나사"},"down":"r"}]},"variant_rule":{"cmp4":{"ask":"most"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_b#11','math',1,1,'u4','','g1_1_math_u4_review_b','unit_review','M1-1-u4-C3',2,'mc','auto','칸을 세어 보고 더 넓은 것을 고르세요.',ARRAY['M1-1-u4-X06']::text[],true,'{"seq":11,"concept":"M1-1-u4-C3","difficulty":2,"kind":"mc","stem":"칸을 세어 보고 더 넓은 것을 고르세요.","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M1-1-u4-X06"},{"t":"넓이가 같아요","mis":"M1-1-u4-X06"}],"explanation":["㉮는 6칸, ㉯는 8칸이에요.","한 변이 더 길다고 더 넓은 것은 아니에요.","더 넓은 것은 ㉯예요."],"asset":{"type":"area_shapes","mode":"grid","shapes":[{"label":"㉮","w":6,"h":1},{"label":"㉯","w":2,"h":4}]},"variant_rule":{"cmp4":{"ask":"most"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_b#12','math',1,1,'u4','','g1_1_math_u4_review_b','unit_review','M1-1-u4-C4',2,'mc','auto','㉮에 가득 담은 물을 ㉯에 부었어요. 더 많이 담을 수 있는 그릇은 어느 것인가요?',ARRAY['M1-1-u4-X10','M1-1-u4-X11']::text[],true,'{"seq":12,"concept":"M1-1-u4-C4","difficulty":2,"kind":"mc","stem":"㉮에 가득 담은 물을 ㉯에 부었어요. 더 많이 담을 수 있는 그릇은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M1-1-u4-X10"},{"t":"담을 수 있는 양이 같아요","mis":"M1-1-u4-X11"}],"explanation":["㉮의 물을 다 붓고도 ㉯에 빈 곳이 남았어요.","㉯가 ㉮보다 더 많이 담을 수 있다는 뜻이에요.","더 많이 담을 수 있는 그릇은 ㉯예요."],"asset":{"type":"cups","items":[{"label":"㉮","w":2,"h":6,"fill":1},{"label":"㉯","w":5,"h":3,"fill":0}],"pour":{"from":0,"to":1}},"variant_rule":{"cmp4":{"ask":"most","by":"cap"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_b#13','math',1,1,'u4','','g1_1_math_u4_review_b','unit_review','M1-1-u4-C5',2,'mc','auto','큰 그릇 ㉮에는 물이 조금, 작은 그릇 ㉯에는 물이 가득 들어 있어요. 담을 수 있는 양이 더 많은 그릇은 어느 것인가요?',ARRAY['M1-1-u4-X09','M1-1-u4-X11']::text[],true,'{"seq":13,"concept":"M1-1-u4-C5","difficulty":2,"kind":"mc","stem":"큰 그릇 ㉮에는 물이 조금, 작은 그릇 ㉯에는 물이 가득 들어 있어요. 담을 수 있는 양이 더 많은 그릇은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M1-1-u4-X09"},{"t":"알 수 없어요","mis":"M1-1-u4-X11"}],"explanation":["담을 수 있는 양은 그릇의 크기예요.","지금 물이 얼마나 들어 있는지와는 달라요.","그릇이 더 큰 ㉮에 더 많이 담을 수 있어요."],"asset":{"type":"cups","items":[{"label":"㉮","w":4,"h":6,"fill":0.2},{"label":"㉯","w":2,"h":2,"fill":1}]},"variant_rule":{"cmp4":{"ask":"most","by":"cap"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_b#14','math',1,1,'u4','','g1_1_math_u4_review_b','unit_review','M1-1-u4-C7',2,'mc','auto','끝을 맞추어 놓았어요. 가장 짧은 것은 어느 것인가요?',ARRAY['M1-1-u4-X15','M1-1-u4-X14']::text[],true,'{"seq":14,"concept":"M1-1-u4-C7","difficulty":2,"kind":"mc","stem":"끝을 맞추어 놓았어요. 가장 짧은 것은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M1-1-u4-X15"},{"t":"㉰","mis":"M1-1-u4-X14"}],"explanation":["㉮ 8칸, ㉯ 4칸, ㉰ 6칸이에요.","오른쪽 끝이 가장 덜 나간 것은 ㉯예요.","셋을 견줄 때는 「가장 짧다」라고 말해요."],"asset":{"type":"len_bars","rows":[{"label":"㉮","len":8},{"label":"㉯","len":4},{"label":"㉰","len":6}],"grid":true},"variant_rule":{"cmp4":{"ask":"least"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_b#15','math',1,1,'u4','','g1_1_math_u4_review_b','unit_review','M1-1-u4-C6',2,'match','auto','견주는 것과 알맞은 비교 말을 이어 보세요.','{}'::text[],false,'{"seq":15,"concept":"M1-1-u4-C6","difficulty":2,"kind":"match","stem":"견주는 것과 알맞은 비교 말을 이어 보세요.","pairs":[{"l":"들이","r":"더 많다"},{"l":"길이","r":"더 짧다"},{"l":"무게","r":"더 가볍다"}],"mis":"M1-1-u4-X12","explanation":["길이는 「길다·짧다」로 말해요.","무게는 「무겁다·가볍다」, 넓이는 「넓다·좁다」, 들이는 「많다·적다」예요.","무엇을 견주는지 먼저 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_b#16','math',1,1,'u4','','g1_1_math_u4_review_b','unit_review','M1-1-u4-C2',2,'ox','auto','저울에서 위로 올라간 깃털이 더 무거워요.',ARRAY['M1-1-u4-X05']::text[],true,'{"seq":16,"concept":"M1-1-u4-C2","difficulty":2,"kind":"ox","stem":"저울에서 위로 올라간 깃털이 더 무거워요.","answer":"X","reason_options":[{"t":"아래로 내려간 쪽이 더 무거우니까","correct":true},{"t":"높이 올라간 쪽이 힘이 세서 더 무거우니까","mis":"M1-1-u4-X05"}],"mis":"M1-1-u4-X05","explanation":["책 쪽이 아래로 내려갔어요.","내려간 쪽이 더 무거워요 — 책이 더 무거워요.","깃털은 위로 올라갔으니 더 가벼워요."],"asset":{"type":"balance","scales":[{"l":{"icon":"🪶","name":"깃털"},"r":{"icon":"📕","name":"책"},"down":"r"}]},"variant_rule":{"cmp4":{}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_b#17','math',1,1,'u4','','g1_1_math_u4_review_b','unit_review','M1-1-u4-C1',3,'mc','auto','구부러진 실의 마디 하나는 칸 하나와 길이가 같아요. 곧게 펴면 가장 긴 것은 어느 것인가요?',ARRAY['M1-1-u4-X02','M1-1-u4-X15']::text[],true,'{"seq":17,"concept":"M1-1-u4-C1","difficulty":3,"kind":"mc","stem":"구부러진 실의 마디 하나는 칸 하나와 길이가 같아요. 곧게 펴면 가장 긴 것은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉰","mis":"M1-1-u4-X02"},{"t":"㉯","mis":"M1-1-u4-X15"}],"explanation":["㉮는 마디 7개 — 펴면 7칸이에요.","㉯는 5칸, ㉰는 6칸이에요.","구부러진 ㉮가 펴면 가장 길어요."],"asset":{"type":"len_bars","rows":[{"label":"㉮","len":7,"bend":true},{"label":"㉯","len":5},{"label":"㉰","len":6}],"grid":true},"variant_rule":{"cmp4":{"ask":"most"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_b#18','math',1,1,'u4','','g1_1_math_u4_review_b','unit_review','M1-1-u4-C3',3,'sa','auto','더 넓은 것은 더 좁은 것보다 몇 칸 더 넓은가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M1-1-u4-C3","difficulty":3,"kind":"sa","stem":"더 넓은 것은 더 좁은 것보다 몇 칸 더 넓은가요? 숫자로 쓰세요.","answer":["3"],"explanation":["㉮는 12칸, ㉯는 9칸이에요.","12칸은 9칸보다 3칸 더 많아요.","칸 수의 차이가 넓이의 차이예요."],"asset":{"type":"area_shapes","mode":"grid","shapes":[{"label":"㉮","w":2,"h":6},{"label":"㉯","w":3,"h":3}]},"variant_rule":{"cmp4":{}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_b#19','math',1,1,'u4','','g1_1_math_u4_review_b','unit_review','M1-1-u4-C7',3,'mc','auto','저울 두 개로 상자 세 개를 견주었어요. 가장 무거운 상자는 어느 것인가요?',ARRAY['M1-1-u4-X14','M1-1-u4-X15']::text[],true,'{"seq":19,"concept":"M1-1-u4-C7","difficulty":3,"kind":"mc","stem":"저울 두 개로 상자 세 개를 견주었어요. 가장 무거운 상자는 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M1-1-u4-X14"},{"t":"㉰","mis":"M1-1-u4-X15"}],"explanation":["첫째 저울에서 ㉯가 ㉮보다 무거워요.","둘째 저울에서 ㉯가 ㉰보다 무거워요.","㉯가 둘 다보다 무거우니 가장 무거워요."],"asset":{"type":"balance","scales":[{"l":{"icon":"📦","name":"㉮"},"r":{"icon":"📦","name":"㉯"},"down":"r"},{"l":{"icon":"📦","name":"㉯"},"r":{"icon":"📦","name":"㉰"},"down":"l"}]},"variant_rule":{"cmp4":{"ask":"most","names":[["㉮","㉯","㉰"]]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_b#20','math',1,1,'u4','','g1_1_math_u4_review_b','unit_review','M1-1-u4-C4',3,'mc','auto','같은 컵으로 물을 퍼서 그릇을 가득 채웠어요. ㉮는 4컵, ㉯는 2컵, ㉰는 5컵이 들어갔어요. 가장 많이 담을 수 있는 그릇은 어느 것인가요?',ARRAY['M1-1-u4-X08','M1-1-u4-X15']::text[],true,'{"seq":20,"concept":"M1-1-u4-C4","difficulty":3,"kind":"mc","stem":"같은 컵으로 물을 퍼서 그릇을 가득 채웠어요. ㉮는 4컵, ㉯는 2컵, ㉰는 5컵이 들어갔어요. 가장 많이 담을 수 있는 그릇은 어느 것인가요?","options":[{"t":"㉰","correct":true},{"t":"㉮","mis":"M1-1-u4-X08"},{"t":"㉯","mis":"M1-1-u4-X15"}],"explanation":["같은 컵으로 퍼 담았으니 컵 수로 견줄 수 있어요.","5컵이 가장 많아요.","가장 높은 그릇이 아니라 ㉰에 가장 많이 담을 수 있어요."],"asset":{"type":"cups","items":[{"label":"㉮","w":2,"h":6,"fill":0},{"label":"㉯","w":1,"h":6,"fill":0},{"label":"㉰","w":5,"h":3,"fill":0}]},"variant_rule":{"cmp4":{"ask":"most","by":"cap"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_b#21','math',1,1,'u4','','g1_1_math_u4_review_b','unit_review','M1-1-u4-C6',3,'error','auto','친구들이 비교하는 말을 했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M1-1-u4-X13','M1-1-u4-X12']::text[],false,'{"seq":21,"concept":"M1-1-u4-C6","difficulty":3,"kind":"error","stem":"친구들이 비교하는 말을 했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도이: 연필이 볼펜보다 더 길면 볼펜도 연필보다 더 길어요.","correct":true,"mis_target":"M1-1-u4-X13"},{"t":"유나: 볼펜은 연필보다 더 짧아요.","mis":"M1-1-u4-X13"},{"t":"하루: 연필은 볼펜보다 더 길어요.","mis":"M1-1-u4-X12"}],"explanation":["연필이 더 길면","볼펜은 연필보다 더 짧아요.","도이가 반대말로 바꾸지 않았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_b#22','math',1,1,'u4','','g1_1_math_u4_review_b','unit_review','M1-1-u4-C2',3,'error','auto','친구들이 무게에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M1-1-u4-X05','M1-1-u4-X04']::text[],false,'{"seq":22,"concept":"M1-1-u4-C2","difficulty":3,"kind":"error","stem":"친구들이 무게에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"유나: 저울에서 위로 올라간 쪽이 더 무거워.","correct":true,"mis_target":"M1-1-u4-X05"},{"t":"지우: 크기가 커도 가벼울 수 있어.","mis":"M1-1-u4-X04"},{"t":"하루: 내려간 접시 쪽이 더 무거워.","mis":"M1-1-u4-X05"}],"explanation":["무게는 크기나 높이로 정해지지 않아요.","양손에 들거나 저울에서 내려간 쪽을 봐요.","그래서 그 친구의 말이 잘못되었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_b#23','math',1,1,'u4','','g1_1_math_u4_review_b','unit_review','M1-1-u4-C7',4,'mc','auto','㉯는 ㉰보다 무겁고, ㉮는 ㉯보다 무겁고, ㉰는 ㉱보다 무거워요. 가장 가벼운 것은 어느 것인가요?',ARRAY['M1-1-u4-X14','M1-1-u4-X15']::text[],false,'{"seq":23,"concept":"M1-1-u4-C7","difficulty":4,"kind":"mc","stem":"㉯는 ㉰보다 무겁고, ㉮는 ㉯보다 무겁고, ㉰는 ㉱보다 무거워요. 가장 가벼운 것은 어느 것인가요?","options":[{"t":"㉱","correct":true},{"t":"㉰","mis":"M1-1-u4-X14"},{"t":"㉮","mis":"M1-1-u4-X15"}],"explanation":["㉮ > ㉯ > ㉰ > ㉱ 예요.","무거운 차례로 늘어놓으면 맨 끝은 ㉱예요.","가장 가벼운 것은 ㉱예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_b#24','math',1,1,'u4','','g1_1_math_u4_review_b','unit_review','M1-1-u4-C3',4,'mc','auto','큰 타일 1장은 작은 타일 2장과 넓이가 같아요. ㉮는 큰 타일 4장, ㉯는 작은 타일 6장으로 빈틈없이 덮였어요. 더 넓은 것은 어느 것인가요?',ARRAY['M1-1-u4-X16']::text[],false,'{"seq":24,"concept":"M1-1-u4-C3","difficulty":4,"kind":"mc","stem":"큰 타일 1장은 작은 타일 2장과 넓이가 같아요. ㉮는 큰 타일 4장, ㉯는 작은 타일 6장으로 빈틈없이 덮였어요. 더 넓은 것은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M1-1-u4-X16"},{"t":"넓이가 같아요","mis":"M1-1-u4-X16"}],"explanation":["큰 타일 4장은 작은 타일 8장만큼이에요.","㉮는 작은 타일 8장, ㉯는 6장만큼이에요.","그래서 ㉮가 더 넓어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_b#25','math',1,1,'u4','','g1_1_math_u4_review_b','unit_review','M1-1-u4-C5',4,'essay','teacher','큰 냄비에 물이 조금, 작은 컵에 물이 가득 들어 있어요. 「담을 수 있는 양」과 「담긴 양」을 각각 견주어 쓰고, 어떻게 확인할 수 있는지 말해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M1-1-u4-C5","difficulty":4,"kind":"essay","stem":"큰 냄비에 물이 조금, 작은 컵에 물이 가득 들어 있어요. 「담을 수 있는 양」과 「담긴 양」을 각각 견주어 쓰고, 어떻게 확인할 수 있는지 말해 보세요.","answer_guide":{"answer":"담을 수 있는 양은 냄비가 더 많다. 담긴 양은 냄비의 물을 같은 컵에 부어 보거나 한쪽 물을 다른 그릇에 옮겨 보아야 알 수 있다.","scoring_points":["담을 수 있는 양(그릇 크기)과 담긴 양(들어 있는 물)을 나누어 말했는가","그림이나 예와 맞게 판단했는가","어떻게 확인할지(옮겨 부어 보기 등) 말했는가"]},"explanation":["담을 수 있는 양은 그릇에 가득 채운 양이에요.","담긴 양은 지금 들어 있는 물의 양이에요.","두 양을 섞지 말고 따로 따져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_c#1','math',1,1,'u4','','g1_1_math_u4_review_c','unit_review','M1-1-u4-C1',1,'mc','auto','끝을 맞추어 놓았어요. 더 긴 것은 어느 것인가요?',ARRAY['M1-1-u4-X15','M1-1-u4-X01']::text[],true,'{"seq":1,"concept":"M1-1-u4-C1","difficulty":1,"kind":"mc","stem":"끝을 맞추어 놓았어요. 더 긴 것은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M1-1-u4-X15"},{"t":"길이가 같아요","mis":"M1-1-u4-X01"}],"explanation":["왼쪽 끝이 맞추어져 있어요.","오른쪽 끝이 더 나간 ㉮가 더 길어요.","끝을 맞추면 다른 쪽 끝만 보면 돼요."],"asset":{"type":"len_bars","rows":[{"label":"㉮","len":9},{"label":"㉯","len":6}]},"variant_rule":{"cmp4":{"ask":"most"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_c#2','math',1,1,'u4','','g1_1_math_u4_review_c','unit_review','M1-1-u4-C2',1,'mc','auto','양팔저울에 두 물건을 올렸어요. 더 무거운 것은 어느 것인가요?',ARRAY['M1-1-u4-X05']::text[],true,'{"seq":2,"concept":"M1-1-u4-C2","difficulty":1,"kind":"mc","stem":"양팔저울에 두 물건을 올렸어요. 더 무거운 것은 어느 것인가요?","options":[{"t":"의자","correct":true},{"t":"공책","mis":"M1-1-u4-X05"},{"t":"무게가 같아요","mis":"M1-1-u4-X05"}],"explanation":["의자 쪽 접시가 아래로 내려갔어요.","아래로 내려간 쪽이 더 무거워요.","더 무거운 것은 의자예요."],"asset":{"type":"balance","scales":[{"l":{"icon":"🪑","name":"의자"},"r":{"icon":"📒","name":"공책"},"down":"l"}]},"variant_rule":{"cmp4":{"ask":"most"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_c#3','math',1,1,'u4','','g1_1_math_u4_review_c','unit_review','M1-1-u4-C3',1,'mc','auto','종이 두 장을 겹쳐 보았어요. 더 넓은 것은 어느 것인가요?',ARRAY['M1-1-u4-X07']::text[],true,'{"seq":3,"concept":"M1-1-u4-C3","difficulty":1,"kind":"mc","stem":"종이 두 장을 겹쳐 보았어요. 더 넓은 것은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M1-1-u4-X07"},{"t":"넓이가 같아요","mis":"M1-1-u4-X07"}],"explanation":["㉯를 ㉮ 위에 겹쳤어요.","㉯는 ㉮ 안에 다 들어가고 ㉮가 둘레에 남아요.","남는 쪽 ㉮가 더 넓어요."],"asset":{"type":"area_shapes","mode":"overlap","shapes":[{"label":"㉮","w":7,"h":4},{"label":"㉯","w":4,"h":3}]},"variant_rule":{"cmp4":{"ask":"most"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_c#4','math',1,1,'u4','','g1_1_math_u4_review_c','unit_review','M1-1-u4-C4',1,'mc','auto','빈 그릇 두 개예요. 더 많이 담을 수 있는 그릇은 어느 것인가요?',ARRAY['M1-1-u4-X15','M1-1-u4-X08']::text[],true,'{"seq":4,"concept":"M1-1-u4-C4","difficulty":1,"kind":"mc","stem":"빈 그릇 두 개예요. 더 많이 담을 수 있는 그릇은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M1-1-u4-X15"},{"t":"담을 수 있는 양이 같아요","mis":"M1-1-u4-X08"}],"explanation":["두 그릇의 크기 차이가 커요.","차이가 크면 눈으로 보아도 알 수 있어요.","㉮에 더 많이 담을 수 있어요."],"asset":{"type":"cups","items":[{"label":"㉮","w":5,"h":4,"fill":0},{"label":"㉯","w":1,"h":3,"fill":0}]},"variant_rule":{"cmp4":{"ask":"most","by":"cap"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_c#5','math',1,1,'u4','','g1_1_math_u4_review_c','unit_review','M1-1-u4-C5',1,'mc','auto','크기가 같은 컵 세 개에 물이 들어 있어요. 물이 가장 많이 담긴 컵은 어느 것인가요?',ARRAY['M1-1-u4-X15','M1-1-u4-X09']::text[],true,'{"seq":5,"concept":"M1-1-u4-C5","difficulty":1,"kind":"mc","stem":"크기가 같은 컵 세 개에 물이 들어 있어요. 물이 가장 많이 담긴 컵은 어느 것인가요?","options":[{"t":"㉰","correct":true},{"t":"㉮","mis":"M1-1-u4-X15"},{"t":"㉯","mis":"M1-1-u4-X09"}],"explanation":["세 컵은 크기가 같아요.","같은 컵이면 물 높이가 가장 높은 컵에 물이 가장 많아요.","물이 가장 많이 담긴 컵은 ㉰예요."],"asset":{"type":"cups","items":[{"label":"㉮","w":3,"h":5,"fill":0.5},{"label":"㉯","w":3,"h":5,"fill":0.2},{"label":"㉰","w":3,"h":5,"fill":0.9}],"same":true},"variant_rule":{"cmp4":{"ask":"most","by":"fill"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_c#6','math',1,1,'u4','','g1_1_math_u4_review_c','unit_review','M1-1-u4-C6',1,'blank','auto','운동장이 교실보다 더 넓어요. 그러면 교실은 운동장보다 더 (        ).',ARRAY['M1-1-u4-X13','M1-1-u4-X12']::text[],false,'{"seq":6,"concept":"M1-1-u4-C6","difficulty":1,"kind":"blank","stem":"운동장이 교실보다 더 넓어요. 그러면 교실은 운동장보다 더 (        ).","options":[{"t":"좁아요","correct":true},{"t":"넓어요","mis":"M1-1-u4-X13"},{"t":"가벼워요","mis":"M1-1-u4-X12"}],"explanation":["운동장이 교실보다 더 넓어요.","거꾸로 말하면 교실은 운동장보다 더 좁아요.","견주는 방향이 바뀌면 반대말을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_c#7','math',1,1,'u4','','g1_1_math_u4_review_c','unit_review','M1-1-u4-C6',1,'blank','auto','돗자리는 손수건보다 더 (        ).',ARRAY['M1-1-u4-X12']::text[],false,'{"seq":7,"concept":"M1-1-u4-C6","difficulty":1,"kind":"blank","stem":"돗자리는 손수건보다 더 (        ).","options":[{"t":"넓어요","correct":true},{"t":"많아요","mis":"M1-1-u4-X12"},{"t":"길어요","mis":"M1-1-u4-X12"}],"explanation":["무엇을 견주는지 먼저 봐요.","바닥에 펼친 크기(넓이)를 견주어요.","길이는 길다, 무게는 무겁다, 넓이는 넓다, 들이는 많다로 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_c#8','math',1,1,'u4','','g1_1_math_u4_review_c','unit_review','M1-1-u4-C1',1,'ox','auto','㉯는 ㉮보다 더 짧아요.',ARRAY['M1-1-u4-X15']::text[],true,'{"seq":8,"concept":"M1-1-u4-C1","difficulty":1,"kind":"ox","stem":"㉯는 ㉮보다 더 짧아요.","answer":"O","reason_options":[{"t":"끝을 맞추었을 때 ㉯의 오른쪽 끝이 덜 나갔으니까","correct":true},{"t":"아래에 놓인 것이 더 짧으니까","mis":"M1-1-u4-X15"}],"mis":"M1-1-u4-X15","explanation":["두 막대의 왼쪽 끝이 맞추어져 있어요.","㉯의 오른쪽 끝이 덜 나갔으니 ㉯가 더 짧아요.","끝을 맞추면 다른 쪽 끝만 보면 돼요."],"asset":{"type":"len_bars","rows":[{"label":"㉮","len":8},{"label":"㉯","len":5}]},"variant_rule":{"cmp4":{}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_c#9','math',1,1,'u4','','g1_1_math_u4_review_c','unit_review','M1-1-u4-C1',2,'mc','auto','끝이 맞추어져 있지 않아요. 칸을 세어 더 긴 것을 고르세요.',ARRAY['M1-1-u4-X01']::text[],true,'{"seq":9,"concept":"M1-1-u4-C1","difficulty":2,"kind":"mc","stem":"끝이 맞추어져 있지 않아요. 칸을 세어 더 긴 것을 고르세요.","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M1-1-u4-X01"},{"t":"길이가 같아요","mis":"M1-1-u4-X01"}],"explanation":["㉮는 8칸, ㉯는 5칸이에요.","오른쪽으로 더 나간 것이 더 긴 것은 아니에요.","더 긴 것은 ㉮예요."],"asset":{"type":"len_bars","rows":[{"label":"㉮","len":8},{"label":"㉯","len":5,"off":4}],"grid":true},"variant_rule":{"cmp4":{"ask":"most"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_c#10','math',1,1,'u4','','g1_1_math_u4_review_c','unit_review','M1-1-u4-C2',2,'mc','auto','큰 스펀지와 작은 쇠공을 양팔저울에 올렸어요. 더 무거운 것은 어느 것인가요?',ARRAY['M1-1-u4-X04']::text[],true,'{"seq":10,"concept":"M1-1-u4-C2","difficulty":2,"kind":"mc","stem":"큰 스펀지와 작은 쇠공을 양팔저울에 올렸어요. 더 무거운 것은 어느 것인가요?","options":[{"t":"작은 쇠공","correct":true},{"t":"큰 스펀지","mis":"M1-1-u4-X04"},{"t":"무게가 같아요","mis":"M1-1-u4-X04"}],"explanation":["작은 쇠공 쪽 접시가 아래로 내려갔어요.","크기는 큰 스펀지가 더 크지만 더 무거운 것은 작은 쇠공이에요.","크기만 보고 무게를 정할 수 없어요."],"asset":{"type":"balance","scales":[{"l":{"icon":"⚙️","name":"작은 쇠공"},"r":{"icon":"🧽","name":"큰 스펀지"},"down":"l"}]},"variant_rule":{"cmp4":{"ask":"most"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_c#11','math',1,1,'u4','','g1_1_math_u4_review_c','unit_review','M1-1-u4-C3',2,'mc','auto','칸을 세어 보고 더 넓은 것을 고르세요.',ARRAY['M1-1-u4-X06']::text[],true,'{"seq":11,"concept":"M1-1-u4-C3","difficulty":2,"kind":"mc","stem":"칸을 세어 보고 더 넓은 것을 고르세요.","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M1-1-u4-X06"},{"t":"넓이가 같아요","mis":"M1-1-u4-X06"}],"explanation":["㉮는 12칸, ㉯는 6칸이에요.","한 변이 더 길다고 더 넓은 것은 아니에요.","더 넓은 것은 ㉮예요."],"asset":{"type":"area_shapes","mode":"grid","shapes":[{"label":"㉮","w":4,"h":3},{"label":"㉯","w":6,"h":1}]},"variant_rule":{"cmp4":{"ask":"most"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_c#12','math',1,1,'u4','','g1_1_math_u4_review_c','unit_review','M1-1-u4-C4',2,'mc','auto','㉮에 가득 담은 물을 ㉯에 부었어요. 더 많이 담을 수 있는 그릇은 어느 것인가요?',ARRAY['M1-1-u4-X10','M1-1-u4-X11']::text[],true,'{"seq":12,"concept":"M1-1-u4-C4","difficulty":2,"kind":"mc","stem":"㉮에 가득 담은 물을 ㉯에 부었어요. 더 많이 담을 수 있는 그릇은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M1-1-u4-X10"},{"t":"담을 수 있는 양이 같아요","mis":"M1-1-u4-X11"}],"explanation":["㉮의 물을 다 붓고도 ㉯에 빈 곳이 남았어요.","㉯가 ㉮보다 더 많이 담을 수 있다는 뜻이에요.","더 많이 담을 수 있는 그릇은 ㉯예요."],"asset":{"type":"cups","items":[{"label":"㉮","w":3,"h":3,"fill":1},{"label":"㉯","w":4,"h":4,"fill":0}],"pour":{"from":0,"to":1}},"variant_rule":{"cmp4":{"ask":"most","by":"cap"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_c#13','math',1,1,'u4','','g1_1_math_u4_review_c','unit_review','M1-1-u4-C5',2,'mc','auto','큰 그릇 ㉮에는 물이 조금, 작은 그릇 ㉯에는 물이 가득 들어 있어요. 담을 수 있는 양이 더 많은 그릇은 어느 것인가요?',ARRAY['M1-1-u4-X09','M1-1-u4-X11']::text[],true,'{"seq":13,"concept":"M1-1-u4-C5","difficulty":2,"kind":"mc","stem":"큰 그릇 ㉮에는 물이 조금, 작은 그릇 ㉯에는 물이 가득 들어 있어요. 담을 수 있는 양이 더 많은 그릇은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M1-1-u4-X09"},{"t":"알 수 없어요","mis":"M1-1-u4-X11"}],"explanation":["담을 수 있는 양은 그릇의 크기예요.","지금 물이 얼마나 들어 있는지와는 달라요.","그릇이 더 큰 ㉮에 더 많이 담을 수 있어요."],"asset":{"type":"cups","items":[{"label":"㉮","w":5,"h":4,"fill":0.2},{"label":"㉯","w":1,"h":4,"fill":1}]},"variant_rule":{"cmp4":{"ask":"most","by":"cap"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_c#14','math',1,1,'u4','','g1_1_math_u4_review_c','unit_review','M1-1-u4-C7',2,'mc','auto','끝을 맞추어 놓았어요. 가장 짧은 것은 어느 것인가요?',ARRAY['M1-1-u4-X15','M1-1-u4-X14']::text[],true,'{"seq":14,"concept":"M1-1-u4-C7","difficulty":2,"kind":"mc","stem":"끝을 맞추어 놓았어요. 가장 짧은 것은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉰","mis":"M1-1-u4-X15"},{"t":"㉯","mis":"M1-1-u4-X14"}],"explanation":["㉮ 5칸, ㉯ 7칸, ㉰ 9칸이에요.","오른쪽 끝이 가장 덜 나간 것은 ㉮예요.","셋을 견줄 때는 「가장 짧다」라고 말해요."],"asset":{"type":"len_bars","rows":[{"label":"㉮","len":5},{"label":"㉯","len":7},{"label":"㉰","len":9}],"grid":true},"variant_rule":{"cmp4":{"ask":"least"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_c#15','math',1,1,'u4','','g1_1_math_u4_review_c','unit_review','M1-1-u4-C6',2,'match','auto','견주는 것과 알맞은 비교 말을 이어 보세요.','{}'::text[],false,'{"seq":15,"concept":"M1-1-u4-C6","difficulty":2,"kind":"match","stem":"견주는 것과 알맞은 비교 말을 이어 보세요.","pairs":[{"l":"넓이","r":"더 좁다"},{"l":"들이","r":"더 적다"},{"l":"길이","r":"더 길다"}],"mis":"M1-1-u4-X12","explanation":["길이는 「길다·짧다」로 말해요.","무게는 「무겁다·가볍다」, 넓이는 「넓다·좁다」, 들이는 「많다·적다」예요.","무엇을 견주는지 먼저 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_c#16','math',1,1,'u4','','g1_1_math_u4_review_c','unit_review','M1-1-u4-C2',2,'ox','auto','저울에서 위로 올라간 포도알이 더 무거워요.',ARRAY['M1-1-u4-X05']::text[],true,'{"seq":16,"concept":"M1-1-u4-C2","difficulty":2,"kind":"ox","stem":"저울에서 위로 올라간 포도알이 더 무거워요.","answer":"X","reason_options":[{"t":"아래로 내려간 쪽이 더 무거우니까","correct":true},{"t":"높이 올라간 쪽이 힘이 세서 더 무거우니까","mis":"M1-1-u4-X05"}],"mis":"M1-1-u4-X05","explanation":["사과 쪽이 아래로 내려갔어요.","내려간 쪽이 더 무거워요 — 사과가 더 무거워요.","포도알은 위로 올라갔으니 더 가벼워요."],"asset":{"type":"balance","scales":[{"l":{"icon":"🍎","name":"사과"},"r":{"icon":"🍇","name":"포도알"},"down":"l"}]},"variant_rule":{"cmp4":{}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_c#17','math',1,1,'u4','','g1_1_math_u4_review_c','unit_review','M1-1-u4-C1',3,'mc','auto','구부러진 실의 마디 하나는 칸 하나와 길이가 같아요. 곧게 펴면 가장 긴 것은 어느 것인가요?',ARRAY['M1-1-u4-X02','M1-1-u4-X15']::text[],true,'{"seq":17,"concept":"M1-1-u4-C1","difficulty":3,"kind":"mc","stem":"구부러진 실의 마디 하나는 칸 하나와 길이가 같아요. 곧게 펴면 가장 긴 것은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M1-1-u4-X02"},{"t":"㉰","mis":"M1-1-u4-X15"}],"explanation":["㉮는 마디 9개 — 펴면 9칸이에요.","㉯는 8칸, ㉰는 6칸이에요.","구부러진 ㉮가 펴면 가장 길어요."],"asset":{"type":"len_bars","rows":[{"label":"㉮","len":9,"bend":true},{"label":"㉯","len":8},{"label":"㉰","len":6}],"grid":true},"variant_rule":{"cmp4":{"ask":"most"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_c#18','math',1,1,'u4','','g1_1_math_u4_review_c','unit_review','M1-1-u4-C3',3,'sa','auto','더 넓은 것은 더 좁은 것보다 몇 칸 더 넓은가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M1-1-u4-C3","difficulty":3,"kind":"sa","stem":"더 넓은 것은 더 좁은 것보다 몇 칸 더 넓은가요? 숫자로 쓰세요.","answer":["6"],"explanation":["㉮는 10칸, ㉯는 16칸이에요.","16칸은 10칸보다 6칸 더 많아요.","칸 수의 차이가 넓이의 차이예요."],"asset":{"type":"area_shapes","mode":"grid","shapes":[{"label":"㉮","w":5,"h":2},{"label":"㉯","w":4,"h":4}]},"variant_rule":{"cmp4":{}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_c#19','math',1,1,'u4','','g1_1_math_u4_review_c','unit_review','M1-1-u4-C7',3,'mc','auto','저울 두 개로 상자 세 개를 견주었어요. 가장 무거운 상자는 어느 것인가요?',ARRAY['M1-1-u4-X14','M1-1-u4-X15']::text[],true,'{"seq":19,"concept":"M1-1-u4-C7","difficulty":3,"kind":"mc","stem":"저울 두 개로 상자 세 개를 견주었어요. 가장 무거운 상자는 어느 것인가요?","options":[{"t":"㉰","correct":true},{"t":"㉮","mis":"M1-1-u4-X14"},{"t":"㉯","mis":"M1-1-u4-X15"}],"explanation":["첫째 저울에서 ㉰가 ㉮보다 무거워요.","둘째 저울에서 ㉮가 ㉯보다 무거워요.","무거운 차례는 ㉰, ㉮, ㉯ — 가장 무거운 것은 ㉰예요."],"asset":{"type":"balance","scales":[{"l":{"icon":"📦","name":"㉮"},"r":{"icon":"📦","name":"㉰"},"down":"r"},{"l":{"icon":"📦","name":"㉯"},"r":{"icon":"📦","name":"㉮"},"down":"r"}]},"variant_rule":{"cmp4":{"ask":"most","names":[["㉮","㉯","㉰"]]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_c#20','math',1,1,'u4','','g1_1_math_u4_review_c','unit_review','M1-1-u4-C4',3,'mc','auto','같은 컵으로 물을 퍼서 그릇을 가득 채웠어요. ㉮는 6컵, ㉯는 3컵, ㉰는 4컵이 들어갔어요. 가장 많이 담을 수 있는 그릇은 어느 것인가요?',ARRAY['M1-1-u4-X08','M1-1-u4-X15']::text[],true,'{"seq":20,"concept":"M1-1-u4-C4","difficulty":3,"kind":"mc","stem":"같은 컵으로 물을 퍼서 그릇을 가득 채웠어요. ㉮는 6컵, ㉯는 3컵, ㉰는 4컵이 들어갔어요. 가장 많이 담을 수 있는 그릇은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M1-1-u4-X08"},{"t":"㉰","mis":"M1-1-u4-X15"}],"explanation":["같은 컵으로 퍼 담았으니 컵 수로 견줄 수 있어요.","6컵이 가장 많아요.","가장 높은 그릇이 아니라 ㉮에 가장 많이 담을 수 있어요."],"asset":{"type":"cups","items":[{"label":"㉮","w":3,"h":4,"fill":0},{"label":"㉯","w":1,"h":6,"fill":0},{"label":"㉰","w":2,"h":4,"fill":0}]},"variant_rule":{"cmp4":{"ask":"most","by":"cap"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_c#21','math',1,1,'u4','','g1_1_math_u4_review_c','unit_review','M1-1-u4-C6',3,'error','auto','친구들이 비교하는 말을 했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M1-1-u4-X12','M1-1-u4-X13']::text[],false,'{"seq":21,"concept":"M1-1-u4-C6","difficulty":3,"kind":"error","stem":"친구들이 비교하는 말을 했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지우: 물병은 컵보다 더 무거워요(담을 수 있는 양을 말하려고).","correct":true,"mis_target":"M1-1-u4-X12"},{"t":"서아: 물병에 컵보다 더 많이 담을 수 있어요.","mis":"M1-1-u4-X12"},{"t":"도이: 컵에는 물병보다 더 적게 담을 수 있어요.","mis":"M1-1-u4-X13"}],"explanation":["담을 수 있는 양은 들이예요.","들이는 「많다·적다」로 말해요.","지우가 알맞지 않은 말을 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_c#22','math',1,1,'u4','','g1_1_math_u4_review_c','unit_review','M1-1-u4-C2',3,'error','auto','친구들이 무게에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M1-1-u4-X04','M1-1-u4-X05']::text[],false,'{"seq":22,"concept":"M1-1-u4-C2","difficulty":3,"kind":"error","stem":"친구들이 무게에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하루: 큰 풍선이 작은 구슬보다 당연히 더 무거워.","correct":true,"mis_target":"M1-1-u4-X04"},{"t":"도이: 들어 보기 전에는 알 수 없어.","mis":"M1-1-u4-X04"},{"t":"유나: 저울에 올려 보자.","mis":"M1-1-u4-X05"}],"explanation":["무게는 크기나 높이로 정해지지 않아요.","양손에 들거나 저울에서 내려간 쪽을 봐요.","그래서 그 친구의 말이 잘못되었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_c#23','math',1,1,'u4','','g1_1_math_u4_review_c','unit_review','M1-1-u4-C7',4,'mc','auto','㉰는 ㉮보다 넓고, ㉯는 ㉰보다 넓고, ㉮는 ㉱보다 넓어요. 가장 좁은 것은 어느 것인가요?',ARRAY['M1-1-u4-X14','M1-1-u4-X15']::text[],false,'{"seq":23,"concept":"M1-1-u4-C7","difficulty":4,"kind":"mc","stem":"㉰는 ㉮보다 넓고, ㉯는 ㉰보다 넓고, ㉮는 ㉱보다 넓어요. 가장 좁은 것은 어느 것인가요?","options":[{"t":"㉱","correct":true},{"t":"㉮","mis":"M1-1-u4-X14"},{"t":"㉯","mis":"M1-1-u4-X15"}],"explanation":["㉯ > ㉰ > ㉮ > ㉱ 예요.","넓은 차례로 늘어놓으면 맨 끝은 ㉱예요.","가장 좁은 것은 ㉱예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_c#24','math',1,1,'u4','','g1_1_math_u4_review_c','unit_review','M1-1-u4-C3',4,'mc','auto','㉮는 가로 6칸·세로 1칸, ㉯는 가로 3칸·세로 3칸인 모양이에요. 알맞은 말은 어느 것인가요?',ARRAY['M1-1-u4-X06']::text[],false,'{"seq":24,"concept":"M1-1-u4-C3","difficulty":4,"kind":"mc","stem":"㉮는 가로 6칸·세로 1칸, ㉯는 가로 3칸·세로 3칸인 모양이에요. 알맞은 말은 어느 것인가요?","options":[{"t":"㉯가 더 넓어요","correct":true},{"t":"㉮가 더 넓어요","mis":"M1-1-u4-X06"},{"t":"넓이가 같아요","mis":"M1-1-u4-X06"}],"explanation":["㉮는 6칸, ㉯는 9칸이에요.","㉮가 가로로 길지만 칸 수는 ㉯가 많아요.","그래서 ㉯가 더 넓어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_c#25','math',1,1,'u4','','g1_1_math_u4_review_c','unit_review','M1-1-u4-C5',4,'essay','teacher','「큰 그릇에는 언제나 물이 더 많이 들어 있다」는 말이 맞는지 쓰고, 그 까닭을 예를 들어 말해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M1-1-u4-C5","difficulty":4,"kind":"essay","stem":"「큰 그릇에는 언제나 물이 더 많이 들어 있다」는 말이 맞는지 쓰고, 그 까닭을 예를 들어 말해 보세요.","answer_guide":{"answer":"맞지 않다. 큰 그릇은 담을 수 있는 양이 많을 뿐, 물을 조금만 넣으면 담긴 양은 작은 그릇보다 적을 수 있다. 예: 빈 양동이와 가득 찬 컵.","scoring_points":["담을 수 있는 양(그릇 크기)과 담긴 양(들어 있는 물)을 나누어 말했는가","그림이나 예와 맞게 판단했는가","어떻게 확인할지(옮겨 부어 보기 등) 말했는가"]},"explanation":["담을 수 있는 양은 그릇에 가득 채운 양이에요.","담긴 양은 지금 들어 있는 물의 양이에요.","두 양을 섞지 말고 따로 따져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_d#1','math',1,1,'u4','','g1_1_math_u4_review_d','unit_review','M1-1-u4-C1',1,'mc','auto','끝을 맞추어 놓았어요. 더 긴 것은 어느 것인가요?',ARRAY['M1-1-u4-X15','M1-1-u4-X01']::text[],true,'{"seq":1,"concept":"M1-1-u4-C1","difficulty":1,"kind":"mc","stem":"끝을 맞추어 놓았어요. 더 긴 것은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M1-1-u4-X15"},{"t":"길이가 같아요","mis":"M1-1-u4-X01"}],"explanation":["왼쪽 끝이 맞추어져 있어요.","오른쪽 끝이 더 나간 ㉯가 더 길어요.","끝을 맞추면 다른 쪽 끝만 보면 돼요."],"asset":{"type":"len_bars","rows":[{"label":"㉮","len":3},{"label":"㉯","len":6}]},"variant_rule":{"cmp4":{"ask":"most"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_d#2','math',1,1,'u4','','g1_1_math_u4_review_d','unit_review','M1-1-u4-C2',1,'mc','auto','양팔저울에 두 물건을 올렸어요. 더 무거운 것은 어느 것인가요?',ARRAY['M1-1-u4-X05']::text[],true,'{"seq":2,"concept":"M1-1-u4-C2","difficulty":1,"kind":"mc","stem":"양팔저울에 두 물건을 올렸어요. 더 무거운 것은 어느 것인가요?","options":[{"t":"파인애플","correct":true},{"t":"체리","mis":"M1-1-u4-X05"},{"t":"무게가 같아요","mis":"M1-1-u4-X05"}],"explanation":["파인애플 쪽 접시가 아래로 내려갔어요.","아래로 내려간 쪽이 더 무거워요.","더 무거운 것은 파인애플이에요."],"asset":{"type":"balance","scales":[{"l":{"icon":"🍒","name":"체리"},"r":{"icon":"🍍","name":"파인애플"},"down":"r"}]},"variant_rule":{"cmp4":{"ask":"most"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_d#3','math',1,1,'u4','','g1_1_math_u4_review_d','unit_review','M1-1-u4-C3',1,'mc','auto','종이 두 장을 겹쳐 보았어요. 더 넓은 것은 어느 것인가요?',ARRAY['M1-1-u4-X07']::text[],true,'{"seq":3,"concept":"M1-1-u4-C3","difficulty":1,"kind":"mc","stem":"종이 두 장을 겹쳐 보았어요. 더 넓은 것은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M1-1-u4-X07"},{"t":"넓이가 같아요","mis":"M1-1-u4-X07"}],"explanation":["㉯를 ㉮ 위에 겹쳤어요.","㉯는 ㉮ 안에 다 들어가고 ㉮가 둘레에 남아요.","남는 쪽 ㉮가 더 넓어요."],"asset":{"type":"area_shapes","mode":"overlap","shapes":[{"label":"㉮","w":6,"h":3},{"label":"㉯","w":3,"h":3}]},"variant_rule":{"cmp4":{"ask":"most"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_d#4','math',1,1,'u4','','g1_1_math_u4_review_d','unit_review','M1-1-u4-C4',1,'mc','auto','빈 그릇 두 개예요. 더 많이 담을 수 있는 그릇은 어느 것인가요?',ARRAY['M1-1-u4-X15','M1-1-u4-X08']::text[],true,'{"seq":4,"concept":"M1-1-u4-C4","difficulty":1,"kind":"mc","stem":"빈 그릇 두 개예요. 더 많이 담을 수 있는 그릇은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M1-1-u4-X15"},{"t":"담을 수 있는 양이 같아요","mis":"M1-1-u4-X08"}],"explanation":["두 그릇의 크기 차이가 커요.","차이가 크면 눈으로 보아도 알 수 있어요.","㉯에 더 많이 담을 수 있어요."],"asset":{"type":"cups","items":[{"label":"㉮","w":2,"h":2,"fill":0},{"label":"㉯","w":4,"h":6,"fill":0}]},"variant_rule":{"cmp4":{"ask":"most","by":"cap"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_d#5','math',1,1,'u4','','g1_1_math_u4_review_d','unit_review','M1-1-u4-C5',1,'mc','auto','크기가 같은 컵 세 개에 물이 들어 있어요. 물이 가장 많이 담긴 컵은 어느 것인가요?',ARRAY['M1-1-u4-X15','M1-1-u4-X09']::text[],true,'{"seq":5,"concept":"M1-1-u4-C5","difficulty":1,"kind":"mc","stem":"크기가 같은 컵 세 개에 물이 들어 있어요. 물이 가장 많이 담긴 컵은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M1-1-u4-X15"},{"t":"㉰","mis":"M1-1-u4-X09"}],"explanation":["세 컵은 크기가 같아요.","같은 컵이면 물 높이가 가장 높은 컵에 물이 가장 많아요.","물이 가장 많이 담긴 컵은 ㉮예요."],"asset":{"type":"cups","items":[{"label":"㉮","w":3,"h":5,"fill":0.7},{"label":"㉯","w":3,"h":5,"fill":0.4},{"label":"㉰","w":3,"h":5,"fill":0.2}],"same":true},"variant_rule":{"cmp4":{"ask":"most","by":"fill"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_d#6','math',1,1,'u4','','g1_1_math_u4_review_d','unit_review','M1-1-u4-C6',1,'blank','auto','양동이가 컵보다 더 무거워요. 그러면 컵은 양동이보다 더 (        ).',ARRAY['M1-1-u4-X13','M1-1-u4-X12']::text[],false,'{"seq":6,"concept":"M1-1-u4-C6","difficulty":1,"kind":"blank","stem":"양동이가 컵보다 더 무거워요. 그러면 컵은 양동이보다 더 (        ).","options":[{"t":"가벼워요","correct":true},{"t":"무거워요","mis":"M1-1-u4-X13"},{"t":"좁아요","mis":"M1-1-u4-X12"}],"explanation":["양동이가 컵보다 더 무거워요.","거꾸로 말하면 컵은 양동이보다 더 가벼워요.","견주는 방향이 바뀌면 반대말을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_d#7','math',1,1,'u4','','g1_1_math_u4_review_d','unit_review','M1-1-u4-C6',1,'blank','auto','책가방은 깃털보다 더 (        ).',ARRAY['M1-1-u4-X12']::text[],false,'{"seq":7,"concept":"M1-1-u4-C6","difficulty":1,"kind":"blank","stem":"책가방은 깃털보다 더 (        ).","options":[{"t":"무거워요","correct":true},{"t":"넓어요","mis":"M1-1-u4-X12"},{"t":"많아요","mis":"M1-1-u4-X12"}],"explanation":["무엇을 견주는지 먼저 봐요.","들었을 때의 무게를 견주어요.","길이는 길다, 무게는 무겁다, 넓이는 넓다, 들이는 많다로 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_d#8','math',1,1,'u4','','g1_1_math_u4_review_d','unit_review','M1-1-u4-C1',1,'ox','auto','㉯는 ㉮보다 더 짧아요.',ARRAY['M1-1-u4-X15']::text[],true,'{"seq":8,"concept":"M1-1-u4-C1","difficulty":1,"kind":"ox","stem":"㉯는 ㉮보다 더 짧아요.","answer":"X","reason_options":[{"t":"끝을 맞추었을 때 ㉯의 오른쪽 끝이 더 나갔으니까","correct":true},{"t":"아래에 놓인 것이 더 짧으니까","mis":"M1-1-u4-X15"}],"mis":"M1-1-u4-X15","explanation":["두 막대의 왼쪽 끝이 맞추어져 있어요.","㉯의 오른쪽 끝이 더 나갔으니 ㉯가 더 길어요.","끝을 맞추면 다른 쪽 끝만 보면 돼요."],"asset":{"type":"len_bars","rows":[{"label":"㉮","len":4},{"label":"㉯","len":9}]},"variant_rule":{"cmp4":{}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_d#9','math',1,1,'u4','','g1_1_math_u4_review_d','unit_review','M1-1-u4-C1',2,'mc','auto','끝이 맞추어져 있지 않아요. 칸을 세어 더 긴 것을 고르세요.',ARRAY['M1-1-u4-X01']::text[],true,'{"seq":9,"concept":"M1-1-u4-C1","difficulty":2,"kind":"mc","stem":"끝이 맞추어져 있지 않아요. 칸을 세어 더 긴 것을 고르세요.","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M1-1-u4-X01"},{"t":"길이가 같아요","mis":"M1-1-u4-X01"}],"explanation":["㉮는 5칸, ㉯는 6칸이에요.","오른쪽으로 더 나간 것이 더 긴 것은 아니에요.","더 긴 것은 ㉯예요."],"asset":{"type":"len_bars","rows":[{"label":"㉮","len":5,"off":3},{"label":"㉯","len":6}],"grid":true},"variant_rule":{"cmp4":{"ask":"most"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_d#10','math',1,1,'u4','','g1_1_math_u4_review_d','unit_review','M1-1-u4-C2',2,'mc','auto','큰 인형과 작은 통조림을 양팔저울에 올렸어요. 더 무거운 것은 어느 것인가요?',ARRAY['M1-1-u4-X04']::text[],true,'{"seq":10,"concept":"M1-1-u4-C2","difficulty":2,"kind":"mc","stem":"큰 인형과 작은 통조림을 양팔저울에 올렸어요. 더 무거운 것은 어느 것인가요?","options":[{"t":"작은 통조림","correct":true},{"t":"큰 인형","mis":"M1-1-u4-X04"},{"t":"무게가 같아요","mis":"M1-1-u4-X04"}],"explanation":["작은 통조림 쪽 접시가 아래로 내려갔어요.","크기는 큰 인형이 더 크지만 더 무거운 것은 작은 통조림이에요.","크기만 보고 무게를 정할 수 없어요."],"asset":{"type":"balance","scales":[{"l":{"icon":"🥫","name":"작은 통조림"},"r":{"icon":"🧸","name":"큰 인형"},"down":"l"}]},"variant_rule":{"cmp4":{"ask":"most"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_d#11','math',1,1,'u4','','g1_1_math_u4_review_d','unit_review','M1-1-u4-C3',2,'mc','auto','칸을 세어 보고 더 넓은 것을 고르세요.',ARRAY['M1-1-u4-X06']::text[],true,'{"seq":11,"concept":"M1-1-u4-C3","difficulty":2,"kind":"mc","stem":"칸을 세어 보고 더 넓은 것을 고르세요.","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M1-1-u4-X06"},{"t":"넓이가 같아요","mis":"M1-1-u4-X06"}],"explanation":["㉮는 10칸, ㉯는 12칸이에요.","한 변이 더 길다고 더 넓은 것은 아니에요.","더 넓은 것은 ㉯예요."],"asset":{"type":"area_shapes","mode":"grid","shapes":[{"label":"㉮","w":2,"h":5},{"label":"㉯","w":3,"h":4}]},"variant_rule":{"cmp4":{"ask":"most"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_d#12','math',1,1,'u4','','g1_1_math_u4_review_d','unit_review','M1-1-u4-C4',2,'mc','auto','㉮에 가득 담은 물을 ㉯에 부었어요. 더 많이 담을 수 있는 그릇은 어느 것인가요?',ARRAY['M1-1-u4-X10','M1-1-u4-X11']::text[],true,'{"seq":12,"concept":"M1-1-u4-C4","difficulty":2,"kind":"mc","stem":"㉮에 가득 담은 물을 ㉯에 부었어요. 더 많이 담을 수 있는 그릇은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M1-1-u4-X10"},{"t":"담을 수 있는 양이 같아요","mis":"M1-1-u4-X11"}],"explanation":["㉮의 물을 다 붓고도 ㉯에 빈 곳이 남았어요.","㉯가 ㉮보다 더 많이 담을 수 있다는 뜻이에요.","더 많이 담을 수 있는 그릇은 ㉯예요."],"asset":{"type":"cups","items":[{"label":"㉮","w":1,"h":6,"fill":1},{"label":"㉯","w":3,"h":3,"fill":0}],"pour":{"from":0,"to":1}},"variant_rule":{"cmp4":{"ask":"most","by":"cap"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_d#13','math',1,1,'u4','','g1_1_math_u4_review_d','unit_review','M1-1-u4-C5',2,'mc','auto','큰 그릇 ㉮에는 물이 조금, 작은 그릇 ㉯에는 물이 가득 들어 있어요. 담을 수 있는 양이 더 많은 그릇은 어느 것인가요?',ARRAY['M1-1-u4-X09','M1-1-u4-X11']::text[],true,'{"seq":13,"concept":"M1-1-u4-C5","difficulty":2,"kind":"mc","stem":"큰 그릇 ㉮에는 물이 조금, 작은 그릇 ㉯에는 물이 가득 들어 있어요. 담을 수 있는 양이 더 많은 그릇은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M1-1-u4-X09"},{"t":"알 수 없어요","mis":"M1-1-u4-X11"}],"explanation":["담을 수 있는 양은 그릇의 크기예요.","지금 물이 얼마나 들어 있는지와는 달라요.","그릇이 더 큰 ㉮에 더 많이 담을 수 있어요."],"asset":{"type":"cups","items":[{"label":"㉮","w":4,"h":5,"fill":0.2},{"label":"㉯","w":2,"h":4,"fill":1}]},"variant_rule":{"cmp4":{"ask":"most","by":"cap"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_d#14','math',1,1,'u4','','g1_1_math_u4_review_d','unit_review','M1-1-u4-C7',2,'mc','auto','끝을 맞추어 놓았어요. 가장 짧은 것은 어느 것인가요?',ARRAY['M1-1-u4-X15','M1-1-u4-X14']::text[],true,'{"seq":14,"concept":"M1-1-u4-C7","difficulty":2,"kind":"mc","stem":"끝을 맞추어 놓았어요. 가장 짧은 것은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M1-1-u4-X15"},{"t":"㉰","mis":"M1-1-u4-X14"}],"explanation":["㉮ 9칸, ㉯ 3칸, ㉰ 5칸이에요.","오른쪽 끝이 가장 덜 나간 것은 ㉯예요.","셋을 견줄 때는 「가장 짧다」라고 말해요."],"asset":{"type":"len_bars","rows":[{"label":"㉮","len":9},{"label":"㉯","len":3},{"label":"㉰","len":5}],"grid":true},"variant_rule":{"cmp4":{"ask":"least"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_d#15','math',1,1,'u4','','g1_1_math_u4_review_d','unit_review','M1-1-u4-C6',2,'match','auto','견주는 것과 알맞은 비교 말을 이어 보세요.','{}'::text[],false,'{"seq":15,"concept":"M1-1-u4-C6","difficulty":2,"kind":"match","stem":"견주는 것과 알맞은 비교 말을 이어 보세요.","pairs":[{"l":"무게","r":"더 무겁다"},{"l":"넓이","r":"더 넓다"},{"l":"들이","r":"더 많다"}],"mis":"M1-1-u4-X12","explanation":["길이는 「길다·짧다」로 말해요.","무게는 「무겁다·가볍다」, 넓이는 「넓다·좁다」, 들이는 「많다·적다」예요.","무엇을 견주는지 먼저 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_d#16','math',1,1,'u4','','g1_1_math_u4_review_d','unit_review','M1-1-u4-C2',2,'ox','auto','저울에서 위로 올라간 양말이 더 무거워요.',ARRAY['M1-1-u4-X05']::text[],true,'{"seq":16,"concept":"M1-1-u4-C2","difficulty":2,"kind":"ox","stem":"저울에서 위로 올라간 양말이 더 무거워요.","answer":"X","reason_options":[{"t":"아래로 내려간 쪽이 더 무거우니까","correct":true},{"t":"높이 올라간 쪽이 힘이 세서 더 무거우니까","mis":"M1-1-u4-X05"}],"mis":"M1-1-u4-X05","explanation":["가방 쪽이 아래로 내려갔어요.","내려간 쪽이 더 무거워요 — 가방이 더 무거워요.","양말은 위로 올라갔으니 더 가벼워요."],"asset":{"type":"balance","scales":[{"l":{"icon":"🧦","name":"양말"},"r":{"icon":"🎒","name":"가방"},"down":"r"}]},"variant_rule":{"cmp4":{}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_d#17','math',1,1,'u4','','g1_1_math_u4_review_d','unit_review','M1-1-u4-C1',3,'mc','auto','구부러진 실의 마디 하나는 칸 하나와 길이가 같아요. 곧게 펴면 가장 긴 것은 어느 것인가요?',ARRAY['M1-1-u4-X02','M1-1-u4-X15']::text[],true,'{"seq":17,"concept":"M1-1-u4-C1","difficulty":3,"kind":"mc","stem":"구부러진 실의 마디 하나는 칸 하나와 길이가 같아요. 곧게 펴면 가장 긴 것은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉰","mis":"M1-1-u4-X02"},{"t":"㉯","mis":"M1-1-u4-X15"}],"explanation":["㉮는 마디 6개 — 펴면 6칸이에요.","㉯는 4칸, ㉰는 5칸이에요.","구부러진 ㉮가 펴면 가장 길어요."],"asset":{"type":"len_bars","rows":[{"label":"㉮","len":6,"bend":true},{"label":"㉯","len":4},{"label":"㉰","len":5}],"grid":true},"variant_rule":{"cmp4":{"ask":"most"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_d#18','math',1,1,'u4','','g1_1_math_u4_review_d','unit_review','M1-1-u4-C3',3,'sa','auto','더 넓은 것은 더 좁은 것보다 몇 칸 더 넓은가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M1-1-u4-C3","difficulty":3,"kind":"sa","stem":"더 넓은 것은 더 좁은 것보다 몇 칸 더 넓은가요? 숫자로 쓰세요.","answer":["5"],"explanation":["㉮는 12칸, ㉯는 7칸이에요.","12칸은 7칸보다 5칸 더 많아요.","칸 수의 차이가 넓이의 차이예요."],"asset":{"type":"area_shapes","mode":"grid","shapes":[{"label":"㉮","w":3,"h":4},{"label":"㉯","w":7,"h":1}]},"variant_rule":{"cmp4":{}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_d#19','math',1,1,'u4','','g1_1_math_u4_review_d','unit_review','M1-1-u4-C7',3,'mc','auto','저울 두 개로 상자 세 개를 견주었어요. 가장 무거운 상자는 어느 것인가요?',ARRAY['M1-1-u4-X14','M1-1-u4-X15']::text[],true,'{"seq":19,"concept":"M1-1-u4-C7","difficulty":3,"kind":"mc","stem":"저울 두 개로 상자 세 개를 견주었어요. 가장 무거운 상자는 어느 것인가요?","options":[{"t":"㉰","correct":true},{"t":"㉯","mis":"M1-1-u4-X14"},{"t":"㉮","mis":"M1-1-u4-X15"}],"explanation":["첫째 저울에서 ㉰가 ㉯보다 무거워요.","둘째 저울에서 ㉰가 ㉮보다 무거워요.","㉰가 둘 다보다 무거우니 가장 무거워요."],"asset":{"type":"balance","scales":[{"l":{"icon":"📦","name":"㉯"},"r":{"icon":"📦","name":"㉰"},"down":"r"},{"l":{"icon":"📦","name":"㉰"},"r":{"icon":"📦","name":"㉮"},"down":"l"}]},"variant_rule":{"cmp4":{"ask":"most","names":[["㉮","㉯","㉰"]]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_d#20','math',1,1,'u4','','g1_1_math_u4_review_d','unit_review','M1-1-u4-C4',3,'mc','auto','같은 컵으로 물을 퍼서 그릇을 가득 채웠어요. ㉮는 4컵, ㉯는 8컵, ㉰는 3컵이 들어갔어요. 가장 많이 담을 수 있는 그릇은 어느 것인가요?',ARRAY['M1-1-u4-X08','M1-1-u4-X15']::text[],true,'{"seq":20,"concept":"M1-1-u4-C4","difficulty":3,"kind":"mc","stem":"같은 컵으로 물을 퍼서 그릇을 가득 채웠어요. ㉮는 4컵, ㉯는 8컵, ㉰는 3컵이 들어갔어요. 가장 많이 담을 수 있는 그릇은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉰","mis":"M1-1-u4-X08"},{"t":"㉮","mis":"M1-1-u4-X15"}],"explanation":["같은 컵으로 퍼 담았으니 컵 수로 견줄 수 있어요.","8컵이 가장 많아요.","가장 높은 그릇이 아니라 ㉯에 가장 많이 담을 수 있어요."],"asset":{"type":"cups","items":[{"label":"㉮","w":2,"h":4,"fill":0},{"label":"㉯","w":4,"h":4,"fill":0},{"label":"㉰","w":1,"h":6,"fill":0}]},"variant_rule":{"cmp4":{"ask":"most","by":"cap"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_d#21','math',1,1,'u4','','g1_1_math_u4_review_d','unit_review','M1-1-u4-C6',3,'error','auto','친구들이 비교하는 말을 했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M1-1-u4-X13','M1-1-u4-X12']::text[],false,'{"seq":21,"concept":"M1-1-u4-C6","difficulty":3,"kind":"error","stem":"친구들이 비교하는 말을 했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서아: 수박이 참외보다 더 무거우면 참외도 수박보다 더 무거워요.","correct":true,"mis_target":"M1-1-u4-X13"},{"t":"하루: 참외는 수박보다 더 가벼워요.","mis":"M1-1-u4-X13"},{"t":"유나: 수박은 참외보다 더 무거워요.","mis":"M1-1-u4-X12"}],"explanation":["수박이 더 무거우면","참외는 수박보다 더 가벼워요.","서아가 반대말로 바꾸지 않았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_d#22','math',1,1,'u4','','g1_1_math_u4_review_d','unit_review','M1-1-u4-C2',3,'error','auto','친구들이 무게에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M1-1-u4-X05','M1-1-u4-X04']::text[],false,'{"seq":22,"concept":"M1-1-u4-C2","difficulty":3,"kind":"error","stem":"친구들이 무게에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서아: 들었을 때 위로 올라가는 손에 무거운 것이 있어.","correct":true,"mis_target":"M1-1-u4-X05"},{"t":"지우: 무거운 것을 든 손이 아래로 내려가.","mis":"M1-1-u4-X05"},{"t":"도이: 크기가 같아도 무게는 다를 수 있어.","mis":"M1-1-u4-X04"}],"explanation":["무게는 크기나 높이로 정해지지 않아요.","양손에 들거나 저울에서 내려간 쪽을 봐요.","그래서 그 친구의 말이 잘못되었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_d#23','math',1,1,'u4','','g1_1_math_u4_review_d','unit_review','M1-1-u4-C7',4,'mc','auto','㉱에는 ㉯보다, ㉯에는 ㉮보다, ㉮에는 ㉰보다 더 많이 담을 수 있어요. 가장 적게 담을 수 있는 것은 어느 것인가요?',ARRAY['M1-1-u4-X14','M1-1-u4-X15']::text[],false,'{"seq":23,"concept":"M1-1-u4-C7","difficulty":4,"kind":"mc","stem":"㉱에는 ㉯보다, ㉯에는 ㉮보다, ㉮에는 ㉰보다 더 많이 담을 수 있어요. 가장 적게 담을 수 있는 것은 어느 것인가요?","options":[{"t":"㉰","correct":true},{"t":"㉮","mis":"M1-1-u4-X14"},{"t":"㉱","mis":"M1-1-u4-X15"}],"explanation":["㉱ > ㉯ > ㉮ > ㉰ 예요.","많이 담는 차례로 늘어놓으면 맨 끝은 ㉰예요.","가장 적게 담을 수 있는 것은 ㉰예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_d#24','math',1,1,'u4','','g1_1_math_u4_review_d','unit_review','M1-1-u4-C3',4,'mc','auto','큰 타일 1장은 작은 타일 2장과 넓이가 같아요. ㉮는 큰 타일 3장, ㉯는 작은 타일 6장으로 빈틈없이 덮였어요. 알맞은 말은 어느 것인가요?',ARRAY['M1-1-u4-X16']::text[],false,'{"seq":24,"concept":"M1-1-u4-C3","difficulty":4,"kind":"mc","stem":"큰 타일 1장은 작은 타일 2장과 넓이가 같아요. ㉮는 큰 타일 3장, ㉯는 작은 타일 6장으로 빈틈없이 덮였어요. 알맞은 말은 어느 것인가요?","options":[{"t":"넓이가 같아요","correct":true},{"t":"㉯","mis":"M1-1-u4-X16"},{"t":"㉮","mis":"M1-1-u4-X16"}],"explanation":["큰 타일 3장은 작은 타일 6장만큼이에요.","㉮도 ㉯도 작은 타일 6장만큼이에요.","타일 수가 달라도 넓이는 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u4_review_d#25','math',1,1,'u4','','g1_1_math_u4_review_d','unit_review','M1-1-u4-C5',4,'essay','teacher','양동이와 물병이 있어요. 담을 수 있는 양이 어느 쪽이 더 많은지 알아보는 방법과, 지금 담긴 양을 견주는 방법을 각각 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"M1-1-u4-C5","difficulty":4,"kind":"essay","stem":"양동이와 물병이 있어요. 담을 수 있는 양이 어느 쪽이 더 많은지 알아보는 방법과, 지금 담긴 양을 견주는 방법을 각각 쓰세요.","answer_guide":{"answer":"담을 수 있는 양: 한쪽에 물을 가득 담아 다른 쪽에 부어 넘치는지 남는지 본다. 담긴 양: 두 그릇의 물을 같은 크기의 컵들에 옮겨 담아 컵 수를 견준다.","scoring_points":["담을 수 있는 양(그릇 크기)과 담긴 양(들어 있는 물)을 나누어 말했는가","그림이나 예와 맞게 판단했는가","어떻게 확인할지(옮겨 부어 보기 등) 말했는가"]},"explanation":["담을 수 있는 양은 그릇에 가득 채운 양이에요.","담긴 양은 지금 들어 있는 물의 양이에요.","두 양을 섞지 말고 따로 따져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
